/* Les remarques : ce qu'un manuel ne dit jamais, sur un mot ou une phrase. Une entrée par
   mot ou phrase, sous son néerlandais tel que le lexique l'écrit, jetons non remplis ; la
   valeur est une paire { fr, en }, où en vaut null quand la remarque ne parle qu'au
   français (septante, nonante). build() (src/content/index.js) la pose sur l'élément, au
   champ note. Merge des genres explanations-be et explanations récrit ce fichier. */
NL.content.byDutch = NL.content.byDutch || {};
NL.content.byDutch['notes'] = {
  'Aangenaam.': { fr: 'Le mot seul suffit ; la forme complète est « aangenaam kennis te maken ».', en: 'The word alone is enough; the full form is “aangenaam kennis te maken”.' },
  'Allerheiligen': { fr: 'Sans article : « Allerheiligen » tombe le 1er novembre.', en: 'No article: “Allerheiligen” falls on November 1.' },
  'België': { fr: 'Sans article : « in België » (en Belgique).', en: 'No article: “in België” (in Belgium).' },
  'Brussel': { fr: 'Sans article : « in Brussel » (à Bruxelles). L’habitant est « de Brusselaar ».', en: 'No article: “in Brussel” (in Brussels). An inhabitant is “de Brusselaar”.' },
  'Dat duurt een half uur.': { fr: '« Een half uur » dure 30 minutes, alors que « half acht » est une heure : 7h30.', en: '“Een half uur” lasts 30 minutes, while “half acht” is a time of day: 7.30.' },
  'Dat is goed, merci.': { fr: 'Une phrase flamande parfaitement naturelle, avec un mot français dedans.', en: 'A perfectly natural Flemish sentence, with a French word in it.' },
  'Dat is klaar.': { fr: '« Klaar » reste invariable : « Dat is klaar », « Ze zijn klaar ».', en: '“Klaar” never changes: “Dat is klaar”, “Ze zijn klaar”.' },
  'Dat is lekker.': { fr: '« Da’s » contracte « dat is » : on l’entend partout en Flandre, et on écrit « dat is ».', en: '“Da’s” runs “dat is” together: you hear it all over Flanders, and write “dat is”.' },
  'Dat is te duur voor mij.': { fr: '« Te » devant un adjectif veut dire trop : « te duur », « te laat ».', en: '“Te” before an adjective means too: “te duur”, “te laat”.' },
  'Dat was plezant.': { fr: '« Da » est « dat » sans le t final, comme on le dit en Flandre. « Plezant » y est un mot courant pour dire que c’était agréable.', en: '“Da” is “dat” without the final t, as said in Flanders. “Plezant” is an everyday word there for something enjoyable.' },
  'De buren zijn heel vriendelijk.': { fr: '« Heel » est le très de tous les jours en néerlandais ; il veut aussi dire entier.', en: '“Heel” is the everyday Dutch word for very; it also means whole.' },
  'De testen draaien nog.': { fr: 'Pluriel « testen », mais « tests » se dit aussi ; « testen » est aussi le verbe (tester).', en: 'Plural “testen”, but “tests” is right too; “testen” is also the verb (to test).' },
  'De trein heeft tien minuten vertraging.': { fr: 'Le néerlandais dit que le train « heeft » du retard. Rien entre « tien minuten » et « vertraging » : jamais « van ».', en: 'Dutch says the train “heeft” a delay. Nothing sits between “tien minuten” and “vertraging”: never “van”.' },
  'Dit is mijn vrouw.': { fr: 'Pour présenter quelqu’un, on dit « dit is », même avec un mot « de » comme « vrouw » : « dit is mijn vrouw », pas « deze is mijn vrouw ».', en: 'To introduce someone, you say “dit is”, even with a “de” word like “vrouw”: “dit is mijn vrouw”, not “deze is mijn vrouw”.' },
  'Duits': { fr: 'Nomme la langue (« het Duits », neutre) et l’adjectif.', en: 'Names the language (“het Duits”, neuter) and the adjective.' },
  'Duitsland': { fr: 'Sans article ; « naar Duitsland » dit la direction, « in Duitsland » le lieu.', en: 'No article; “naar Duitsland” gives the direction, “in Duitsland” the place.' },
  'Een goed weekend nog!': { fr: 'Ici, « nog » ne veut pas dire encore : il vise le temps qui reste, comme dans « nog een fijne dag » (bonne fin de journée). Sans lui : « Een goed weekend! ».', en: 'Here “nog” does not mean again: it looks to the time still ahead, as in “nog een fijne dag” (enjoy the rest of your day). Without it: “Een goed weekend!”.' },
  'Een half wit, gesneden alstublieft.': { fr: 'Apprends-la mot pour mot et la boulangerie cesse d’être effrayante.', en: 'Learn it word for word and the bakery stops being frightening.' },
  'Een pintje, alstublieft.': { fr: 'Faux ami : un « pintje » est un petit verre de bière pression, pas une pinte.', en: 'False friend: a “pintje” is a small glass of draught beer, not a pint.' },
  'Eerst werk ik, daarna kook ik.': { fr: 'Commence par autre chose que le sujet et le verbe reste quand même en deuxième position.', en: 'Start with something other than the subject and the verb still stays in second position.' },
  'Engeland': { fr: 'Sans article ; l’adjectif est « Engels ». Au sens strict, l’Angleterre, mais se dit souvent de tout le Royaume-Uni.', en: 'No article; the adjective is “Engels”. Strictly England, but often said for the whole UK.' },
  'Er ligt een pakje bij de buren.': { fr: '« Ligt » (littéralement couché) se dit d’un objet posé ; « bij de buren » veut dire chez les voisins.', en: '“Ligt” (literally lying) is used for an object that lies somewhere; “bij de buren” means at the neighbours’.' },
  'Europa': { fr: 'Sans article : « in Europa » (en Europe). L’adjectif est « Europees ».', en: 'No article: “in Europa” (in Europe). The adjective is “Europees”.' },
  'Frankrijk': { fr: 'Sans article : « in Frankrijk » (en France). Vers la France : « naar Frankrijk ».', en: 'No article: “in Frankrijk” (in France). To France is “naar Frankrijk”.' },
  'Ga rechtdoor en dan links.': { fr: 'Un seul « Ga » sert les deux étapes : « Ga rechtdoor en dan links ». À « u », on dit « Gaat u rechtdoor ».', en: 'One “Ga” serves both steps: “Ga rechtdoor en dan links”. To “u”, you say “Gaat u rechtdoor”.' },
  'Heeft u dat in een andere maat?': { fr: '« Hebde » est « hebt ge » collé : la fin est le « ge » flamand, là où les Pays-Bas disent « heeft u » ou « heb je ».', en: '“Hebde” is “hebt ge” run together: the end is the Flemish “ge”, where the Netherlands says “heeft u” or “heb je”.' },
  'Heeft u een voorschrift nodig?': { fr: 'Avec « u », un Flamand dit « Hebt u » et non « Heeft u » comme aux Pays-Bas. C’est la forme polie du cabinet et du guichet.', en: 'With “u” a Fleming says “Hebt u” where the Netherlands says “Heeft u”. It is the polite form at the surgery and the counter.' },
  'Het gaat al wat beter.': { fr: '« ’t » remplace « het » et « wa » remplace « wat » : c’est la langue parlée de tous les jours en Flandre.', en: '“’t” stands for “het” and “wa” for “wat”: this is everyday spoken Flemish.' },
  'Het is half drie.': { fr: '« Half drie » = 2h30. Trompe-toi une fois et tu rates une réunion.', en: '“Half drie” = 2.30. Get it wrong once and you miss a meeting.' },
  'Het is hier heel rustig.': { fr: 'En début de phrase, la majuscule va au mot suivant : « ’t Is », pas « ’T is ».', en: 'At the start of a sentence the capital goes on the next word: “’t Is”, not “’T is”.' },
  'Het is kwart voor acht.': { fr: 'Pour 8h15, on dit « kwart over acht » aux Pays-Bas et « kwart na acht » en Flandre.', en: 'For 8.15, the Netherlands says “kwart over acht” and Flanders “kwart na acht”.' },
  'Het regent weer.': { fr: '« ’t » est la forme parlée de « het » : « ’t huis », « ’t Regent ». Ici « weer » veut dire de nouveau, pas le temps qu’il fait.', en: '“’t” is the spoken form of “het”: “’t huis”, “’t Regent”. Here “weer” means again, not the weather.' },
  'Het was een drukke dag.': { fr: '« Een drukke dag » est une journée chargée ; « druk » se dit aussi d’une rue animée.', en: '“Een drukke dag” is a busy day; “druk” is also said of a lively street.' },
  'Hij is een collega van mij.': { fr: '« Een collega van mij » dit un collègue parmi d’autres ; attention : « van mij », pas « van mijn ».', en: '“Een collega van mij” means one colleague among several; mind “van mij”, not “van mijn”.' },
  'Hoe gaat het met de familie?': { fr: '« En hoe is ’t thuis » demande comment ça va « thuis » (à la maison) : prépare ta réponse.', en: '“En hoe is ’t thuis” asks how things are “thuis” (at home): have your answer ready.' },
  'Hoe heet je?': { fr: '« Gij » est le tu du flamand parlé, là où les Pays-Bas disent « jij ».', en: '“Gij” is the spoken Flemish word for you, where the Netherlands says “jij”.' },
  'Hoe laat is het?': { fr: '« ’t » est « het » réduit : on l’entend ainsi et on l’écrit avec l’apostrophe.', en: '“’t” is “het” reduced: you hear it that way and write it with the apostrophe.' },
  'Hoe lang duurt het?': { fr: '« Hoe lang » porte sur la durée ; pour la distance, on dit « hoe ver ».', en: '“Hoe lang” is about duration; for distance you say “hoe ver”.' },
  'Hoe oud ben je?': { fr: '« Zijde » est « zijt » et « gij » collés, là où le néerlandais dit « ben je ».', en: '“Zijde” is “zijt” and “gij” run together, where Dutch says “ben je”.' },
  'Hoe was uw weekend?': { fr: 'Les collègues posent cette question le lundi. « En » (alors) lance la question, et « ’t weekend » remplace « uw weekend ».', en: 'Colleagues ask this on Monday. “En” (so) opens the question, and “’t weekend” replaces “uw weekend”.' },
  'Hoe zeg je dat in het Nederlands?': { fr: '« Zegde » est « zegt ge » collé : la fin est le « ge » flamand, là où les Pays-Bas disent « zeg je ».', en: '“Zegde” is “zegt ge” run together: the end is the Flemish “ge”, where the Netherlands says “zeg je”.' },
  'Hoeveel is het?': { fr: '« Hoeveel is ’t » demande ce que tu dois ; pour le prix d’une chose, « wat kost dat ».', en: '“Hoeveel is ’t” asks what you owe; for the price of one thing, say “wat kost dat”.' },
  'Hoeveel kost dat?': { fr: 'Pointe l’objet du doigt : « da » (pour « dat ») suffit, pas besoin de le nommer.', en: 'Point at the object: “da” (for “dat”) is enough, you need not name it.' },
  'Ik ben Java-ontwikkelaar.': { fr: 'Un métier se dit sans article ; au travail, on dit aussi bien developer que « ontwikkelaar ».', en: 'A job is said with no article; at work, people say developer as often as “ontwikkelaar”.' },
  'Ik ben Nederlands aan het leren.': { fr: 'Dis-le tôt : les gens ralentissent au lieu de passer au français.', en: 'Say it early: people slow down instead of switching to French or English.' },
  'Ik ben allergisch voor noten.': { fr: 'Après « allergisch », la préposition est « voor » : « allergisch voor noten ».', en: 'After “allergisch” the preposition is “voor”: “allergisch voor noten”.' },
  'Ik ben er nog mee bezig.': { fr: '« ermee » se coupe autour de « nog » : « er nog mee » ; sans « nog » : « Ik ben ermee bezig ».', en: '“ermee” splits around “nog”: “er nog mee”; without “nog”: “Ik ben ermee bezig”.' },
  'Ik ben getrouwd en ik heb twee kinderen.': { fr: 'Pluriel irrégulier : « het kind » devient « de kinderen ».', en: 'Irregular plural: “het kind” becomes “de kinderen”.' },
  'Ik ben moe.': { fr: 'Contraste avec « ik heb slaap » (j’ai sommeil), qui prend « hebben » : fatigué se dit avec « zijn ».', en: 'Contrast with “ik heb slaap” (I am sleepy), which takes “hebben”: tired goes with “zijn”.' },
  'Ik ben nieuw in de straat.': { fr: 'Après « ben », « nieuw » reste invariable ; devant un nom : « een nieuwe buur », mais « een nieuw huis ».', en: 'After “ben”, “nieuw” takes no ending; before a noun: “een nieuwe buur”, but “een nieuw huis”.' },
  'Ik ben op zoek naar brood.': { fr: 'Locution « op zoek zijn naar » : « naar » introduit ce qu’on cherche, ici « brood ».', en: 'The set phrase “op zoek zijn naar”: “naar” introduces what you seek, here “brood”.' },
  'Ik ben te laat.': { fr: '« Zen » remplace « ben » à l’oral dans « ik zen » ; à l’écrit : « ik ben ».', en: '“Zen” replaces “ben” in spoken “ik zen”; in writing it is “ik ben”.' },
  'Ik ben veertig jaar.': { fr: 'Pas besoin d’ajouter « oud » à la fin.', en: 'No need to add “oud” at the end.' },
  'Ik ben ziek.': { fr: 'Le changement d’état se dit « ziek worden » : « ik word ziek » (je tombe malade).', en: 'The change of state is “ziek worden”: “ik word ziek” (I fall ill).' },
  'Ik heb de match gezien.': { fr: 'Participe irrégulier : « zien » donne « gezien ».', en: 'Irregular participle: “zien” gives “gezien”.' },
  'Ik heb een vergadering om tien uur.': { fr: 'L’heure se donne avec « om » : « om tien uur ».', en: 'The time is given with “om”: “om tien uur”.' },
  'Ik heb er geen goesting in.': { fr: 'Typiquement flamand. Utilise-le et les gens sourient.', en: 'Typically Flemish. Use it and people smile.' },
  'Ik heb honger.': { fr: 'Se dit avec « hebben », pas avec « zijn ».', en: 'Said with “hebben”, not with “zijn”.' },
  'Ik heb koorts sinds gisteren.': { fr: 'Avec « sinds », le présent : « ik heb koorts », non le parfait « ik heb koorts gehad ».', en: 'With “sinds”, the present tense: “ik heb koorts”, not the perfect “ik heb koorts gehad”.' },
  'Ik heb pijn aan mijn rug.': { fr: 'Le possessif : « mijn rug » (mon dos), là où le français met l’article ; « pijn in mijn rug » est courant aussi.', en: 'Dutch uses the possessive: “mijn rug” (my back); “pijn in mijn rug” is common too.' },
  'Ik heb tijd op dinsdag.': { fr: '« op » devant le jour ; on dit « tijd hebben » (avoir le temps).', en: '“op” goes before the day; the expression is “tijd hebben” (to have time).' },
  'Ik heet {naam}.': { fr: 'Pour demander le nom : « hoe heet u » (poli) ou « hoe heet je ».', en: 'To ask someone’s name: “hoe heet u” (formal) or “hoe heet je”.' },
  'Ik ken hier nog niet veel mensen.': { fr: 'Dans « nog nie », « nie » est « niet » dont le t final tombe à l’oral, et l’ensemble veut dire pas encore.', en: 'In “nog nie”, “nie” is “niet” with its final t dropped in speech, and the whole means not yet.' },
  'Ik kijk alleen even, merci.': { fr: 'La façon polie d’échapper à un vendeur serviable.', en: 'The polite way to escape a helpful shop assistant.' },
  'Ik kom een beetje later, sorry.': { fr: 'Le présent « Ik kom » dit le futur proche (je vais arriver), avec « komen » et non « aankomen ». « Sorry » est courant en Flandre.', en: 'The present “Ik kom” says the near future (I will arrive), with “komen”, not “aankomen”. “Sorry” is common in Flanders.' },
  'Ik kom om tien uur.': { fr: 'Le verbe reste en deuxième place : « Om tien uur kom ik » (à dix heures, je viens).', en: 'The verb stays second: “Om tien uur kom ik” (at ten o’clock I come).' },
  'Ik kom om zes uur thuis.': { fr: '« thuiskomen » se sépare : « thuis » reste en fin de phrase.', en: '“thuiskomen” is separable: “thuis” stays at the end of the sentence.' },
  'Ik moet naar het containerpark.': { fr: '« Containerpark » est le mot belge pour la déchetterie ; aux Pays-Bas : « milieustraat ».', en: '“Containerpark” is the Belgian word for the recycling centre; in the Netherlands it is “milieustraat”.' },
  'Ik moet overstappen in Dendermonde.': { fr: 'Après « moeten », le verbe séparable reste entier à l’infinitif : « overstappen », pas « stap over ». Termonde se dit « Dendermonde ».', en: 'After “moeten” the separable verb stays whole as an infinitive: “overstappen”, not “stap over”. Termonde is “Dendermonde”.' },
  'Ik neem de trein naar Brussel.': { fr: '« Naar » marque où l’on va (aller à, partir pour) ; là où l’on est, on dit « in » : « Ik woon in Brussel ».', en: '“Naar” marks where you are going; where you are, you say “in”: “Ik woon in Brussel”.' },
  'Ik neem mijn laptop mee.': { fr: '« meenemen » se sépare : « mee » part à la fin de la phrase.', en: '“meenemen” is separable: “mee” goes to the end of the sentence.' },
  'Ik spreek nog niet goed Nederlands.': { fr: 'Le mot « nog » compte : il promet que tu y travailles.', en: 'The word “nog” matters: it promises that you are working on it.' },
  'Ik sta in de file.': { fr: 'Le néerlandais dit « ik sta » (je suis debout) là où le français dit être dans les files. Excuse universellement acceptée.', en: 'Dutch says “ik sta” (I am standing) where English says stuck in traffic. A universally accepted excuse.' },
  'Ik sta om zes uur op.': { fr: 'Le préfixe « op » se détache du verbe et part à la fin de la phrase.', en: 'The prefix “op” splits off the verb and goes to the end of the sentence.' },
  'Ik stuur u een mail.': { fr: 'Le présent suffit pour un futur proche : pas besoin de « zal ».', en: 'The present tense is enough for the near future: no need for “zal”.' },
  'Ik versta een beetje Nederlands.': { fr: 'Avec « ik », le verbe reste nu : « ik versta », mais « hij verstaat ».', en: 'With “ik” the verb stays bare: “ik versta”, but “hij verstaat”.' },
  'Ik vertrek om kwart voor acht.': { fr: '« om » se met devant l’heure (à) ; huit heures et quart se dit « kwart over acht ». « vertrekken » ne se sépare pas.', en: '“om” goes before the hour (at); a quarter past eight is “kwart over acht”. “vertrekken” is not separable.' },
  'Ik voel me niet goed.': { fr: 'En Flandre on laisse tomber le t final de « niet » à l’oral : « nie ». À l’écrit, on garde « niet ».', en: 'In Flanders the final t of “niet” drops in speech: “nie”. In writing, keep “niet”.' },
  'Ik werk aan een project voor een klant.': { fr: 'On travaille « aan » un projet et « voor » un client.', en: 'You work “aan” a project and “voor” a client.' },
  'Ik werk bij {bedrijf}.': { fr: 'Les entreprises prennent « bij », jamais « in ».', en: 'Companies take “bij”, never “in”.' },
  'Ik werk vandaag van thuis.': { fr: 'On dit « van thuis » ou « thuis » seul : « Ik werk thuis ».', en: 'You say “van thuis” or “thuis” alone: “Ik werk thuis”.' },
  'Ik wil graag een afspraak maken.': { fr: 'Pour demander poliment, un Flamand dit « Ik had graag … gemaakt », là où l’on dit « Ik wil graag » aux Pays-Bas.', en: 'To ask politely a Fleming says “Ik had graag … gemaakt”, where the Netherlands says “Ik wil graag”.' },
  'Ik woon in de Kloosterstraat.': { fr: 'Une rue prend « in » : « wonen in de …straat ».', en: 'A street takes “in”, though English says on: “wonen in de …straat”.' },
  'Ik woon in {stad}.': { fr: 'Si un autre mot ouvre la phrase, le verbe passe avant le sujet : « hier woon ik ».', en: 'If another word opens the sentence, the verb comes before the subject: “hier woon ik”.' },
  'Ik zou graag een koffiekoek hebben.': { fr: 'On commande avec « ik had graag » en Flandre ; les Pays-Bas disent « ik zou graag ».', en: 'You order with “ik had graag” in Flanders; the Netherlands says “ik zou graag”.' },
  'Is dat alles?': { fr: 'C’est eux qui te le demandent. Réponse : « Ja, dat is alles ».', en: 'They are the ones who ask you. Answer: “Ja, dat is alles”.' },
  'Is het ver van hier?': { fr: 'Le « ’t » est « het », à peine prononcé. Pour la durée, demande plutôt « hoe lang duurt ’t ».', en: 'The “’t” is “het”, barely pronounced. To ask about time instead, say “hoe lang duurt ’t”.' },
  'Italië': { fr: 'Sans article ; l’adjectif est « Italiaans ».', en: 'No article; the adjective is “Italiaans”.' },
  'Ja, dat is alles, merci.': { fr: '« Merci » se dit en Flandre pour « bedankt », même au comptoir.', en: '“Merci” is said in Flanders for “bedankt”, even at the counter.' },
  'Kan ik met de kaart betalen?': { fr: '« Bancontact » est la carte de paiement belge ; aux Pays-Bas on dit « pinnen ».', en: '“Bancontact” is the Belgian payment card; in the Netherlands people say “pinnen”.' },
  'Kan ik vandaag nog langskomen?': { fr: 'Après « kan », le verbe séparable reste entier en fin de phrase : « ik kan vandaag langskomen » ; seul, il se scinde : « ik kom vandaag langs ».', en: 'After “kan”, the separable verb stays whole at the end: “ik kan vandaag langskomen”; on its own it splits: “ik kom vandaag langs”.' },
  'Kerstmis': { fr: 'Pas d’article : « met Kerstmis » (à Noël).', en: 'No article: “met Kerstmis” (at Christmas).' },
  'Kunt u dat even uitleggen?': { fr: '« Is » (pour « eens ») adoucit la demande, comme « even » ; sans eux tu sonnes sec.', en: '“Is” (for “eens”) softens the request, like “even”; without them you sound curt.' },
  'Kunt u dat herhalen?': { fr: 'On dit « nog is zeggen » (redire) plus souvent que « herhalen ».', en: 'People say “nog is zeggen” (say again) more often than “herhalen”.' },
  'Kunt u mij helpen?': { fr: '« Kunde » est « kunt ge » contracté. En Flandre, « ge » vaut pour « kunt u » comme pour « kun je » : une seule forme à retenir pour les deux.', en: '“Kunde” is “kunt ge” run together. In Flanders “ge” stands for both “kunt u” and “kun je”, so you learn one form for the two.' },
  'Kunt u wat trager spreken, alstublieft?': { fr: 'À l’oral, on dit « kunde » : « kunt ge » contracté ; « wat » adoucit la demande.', en: 'Spoken, it is “kunde”: “kunt ge” run together; “wat” softens the request.' },
  'Luxemburg': { fr: 'Sans article : « in Luxemburg » (au Luxembourg). L’orthographe diffère du français.', en: 'No article: “in Luxemburg” (in Luxembourg). The spelling differs from French.' },
  'Mag ik een zakje, alstublieft?': { fr: 'Forme polie, avec « u » : « alstublieft ». Avec « je », on dit « alsjeblieft ».', en: 'Polite form, with “u”: “alstublieft”. With “je”, you say “alsjeblieft”.' },
  'Mag ik het in het Nederlands proberen?': { fr: '« Is » (pour « eens ») adoucit la demande, et la phrase évite le passage au français.', en: '“Is” (for “eens”) softens the request, and the sentence stops the switch to French.' },
  'Mag ik twee pistolets?': { fr: '« Pistolet » est le petit pain rond belge ; aux Pays-Bas on dit « broodje ».', en: '“Pistolet” is the Belgian round roll; in the Netherlands people say “broodje”.' },
  'Mag ik uw pakje aannemen?': { fr: 'Ce qu’un voisin te demande. Réponse : « Ja, graag, merci ! »', en: 'What a neighbour asks you. Answer: “Ja, graag, merci!”' },
  'Mijn collega’s spreken allemaal Nederlands.': { fr: '« Allemaal » se place après le verbe et ne change pas.', en: '“Allemaal” goes after the verb and never changes.' },
  'Mijn dochter gaat naar school in {stad}.': { fr: 'Sans article : « naar school gaan » (aller à l’école).', en: 'No article: “naar school gaan” (to go to school).' },
  'Nederland': { fr: 'Sans article, à la différence du français : « in Nederland » (aux Pays-Bas).', en: 'No article, unlike French: “in Nederland” (in the Netherlands).' },
  'Nieuwjaar': { fr: 'Un seul mot, sans article : « met Nieuwjaar » (au Nouvel An).', en: 'One word, no article: “met Nieuwjaar” (at New Year).' },
  'Niks speciaals, en bij u?': { fr: 'Après « niks », l’adjectif prend un -s : « niks speciaals », comme « iets leuks ». Après « bij », « u » est la forme objet de « ge ».', en: 'After “niks”, the adjective takes an -s: “niks speciaals”, like “iets leuks”. After “bij”, “u” is the object form of “ge”.' },
  'Nog eens, alstublieft.': { fr: '« Asteblieft » est la forme parlée de « alstublieft », et « is » remplace « eens ».', en: '“Asteblieft” is the spoken form of “alstublieft”, and “is” stands for “eens”.' },
  'Om negen uur.': { fr: '« om » devant l’heure, et « uur » reste au singulier.', en: '“om” goes before the hour, and “uur” stays singular.' },
  'Onze zoon is zes jaar.': { fr: 'Après un nombre, « jaar » reste au singulier : « zes jaar ».', en: 'After a number, “jaar” stays singular: “zes jaar”.' },
  'Op welk spoor?': { fr: '« Het spoor » est neutre, d’où « welk » ; un mot en « de » prend « welke » : « Welke trein? ». Réponse : « Op spoor 4 ».', en: '“Het spoor” is neuter, hence “welk”; a “de” word takes “welke”: “Welke trein?”. The answer is “Op spoor 4”.' },
  'Pasen': { fr: 'Sans article : « met Pasen » (à Pâques).', en: 'No article: “met Pasen” (at Easter).' },
  'Rijdt deze bus naar Aalst?': { fr: 'Question par inversion : le verbe passe devant, « Rijdt deze bus ». Alost se dit « Aalst ».', en: 'A question formed by putting the verb first: “Rijdt deze bus”. Alost is “Aalst”.' },
  'Sinterklaas': { fr: 'Sans article. En Flandre, il apporte ses cadeaux le 6 décembre.', en: 'No article. In Flanders he brings his gifts on December 6.' },
  'Sorry, ik heb dat niet verstaan.': { fr: 'À l’oral, le « t » final tombe dans « da » et « nie » ; à l’écrit : « dat » et « niet ».', en: 'Spoken, the final “t” drops in “da” and “nie”; in writing it is “dat” and “niet”.' },
  'Sorry, mijn Nederlands is nog niet zo goed.': { fr: 'Dis-le en réunion : les collègues flamands aident au lieu de basculer.', en: 'Say it in a meeting: Flemish colleagues help instead of switching language.' },
  'Spanje': { fr: 'Sans article ; l’adjectif est « Spaans ».', en: 'No article; the adjective is “Spaans”.' },
  'Spreekt u Frans?': { fr: 'Une porte de secours, mais essaie le néerlandais d’abord.', en: 'An escape hatch, but try Dutch first.' },
  'Tot hoe laat zijn jullie open?': { fr: '« Jullie » est le vous du pluriel, informel. Poli : « Tot hoe laat bent u open ».', en: '“Jullie” is the informal plural you. Polite: “Tot hoe laat bent u open”.' },
  'Tot maandag.': { fr: 'Même schéma que « tot straks » : « tot » puis le moment, sans article.', en: 'Same pattern as “tot straks”: “tot” then the moment, with no article.' },
  'Tot straks!': { fr: 'On le dit en quittant quelqu’un qu’on reverra le jour même.', en: 'Said when leaving someone you will see again the same day.' },
  'Vlaams': { fr: 'La langue est « het Vlaams ». L’adjectif : « de Vlaamse taal », mais « een Vlaams dorp ».', en: 'The language is “het Vlaams”. The adjective: “de Vlaamse taal”, but “een Vlaams dorp”.' },
  'Vlaanderen': { fr: 'Sans article : « in Vlaanderen » (en Flandre). Le nom a l’air d’un pluriel, mais il est singulier.', en: 'No article: “in Vlaanderen” (in Flanders). It looks plural but is singular.' },
  'Voor hier of om mee te nemen?': { fr: 'Encore une question qu’on te pose, pas l’inverse.', en: 'Another question they ask you, not the other way round.' },
  'Waar is de kassa?': { fr: 'Dans la question, le verbe suit « waar » : « waar is de kassa », pas « waar de kassa is ».', en: 'In the question the verb follows “waar”: “waar is de kassa”, not “waar de kassa is”.' },
  'Waar is het gemeentehuis?': { fr: 'Le « gemeentehuis » est la maison communale, où tu déclares ton domicile.', en: 'The “gemeentehuis” is the town hall, where you register your address.' },
  'Wallonië': { fr: 'Sans article : « in Wallonië » (en Wallonie). Le tréma sépare les deux dernières voyelles.', en: 'No article: “in Wallonië” (in Wallonia). The diaeresis splits the last two vowels.' },
  'Wat betekent dat?': { fr: 'Le t final tombe : « wat » devient « wa » et « dat » devient « da ».', en: 'The final t drops: “wat” becomes “wa” and “dat” becomes “da”.' },
  'Wat doe je meestal in het weekend?': { fr: 'On dit « in ’t weekend », là où le français dit juste le week-end.', en: 'You say “in ’t weekend”, where English says at the weekend or on the weekend.' },
  'Wat een weer!': { fr: '« Amai » marque la surprise, l’admiration ou le dépit, et passe très bien au travail. La phrase vaut pour un temps superbe comme pour un temps affreux.', en: '“Amai” marks surprise, admiration or dismay, and is fine at work. The phrase fits glorious weather as well as awful weather.' },
  'We hebben gewandeld.': { fr: 'Se promener prend être, mais « wandelen » prend « hebben ». « Zijn » seulement avec destination : « we zijn naar huis gewandeld » (nous sommes rentrés à pied).', en: '“Wandelen” takes “hebben”. It takes “zijn” only with a destination: “we zijn naar huis gewandeld” (we walked home).' },
  'We spreken morgen af.': { fr: '« afspreken » se sépare : « af » part à la fin. Le présent dit ici le futur.', en: '“afspreken” is separable: “af” goes to the end. The present tense here means the future.' },
  'Wij hebben twee kinderen.': { fr: '« Wij » est appuyé ; à l’oral on dit plus souvent « we ».', en: '“Wij” is stressed; in speech people more often say “we”.' },
  'Wij wonen hier al vijf jaar.': { fr: 'Le néerlandais garde le présent, comme le français, et « al » rend depuis : « al vijf jaar » (depuis cinq ans).', en: 'Dutch keeps the present tense, and “al” does the work of for: “al vijf jaar” (for five years).' },
  'aandoen': { fr: 'Verbe séparable : « ik doe mijn jas aan ».', en: 'Separable verb: “ik doe mijn jas aan”.' },
  'aankomen': { fr: 'Verbe séparable : « Ik kom aan ». Au passé composé il se conjugue avec « zijn » : « is aangekomen ».', en: 'A separable verb: “Ik kom aan”. In the perfect it takes “zijn”: “is aangekomen”.' },
  'acht': { fr: 'Le mot des dizaines met un t devant « acht » : « tachtig » (quatre-vingts).', en: 'The tens word puts a t before “acht”: “tachtig” (eighty).' },
  'achter': { fr: '« Achter » est l’opposé de « voor » : « achter het huis » (derrière la maison).', en: '“Achter” is the opposite of “voor”: “achter het huis” (behind the house).' },
  'afspreken': { fr: 'Verbe séparable : « we spreken morgen af ». Le nom est « de afspraak ».', en: 'Separable verb: “we spreken morgen af”. The noun is “de afspraak”.' },
  'afwassen': { fr: 'Verbe à particule séparable : « ik was af ». Participe : « afgewassen ».', en: 'A separable verb: “ik was af”. Past participle: “afgewassen”.' },
  'afwerken': { fr: 'Séparable : « Ik werk het af », participe « afgewerkt ».', en: 'Separable: “Ik werk het af”, participle “afgewerkt”.' },
  'afzeggen': { fr: 'Verbe séparable : « Ik zeg de afspraak af » (j’annule le rendez-vous).', en: 'Separable verb: “Ik zeg de afspraak af” (I cancel the appointment).' },
  'al': { fr: 'Avec une durée, « al » rend depuis : « al vijf jaar » (depuis cinq ans).', en: 'With the present tense and a length of time, “al” does the work of for: “al vijf jaar” (for five years).' },
  'alle': { fr: '« Alle » précède un nom : « alle mensen ». Sans nom, on dit « allemaal » : « we komen allemaal ».', en: '“Alle” comes before a noun: “alle mensen”. Without a noun, use “allemaal”: “we komen allemaal”.' },
  'alleen': { fr: 'Deux sens, selon le contexte : « Ik ben alleen » (je suis seul), « alleen vandaag » (seulement aujourd’hui).', en: 'Two senses, by context: “Ik ben alleen” (I am alone), “alleen vandaag” (only today).' },
  'allemaal': { fr: 'Suit le pluriel : « jullie zijn allemaal moe ». « Iedereen » prend le singulier : « iedereen is moe ».', en: 'Follows a plural: “jullie zijn allemaal moe”. “Iedereen” takes the singular: “iedereen is moe”.' },
  'allergisch': { fr: 'Se construit avec « voor » : « Ik ben allergisch voor noten ».', en: 'Takes “voor”: “Ik ben allergisch voor noten”.' },
  'alles': { fr: '« Dat is alles » (c’est tout) : la réponse au comptoir quand tu as fini de commander.', en: '“Dat is alles” (that is all): the answer at the counter once you have finished ordering.' },
  'als': { fr: '« Als ik thuis ben » (quand je suis à la maison) : « als » pour le présent ou le futur. En question c’est « wanneer », au passé « toen ».', en: '“Als ik thuis ben” (when I am home): “als” for now or later. In a question it is “wanneer”, in the past “toen”.' },
  'alstublieft': { fr: '« Asteblieft » est la forme contractée qu’on entend en Flandre. Elle se dit à l’oral, tandis qu’on écrit « alstublieft ».', en: '“Asteblieft” is the run-together form you hear in Flanders. You say it, but you write “alstublieft”.' },
  'altijd': { fr: 'Se place après le verbe conjugué : « ik werk altijd ».', en: 'It goes after the conjugated verb: “ik werk altijd”.' },
  'amai': { fr: 'Le mot le plus flamand qui soit. Surprise, compassion, admiration.', en: 'The most Flemish word there is. Surprise, sympathy, admiration.' },
  'ambetant': { fr: 'Vient du français embêtant. « Ambetant » est courant à l’oral en Flandre, et « vervelend », le mot standard, s’y dit aussi.', en: 'Comes from French embêtant. “Ambetant” is common in spoken Flemish, and “vervelend”, the standard word, is said there too.' },
  'antwoorden': { fr: 'Répondre à une question : « antwoorden op » ; pour un appel, « opnemen ».', en: 'To answer a question: “antwoorden op”; for a phone call, “opnemen”.' },
  'april': { fr: 'Sans majuscule ; on dit « in april » (en avril).', en: 'No capital; you say “in april” (in April).' },
  'augustus': { fr: 'Le mois garde la finale latine, sans majuscule : « in augustus ».', en: 'The month keeps its Latin ending, with no capital: “in augustus”.' },
  'bang': { fr: '« Bang » se construit avec « voor » : « bang voor honden » (peur des chiens).', en: '“Bang” takes “voor”: “bang voor honden” (afraid of dogs).' },
  'bedoelen': { fr: '« Wat bedoel je? » (que veux-tu dire ?). « Ik bedoel het goed » (c’est pour bien faire).', en: '“Wat bedoel je?” (what do you mean?). “Ik bedoel het goed” (I mean well).' },
  'beginnen': { fr: 'Suivi d’un autre verbe : « ik begin te werken » (je commence à travailler).', en: 'Before another verb: “ik begin te werken” (I start working).' },
  'belangrijk': { fr: 'Vient de « belang » (l’intérêt, l’importance) : « belangrijk » est ce qui compte.', en: 'From “belang” (interest, importance): “belangrijk” is what matters.' },
  'bellen': { fr: 'Se construit avec ou sans « naar » : « Ik bel hem », « Ik bel naar de dokter ».', en: 'Used with or without “naar”: “Ik bel hem”, “Ik bel naar de dokter”.' },
  'beloven': { fr: 'Avec « dat » : « Ik beloof je dat ik kom ».', en: 'With “dat”: “Ik beloof je dat ik kom”.' },
  'beneden': { fr: '« Beneden » s’emploie surtout seul, à l’opposé de « boven » : « Ze zijn beneden » (ils sont en bas). Devant un nom, on dit « onder ».', en: '“Beneden” is mostly used alone, opposite “boven”: “Ze zijn beneden” (they are downstairs). Before a noun, say “onder”.' },
  'bereiken': { fr: 'Inséparable : « Ik probeer u te bereiken » (j’essaie de vous joindre).', en: 'Not separable: “Ik probeer u te bereiken” (I am trying to reach you).' },
  'beschikbaar': { fr: 'Se dit d’une personne comme d’une chose, et pour un moment libre : « Ik ben donderdag beschikbaar ».', en: 'Said of a person or a thing alike, and for a free time slot: “Ik ben donderdag beschikbaar”.' },
  'besluiten': { fr: 'Se construit avec « te » : « Ik heb besloten te gaan ».', en: 'Takes “te”: “Ik heb besloten te gaan”.' },
  'bespreken': { fr: 'Verbe fort à préfixe inséparable : « hij bespreekt », « hij heeft besproken ».', en: 'A strong verb with an inseparable prefix: “hij bespreekt”, “hij heeft besproken”.' },
  'bestellen': { fr: 'Le préfixe « be- » reste collé au verbe : « ik bestel » et « ik heb besteld ».', en: 'The prefix “be-” stays attached to the verb: “ik bestel” and “ik heb besteld”.' },
  'betalen': { fr: 'Verbe régulier : « betaalde », « betaald ». On paie par carte : « met de kaart betalen ».', en: 'A regular verb: “betaalde”, “betaald”. You pay by card: “met de kaart betalen”.' },
  'betekenen': { fr: 'Pour demander le sens d’un mot : « wat betekent dat ».', en: 'To ask what a word means: “wat betekent dat”.' },
  'beter': { fr: 'Comparatif de « goed ». Après une maladie, « beter » veut aussi dire guéri.', en: 'The comparative of “goed”. After an illness, “beter” can also mean recovered.' },
  'bevestigen': { fr: 'Inséparable : « Ik bevestig de afspraak » (je confirme le rendez-vous).', en: 'Not separable: “Ik bevestig de afspraak” (I confirm the appointment).' },
  'bewaren': { fr: 'Aussi pour enregistrer : « een bestand bewaren » (enregistrer un fichier). Garder à soi, c’est « houden ».', en: 'Also used for saving: “een bestand bewaren” (to save a file). To hold on to something is “houden”.' },
  'bezig': { fr: 'On dit « Ik ben ermee bezig » (j’y travaille) quand on te demande si c’est fini.', en: 'You say “Ik ben ermee bezig” (I am on it) when asked whether it is done.' },
  'bezoeken': { fr: 'Verbe inséparable : « ik bezoek », participe « bezocht ».', en: 'Inseparable verb: “ik bezoek”, past participle “bezocht”.' },
  'bij': { fr: '« Bij » sert aussi pour son employeur : « Ik werk bij {bedrijf} » (je travaille chez {bedrijf}).', en: '“Bij” is also used for your employer: “Ik werk bij {bedrijf}” (I work at {bedrijf}).' },
  'bijna': { fr: 'Se met juste devant le mot qu’il nuance : « bijna klaar ».', en: 'Goes right before the word it qualifies: “bijna klaar”.' },
  'binnen': { fr: 'Lieu : « Ik ben binnen » ; mouvement : « naar binnen gaan » ; verbe séparable : « Kom binnen ! ».', en: 'Place: “Ik ben binnen”; movement: “naar binnen gaan”; separable verb: “Kom binnen!”.' },
  'blauw': { fr: '« Een blauwe broek », mais après « een » devant un mot en « het » : « een blauw hemd ».', en: '“Een blauwe broek”, but after “een” before a “het” word: “een blauw hemd”.' },
  'blij': { fr: '« Blij » dit la joie du moment : « ik ben blij ». « Gelukkig » dit un bonheur plus profond.', en: '“Blij” is joy in the moment: “ik ben blij”. “Gelukkig” is a deeper happiness.' },
  'blijven': { fr: 'Devant un verbe, il veut dire continuer : « ik blijf wachten » (je continue d’attendre).', en: 'Before a verb, it means keep on doing: “ik blijf wachten” (I keep waiting).' },
  'bloeden': { fr: 'Au passé composé, avec « hebben » : « hij heeft gebloed ».', en: 'In the perfect it takes “hebben”: “hij heeft gebloed”.' },
  'boos': { fr: '« Boos » se construit avec « op » : « boos op iemand » (fâché contre quelqu’un).', en: '“Boos” takes “op”: “boos op iemand” (angry at someone).' },
  'boven': { fr: '« Boven » ne touche pas l’objet, contrairement à « op » : « boven de tafel » (au-dessus de la table).', en: '“Boven” does not touch the thing, unlike “op”: “boven de tafel” (above the table).' },
  'breed': { fr: 'Devient « brede » devant un nom, le double e perdant une lettre : « een brede rivier », mais « een breed pad » (mot « het » après « een »).', en: 'Becomes “brede” before a noun, the double e losing a letter: “een brede rivier”, but “een breed pad” (a “het” word after “een”).' },
  'brengen': { fr: '« Brengen » : porter quelque chose jusqu’à quelqu’un ; aller le chercher se dit « halen ».', en: '“Brengen”: carry something to someone; going to get it is “halen”.' },
  'bruin': { fr: '« De bruine laarzen », mais après « een » devant un mot en « het » : « een bruin hemd ».', en: '“De bruine laarzen”, but after “een” before a “het” word: “een bruin hemd”.' },
  'buiten': { fr: 'Pour aller dehors, on dit « naar buiten ».', en: 'To go outside, say “naar buiten”.' },
  'cash': { fr: 'Se dit avec « betalen » : « cash betalen » (payer en liquide), mot venu de l’anglais.', en: 'Used with “betalen”: “cash betalen” (to pay cash), a word from English.' },
  'daar': { fr: 'Le mot « er » est le « daar » atone, un peu comme le y français : « ik woon er » (j’y habite).', en: '“Er” is the unstressed “daar”, much like the French y: “ik woon er” (I live there).' },
  'daarna': { fr: 'En tête de phrase, le verbe suit aussitôt : « daarna kook ik ».', en: 'At the start of a sentence, the verb follows at once: “daarna kook ik”.' },
  'daarom': { fr: 'Ouvre la phrase, donc le verbe vient juste après : « Daarom ga ik ».', en: 'Opens the sentence, so the verb comes right after: “Daarom ga ik”.' },
  'dag': { fr: 'À l’entrée comme à la sortie. À ne pas confondre avec « de dag », le jour.', en: 'On the way in and on the way out. Not to be confused with “de dag”, the day.' },
  'dan': { fr: 'Marque l’étape suivante, et compare aussi : « groter dan ».', en: 'Marks the next step, and also compares: “groter dan”.' },
  'dank u wel': { fr: 'En Flandre, « merci » est du néerlandais normal, pas du français. Utilise-le sans hésiter.', en: 'In Flanders, “merci” is normal Dutch, not French. Use it without hesitating.' },
  'dansen': { fr: 'Verbe régulier : « ik dans », « ik heb gedanst ».', en: 'A regular verb: “ik dans”, “ik heb gedanst”.' },
  'dat': { fr: 'Introduit une subordonnée, donc le verbe part à la fin : « Ik weet dat hij komt ».', en: 'Opens a subordinate clause, so the verb goes last: “Ik weet dat hij komt”.' },
  'de Belg': { fr: 'Le pluriel est « Belgen » ; une Belge est « een Belgische ».', en: 'Plural “Belgen”; a Belgian woman is “een Belgische”.' },
  'de aardappel': { fr: 'Prend « de ». Pluriel : « aardappels ».', en: 'Takes “de”. Plural: “aardappels”.' },
  'de afdeling': { fr: 'Un nom en « -ing » tiré d’un verbe prend « de » : « de afdeling », pluriel « de afdelingen ».', en: 'A noun in “-ing” made from a verb takes “de”: “de afdeling”, plural “de afdelingen”.' },
  'de afspraak': { fr: 'Pluriel « afspraken » ; vaut pour un rendez-vous médical comme pour un accord conclu.', en: 'Plural “afspraken”; covers a doctor’s appointment as well as an agreement made.' },
  'de agenda': { fr: 'Avec « de ». Sert aussi pour l’ordre du jour d’une réunion.', en: 'Takes “de”. Also used for a meeting’s list of topics.' },
  'de ajuin': { fr: 'Prend « de » ; pluriel : « ajuinen ».', en: 'Takes “de”; plural: “ajuinen”.' },
  'de ambulance': { fr: 'Le pluriel prend « -s » : « de ambulances ».', en: 'The plural takes “-s”: “de ambulances”.' },
  'de apotheek': { fr: '« De apotheker » est la personne qui travaille à « de apotheek ».', en: '“De apotheker” is the person who works at “de apotheek”.' },
  'de appel': { fr: 'Prend « de ». Le pluriel ajoute un s : « appels ».', en: 'Takes “de”. The plural adds an s: “appels”.' },
  'de auto': { fr: 'Toujours « de auto », jamais « het ». Le pluriel prend une apostrophe : « de auto’s ».', en: 'Always “de auto”, never “het”. The plural takes an apostrophe: “de auto’s”.' },
  'de avond': { fr: '« vanavond » veut dire ce soir : « vanavond werk ik niet ».', en: '“vanavond” means this evening: “vanavond werk ik niet”.' },
  'de baas': { fr: 'Pluriel : « bazen ». Pour une femme, on dit « de bazin » (« mijn bazin »).', en: 'The plural is “bazen”. For a woman, say “de bazin” (“mijn bazin”).' },
  'de baby': { fr: 'Le pluriel est « baby’s », avec une apostrophe.', en: 'The plural is “baby’s”, with an apostrophe.' },
  'de badkamer': { fr: 'La salle de bain n’a souvent pas de toilettes : elles sont à part, dans « het toilet ».', en: 'The bathroom often has no toilet: that is a separate room, “het toilet”.' },
  'de bagage': { fr: 'Se met au singulier : « mijn bagage » (mes bagages).', en: 'Used in the singular: “mijn bagage” (my luggage).' },
  'de bakker': { fr: 'Désigne aussi la boulangerie : « naar de bakker gaan ».', en: 'Also means the bakery itself: “naar de bakker gaan”.' },
  'de bank': { fr: '« De bank » est aussi le banc ; le canapé, c’est « de zetel ». Pluriel : « de banken ».', en: '“De bank” is also a bench; a sofa is “de zetel”. Plural: “de banken”.' },
  'de batterij': { fr: 'Avec « de ». Batterie à plat : « mijn batterij is leeg ».', en: 'Takes “de”. A flat battery: “mijn batterij is leeg”.' },
  'de beenhouwer': { fr: 'Mot flamand. Le nord dit « slager », que la Flandre comprend aussi.', en: 'A Flemish word. The north says “slager”, which Flanders understands too.' },
  'de berg': { fr: 'On dit « naar de bergen » (à la montagne) au pluriel.', en: 'Said in the plural: “naar de bergen” (to the mountains).' },
  'de bibliotheek': { fr: 'Le mot s’écrit « de bibliotheek », pluriel « de bibliotheken ».', en: 'The word is spelled “de bibliotheek”, plural “de bibliotheken”.' },
  'de bloem': { fr: 'Pluriel : « bloemen ».', en: 'Plural: “bloemen”.' },
  'de bon': { fr: '« Kasticket » est le ticket de caisse ; « bon » sert aussi pour un bon d’achat.', en: '“Kasticket” is the till receipt; “bon” also serves for a voucher.' },
  'de boodschap': { fr: 'Avec « de ». Au pluriel, « boodschappen » veut dire les courses.', en: 'Takes “de”. In the plural, “boodschappen” means the shopping.' },
  'de boom': { fr: 'Pluriel : « bomen ». Avec « de ».', en: 'Plural: “bomen”. Takes “de”.' },
  'de boot': { fr: 'Pluriel « boten ». Le diminutif « het bootje » est neutre.', en: 'Plural “boten”. The diminutive “het bootje” is neuter.' },
  'de boter': { fr: 'Nom en « de ». « Boterham » (la tartine) vient de « boter » et se dit de toute tranche de pain, beurrée ou non.', en: 'A “de” noun. “Boterham” (a slice of bread) comes from “boter” and means any slice, buttered or not.' },
  'de brand': { fr: 'Un incendie, pas un simple feu : « het vuur » est le feu en général.', en: 'A blaze, not just any fire: “het vuur” is fire in general.' },
  'de brandweer': { fr: 'Le verbe reste au singulier : « de brandweer komt » ; un pompier se dit « de brandweerman ».', en: 'The verb stays singular: “de brandweer komt”; one firefighter is “de brandweerman”.' },
  'de brievenbus': { fr: 'Composé de « brief » (lettre) et de « bus » (boîte) : le dernier mot donne « de ». Pluriel : « de brievenbussen ».', en: 'Made of “brief” (letter) and “bus” (box), so the last word gives “de”. Plural: “de brievenbussen”.' },
  'de broek': { fr: 'Un seul pantalon : « de broek » ; plusieurs : « de broeken ».', en: 'One pair is “de broek”; several are “de broeken”.' },
  'de broer': { fr: 'Pluriel : « broers ». « De broeder » est le frère religieux.', en: 'The plural is “broers”. “De broeder” is a religious brother.' },
  'de brug': { fr: 'Pluriel avec le « g » doublé : « de bruggen ».', en: 'Plural with the “g” doubled: “de bruggen”.' },
  'de buik': { fr: '« De buik » est le ventre ; l’estomac, l’organe, se dit « de maag ».', en: '“De buik” is the belly; the stomach as an organ is “de maag”.' },
  'de buren': { fr: 'Pluriel de « de buur » : il vaut pour des hommes, des femmes ou un groupe mixte.', en: 'Plural of “de buur”: it covers men, women or a mixed group.' },
  'de bus': { fr: 'Le pluriel double le « s » : « de bussen ». Pour le moyen de transport : « met de bus » (« Ik kom met de bus »).', en: 'The plural doubles the “s”: “de bussen”. For the means of transport, say “met de bus” (“Ik kom met de bus”).' },
  'de bushalte': { fr: 'Composé de « de halte » : article « de » ; pluriel « de bushaltes ».', en: 'Built on “de halte”: article “de”; plural “de bushaltes”.' },
  'de buurman': { fr: 'Au pluriel, on dit plutôt « de buren », pour les hommes comme pour les femmes.', en: 'The plural is usually “de buren”, for men and women alike.' },
  'de buurt': { fr: '« De buurt » est le voisinage proche, où l’on se connaît ; « de wijk » est le quartier comme division de la ville.', en: '“De buurt” is the close surroundings, where people know each other; “de wijk” is the neighbourhood as a division of the town.' },
  'de buurvrouw': { fr: 'Pluriel : « de buurvrouwen » ; pour un groupe mixte, on dit « de buren ».', en: 'Plural: “de buurvrouwen”; for a mixed group, say “de buren”.' },
  'de camping': { fr: '« De camping » est le terrain ; l’activité se dit avec le verbe « kamperen ».', en: '“De camping” is the site; the activity is the verb “kamperen”.' },
  'de choco': { fr: 'En Flandre, « choco » désigne seulement la pâte à tartiner ; le chocolat se dit « chocolade ».', en: 'In Flanders “choco” means only the spread; chocolate itself is “chocolade”.' },
  'de chocolade': { fr: 'Prend « de » ; non dénombrable, sans pluriel courant.', en: 'Takes “de”; it is uncountable, with no usual plural.' },
  'de cinema': { fr: 'Prend « de » : « de cinema », sans accent.', en: 'Takes “de”: “de cinema”, with no accent.' },
  'de code': { fr: 'Pas d’article partitif en néerlandais : « Ik schrijf code » (je programme).', en: 'No article is needed here: “Ik schrijf code” (I am programming).' },
  'de cola': { fr: 'Prend « de » ; « een cola » désigne un verre ou une canette.', en: 'Takes “de”; “een cola” means one glass or one can.' },
  'de collega': { fr: 'Pluriel « collega’s », avec une apostrophe. Même mot pour un homme et une femme.', en: 'Plural “collega’s”, with an apostrophe. Same word for a man and a woman.' },
  'de computer': { fr: 'Prend « de » : « de computer », pluriel « de computers ».', en: 'Takes “de”: “de computer”, plural “de computers”.' },
  'de crèche': { fr: 'Mot emprunté au français, mais avec « de », et il se prononce à la française.', en: 'Borrowed from French, but with “de”, and pronounced the French way.' },
  'de dag': { fr: 'Pluriel « dagen » : « drie dagen ».', en: 'The plural is “dagen”: “drie dagen”.' },
  'de dame': { fr: 'Pour parler d’une dame, pas pour l’appeler : on dit « mevrouw » en lui parlant.', en: 'For talking about a lady, not to her: you say “mevrouw” when addressing her.' },
  'de databank': { fr: 'La Flandre dit volontiers « databank » là où le nord dit « database ».', en: 'Flanders is happy to say “databank” where the north says “database”.' },
  'de datum': { fr: 'Question usuelle : « Welke datum is het vandaag? » (quelle est la date aujourd’hui ?).', en: 'Common question: “Welke datum is het vandaag?” (what is the date today?).' },
  'de deadline': { fr: 'Le verbe qui va avec : « de deadline halen » (tenir le délai).', en: 'The verb that goes with it: “de deadline halen” (meet the due date).' },
  'de deur': { fr: 'Mot en « de » ; le pluriel est « de deuren ».', en: 'A “de” word, and the plural is “de deuren”.' },
  'de directeur': { fr: 'Le directeur de l’école ; au féminin, « de directrice ». Pluriel « de directeurs ».', en: 'The head of a school; the woman is “de directrice”. The plural is “de directeurs”.' },
  'de dochter': { fr: 'Pluriel « dochters ». « Dochter » prend « de ».', en: 'Plural “dochters”. “Dochter” takes “de”.' },
  'de dokter': { fr: 'On s’adresse au médecin en disant « dokter ». En Flandre le généraliste se dit aussi « huisdokter ».', en: 'You address the doctor as “dokter”. In Flanders the family doctor is also called “huisdokter”.' },
  'de dorst': { fr: 'Se construit avec « hebben » et sans article : « ik heb dorst » (j’ai soif).', en: 'Built with “hebben” and no article: “ik heb dorst” (I am thirsty).' },
  'de douane': { fr: 'S’emploie au singulier : « bij de douane » (à la douane).', en: 'Used in the singular: “bij de douane” (at customs).' },
  'de douche': { fr: '« De douche » : article « de ». Pluriel « de douches ».', en: '“De douche”: article “de”. Plural “de douches”.' },
  'de drank': { fr: 'Avec « de » : « de drank ». Le pluriel est « de dranken ».', en: 'Takes “de”: “de drank”. The plural is “de dranken”.' },
  'de eend': { fr: 'Pluriel : « eenden ». Avec « de ».', en: 'Plural: “eenden”. Takes “de”.' },
  'de eieren': { fr: 'Pluriel de « het ei », neutre ; on dit « twee eieren ».', en: 'Plural of “het ei”, which is neuter; one says “twee eieren”.' },
  'de euro': { fr: 'Pluriel « euro’s », mais après un chiffre on garde « euro » : « vijf euro ».', en: 'Plural “euro’s”, but after a number it stays “euro”: “vijf euro”.' },
  'de ex': { fr: 'Le pluriel est « exen ».', en: 'The plural is “exen”.' },
  'de factuur': { fr: 'Pluriel à retenir : « de factuur », « de facturen ».', en: 'Plural to remember: “de factuur”, “de facturen”.' },
  'de feedback': { fr: 'Emprunt à l’anglais, mais l’article est « de » : « de feedback ».', en: 'An English loan, but the article is “de”: “de feedback”.' },
  'de feestdag': { fr: 'Mot composé : « de dag » donne l’article, donc « de feestdag ».', en: 'A compound: “de dag” gives the article, so “de feestdag”.' },
  'de fiets': { fr: '« Velo », venu du français, est courant à l’oral en Flandre ; « fiets », le mot standard, s’y dit aussi.', en: '“Velo”, a word from French, is common in spoken Flemish; “fiets”, the standard word, is said there too.' },
  'de file': { fr: 'Obsession nationale et sujet de conversation sans risque : « Ik sta in de file ». C’est « de », pas « het ».', en: 'A national obsession and a safe topic of conversation: “Ik sta in de file”. It is “de”, not “het”.' },
  'de film': { fr: 'Le pluriel prend un « -s » : « de films ».', en: 'The plural takes an “-s”: “de films”.' },
  'de fles': { fr: 'L’article est « de » : « de fles ». Le pluriel est « de flessen », avec deux s.', en: 'The article is “de”: “de fles”. The plural is “de flessen”, with a double s.' },
  'de fooi': { fr: 'On donne « een fooi » au serveur. Le pluriel est « de fooien ».', en: 'You give the waiter “een fooi”. The plural is “de fooien”.' },
  'de foto': { fr: 'Prend « de » ; pluriel « de foto’s ».', en: 'Takes “de”; plural “de foto’s”.' },
  'de fout': { fr: '« Bug » désigne une erreur de logiciel ; « fout » sert pour toute autre erreur.', en: '“Bug” means a software error; “fout” serves for any other mistake.' },
  'de frieten': { fr: 'Toujours au pluriel en Flandre ; le nord dit « patat ».', en: 'Always plural in Flanders; the north says “patat”.' },
  'de frigo': { fr: 'Le mot de Flandre : « de frigo ». « De koelkast » est la forme du Nord, qu’on comprend aussi.', en: 'The Flemish word: “de frigo”. “De koelkast” is the northern form, understood too.' },
  'de fuif': { fr: '« De fuif » est le mot belge pour une soirée dansante de jeunes ; « het feest » est le mot général.', en: '“De fuif” is the Belgian word for a young people’s dance party; “het feest” is the general word.' },
  'de gang': { fr: '« De gang » : article « de ». Pluriel « de gangen ».', en: '“De gang”: article “de”. Plural “de gangen”.' },
  'de garage': { fr: 'Même mot qu’en français, mais avec « de » ; pluriel : « de garages ».', en: 'Same word as in French, with “de”; plural: “de garages”.' },
  'de gast': { fr: 'Familier pour un gars, mais aussi l’invité ; pluriel « gasten ».', en: 'Informal for a guy, but also the guest; plural “gasten”.' },
  'de gemeente': { fr: 'Le bâtiment s’appelle « het gemeentehuis », la commune elle-même « de gemeente ».', en: 'The building is “het gemeentehuis”, the municipality itself “de gemeente”.' },
  'de gids': { fr: 'Pluriel « gidsen ». Le livre se dit « de reisgids ».', en: 'Plural “gidsen”. The guidebook is “de reisgids”.' },
  'de grens': { fr: 'Le pluriel est « grenzen », avec un z.', en: 'The plural is “grenzen”, with a z.' },
  'de groenten': { fr: '« De groenten » est le pluriel ; au singulier, « de groente » s’emploie aussi comme non dénombrable.', en: '“De groenten” is the plural; “de groente” is also used as an uncountable.' },
  'de gsm': { fr: 'Le mot courant en Flandre pour le portable, toujours avec « de ».', en: 'The usual word in Flanders for a mobile phone, always with “de”.' },
  'de halte': { fr: '« De halte » est l’arrêt d’un « bus » ou d’un « tram » ; pour le train, on dit « het station ».', en: '“De halte” is a stop for a “bus” or a “tram”; for the train you say “het station”.' },
  'de hand': { fr: 'Le pluriel est « handen », avec la terminaison « -en ».', en: 'The plural is “handen”, with the ending “-en”.' },
  'de handschoenen': { fr: 'Littéralement « hand » et « schoen », d’où « de handschoen » au singulier.', en: 'Literally “hand” and “schoen”, hence “de handschoen” in the singular.' },
  'de haven': { fr: 'Pluriel « havens ». Se dit « in de haven » (dans le port).', en: 'Plural “havens”. Said “in de haven” (in the port).' },
  'de helft': { fr: 'Suivi de « van » : « de helft van de klas ».', en: 'Followed by “van”: “de helft van de klas”.' },
  'de herfst': { fr: 'Un mot en « de » : « de herfst ». Pour dire en automne : « in de herfst ».', en: 'A “de” word: “de herfst”. To say in autumn: “in de herfst”.' },
  'de hesp': { fr: 'Mot flamand. Le nord dit « ham ».', en: 'A Flemish word. The north says “ham”.' },
  'de hobby': { fr: 'Mot venu de l’anglais, mais avec « de » : « de hobby ».', en: 'A word from English, but with “de”: “de hobby”.' },
  'de hoed': { fr: 'Chapeau à bords ; pluriel « de hoeden ».', en: 'A brimmed hat; the plural is “de hoeden”.' },
  'de hoek': { fr: 'Au coin de la rue : « op de hoek » ; le coin d’une pièce se dit « in de hoek ».', en: 'On the street corner: “op de hoek”; the corner of a room is “in de hoek”.' },
  'de hoest': { fr: 'Le verbe est « hoesten » (tousser) ; « de hoest » est le nom.', en: 'The verb is “hoesten” (to cough); “de hoest” is the noun.' },
  'de hond': { fr: 'Pluriel : « honden ». Avec « de », comme « de kat ».', en: 'Plural: “honden”. Takes “de”, like “de kat”.' },
  'de honger': { fr: 'Se construit avec « hebben » : « ik heb honger » (j’ai faim).', en: 'Built with “hebben”: “ik heb honger” (I am hungry).' },
  'de huisarts': { fr: 'Composé de « huis » et « arts » ; c’est le premier médecin qu’on consulte.', en: 'Built from “huis” and “arts”; it is the first doctor you see.' },
  'de hulp': { fr: 'Pour demander de l’aide : « om hulp vragen ».', en: 'To ask for help: “om hulp vragen”.' },
  'de inwoner': { fr: 'Pluriel : « de inwoners » ; pour une femme, on dit « de inwoonster ».', en: 'Plural: “de inwoners”; for a woman, Dutch uses “de inwoonster”.' },
  'de jas': { fr: 'Un seul mot pour les deux, avec « de » ; pluriel « de jassen ».', en: 'One word for both, with “de”; the plural is “de jassen”.' },
  'de jongen': { fr: 'Pluriel « jongens » ; le diminutif est « het jongetje ».', en: 'Plural “jongens”; the diminutive is “het jongetje”.' },
  'de juf': { fr: 'On s’adresse à elle en disant « juf », de la maternelle à la primaire ; un homme est « de meester ».', en: 'Pupils address her as “juf”, from kindergarten through primary school; a man is “de meester”.' },
  'de kaart': { fr: 'En Belgique la carte de débit, c’est « Bancontact » — le mot écrit sur le terminal.', en: 'In Belgium the debit card is “Bancontact”: the word written on the terminal.' },
  'de kaas': { fr: 'Un nom en « de » : « de kaas ». Pluriel : « kazen ».', en: 'A “de” noun: “de kaas”. Plural: “kazen”.' },
  'de kalender': { fr: 'Mot en « de » ; l’agenda de poche se dit « de agenda ».', en: 'A “de” word; the pocket diary is “de agenda”.' },
  'de kamer': { fr: 'Toute pièce, y compris la chambre d’hôtel ; « de slaapkamer » est la chambre à coucher d’un logement.', en: 'Any room, hotel rooms too; “de slaapkamer” is the bedroom of a home.' },
  'de kapper': { fr: 'Désigne la personne comme le salon : « naar de kapper gaan » (aller chez le coiffeur).', en: 'Names the person and the salon: “naar de kapper gaan” (to go to the hairdresser’s).' },
  'de kassa': { fr: 'On paie « aan de kassa » (à la caisse), avec « aan » et non « in ».', en: 'You pay “aan de kassa” (at the checkout), with “aan” and not “in”.' },
  'de kast': { fr: '« De kast » désigne l’armoire comme le placard. Pluriel « de kasten ».', en: '“De kast” covers both a wardrobe and a cupboard. Plural “de kasten”.' },
  'de kat': { fr: 'Pluriel : « katten », avec deux « t ».', en: 'Plural: “katten”, with two “t”.' },
  'de keel': { fr: '« Keelpijn » (mal de gorge) s’écrit en un seul mot.', en: '“Keelpijn” (sore throat) is written as one word.' },
  'de keer': { fr: 'Après un nombre, « keer » reste au singulier : « twee keer ».', en: 'After a number, “keer” stays singular: “twee keer”.' },
  'de kelder': { fr: '« De kelder » : article « de ». Pluriel « de kelders ».', en: '“De kelder”: article “de”. Plural “de kelders”.' },
  'de kerk': { fr: 'Mot en « de » ; le pluriel est « de kerken ».', en: 'A “de” word, and the plural is “de kerken”.' },
  'de kermis': { fr: 'Prend « de » : « de kermis », pas « het kermis ».', en: 'Takes “de”: “de kermis”, not “het kermis”.' },
  'de keuken': { fr: 'Désigne la pièce, mais aussi la cuisine comme art : « de Italiaanse keuken ».', en: 'Means the room, but also cooking as a style: “de Italiaanse keuken”.' },
  'de kinderen': { fr: 'C’est le pluriel de « het kind », mais il prend « de ».', en: 'This is the plural of “het kind”, but it takes “de”.' },
  'de kip': { fr: 'Désigne la poule comme sa viande ; pluriel : « kippen ».', en: 'Covers the bird and its meat; plural: “kippen”.' },
  'de klant': { fr: 'Pluriel « klanten » ; chez le client se dit « bij de klant ».', en: 'Plural “klanten”; at the client’s is “bij de klant”.' },
  'de klas': { fr: 'Pluriel « de klassen », avec un « s » double à l’écrit.', en: 'The plural is “de klassen”, with a doubled “s” in writing.' },
  'de klasgenoot': { fr: 'Pluriel « de klasgenoten ». Mot composé de « de klas » et « de genoot ».', en: 'The plural is “de klasgenoten”. A compound of “de klas” and “de genoot”.' },
  'de kleur': { fr: 'Mot en « de » : « de kleur », pluriel « kleuren ».', en: 'A “de” word: “de kleur”, plural “kleuren”.' },
  'de kleuter': { fr: 'Un enfant d’environ trois à six ans ; pluriel « de kleuters ». L’école est « de kleuterschool ».', en: 'A child of about three to six; the plural is “de kleuters”. The school is “de kleuterschool”.' },
  'de koe': { fr: 'Pluriel : « koeien ». Avec « de ».', en: 'Plural: “koeien”. Takes “de”.' },
  'de koek': { fr: 'Prend « de ». Pluriel : « koeken ».', en: 'Takes “de”. Plural: “koeken”.' },
  'de koffer': { fr: 'Un mot en « de » ; pluriel « koffers ».', en: 'A “de” word; plural “koffers”.' },
  'de koffie': { fr: 'Un nom en « de » : « de koffie ». On commande simplement « een koffie ».', en: 'A “de” noun: “de koffie”. You simply order “een koffie”.' },
  'de koffiekoek': { fr: 'La viennoiserie du matin. Le nord dit « zoet broodje ».', en: 'The morning pastry. The north says “zoet broodje”.' },
  'de komkommer': { fr: 'Prend « de ». Pluriel : « komkommers ».', en: 'Takes “de”. Plural: “komkommers”.' },
  'de koorts': { fr: 'On dit « koorts hebben » (avoir de la fièvre), sans article.', en: 'You say “koorts hebben” (to have a fever), with no article.' },
  'de korting': { fr: 'Pluriel « kortingen ». On obtient une réduction : « korting krijgen ».', en: 'Plural “kortingen”. You get a discount: “korting krijgen”.' },
  'de kousen': { fr: 'Pluriel de « de kous » : une paire se dit « een paar kousen ».', en: 'Plural of “de kous”: a pair is “een paar kousen”.' },
  'de kust': { fr: 'Se dit « aan de kust » (au bord de la mer).', en: 'Said “aan de kust” (at the seaside).' },
  'de laarzen': { fr: 'Pluriel de « de laars », avec un z : « laarzen ».', en: 'Plural of “de laars”, with a z: “laarzen”.' },
  'de lader': { fr: 'Avec « de ». Pour le chargeur d’un téléphone ; « de oplader » existe aussi.', en: 'Takes “de”. For a phone charger; “de oplader” exists too.' },
  'de lamp': { fr: '« De lamp » : article « de ». Pluriel « de lampen ».', en: '“De lamp”: article “de”. Plural “de lampen”.' },
  'de leerkracht': { fr: 'Mot neutre pour tout enseignant, homme ou femme, sans dire « juf » ou « meester ».', en: 'A neutral word for any teacher, man or woman, without saying “juf” or “meester”.' },
  'de leerling': { fr: 'Vaut pour une fille comme pour un garçon, sans changer de forme. Pluriel « de leerlingen ».', en: 'Used for a girl as well as a boy, with no change of form. The plural is “de leerlingen”.' },
  'de lente': { fr: 'Un mot en « de » : « de lente ». Pour dire au printemps : « in de lente ».', en: 'A “de” word: “de lente”. To say in spring: “in de lente”.' },
  'de lepel': { fr: 'Avec « de » : « de lepel ». Le pluriel est « de lepels ».', en: 'Takes “de”: “de lepel”. The plural is “de lepels”.' },
  'de les': { fr: 'Pluriel « de lessen » ; ne le confonds pas avec « de klas », la classe elle-même.', en: 'The plural is “de lessen”; do not mix it up with “de klas”, the room itself.' },
  'de lijn': { fr: 'Avec « de ». Au téléphone : « de lijn is bezet » (c’est occupé).', en: 'Takes “de”. On the phone: “de lijn is bezet” (it is engaged).' },
  'de limonade': { fr: 'En Belgique, « de limonade » désigne toute boisson gazeuse sucrée, pas seulement la limonade.', en: 'In Belgium, “de limonade” means any sweet fizzy drink, not only lemonade.' },
  'de living': { fr: 'Emprunt à l’anglais, courant en Flandre. Aux Pays-Bas, on dit « de woonkamer ».', en: 'Borrowed from English and common in Flanders. In the Netherlands, people say “de woonkamer”.' },
  'de lucht': { fr: '« De lucht » est l’air, et aussi le ciel visible, comme « de hemel ». Seul « de hemel » veut aussi dire le paradis.', en: '“De lucht” is the air, and also the visible sky, as is “de hemel”. Only “de hemel” also means heaven.' },
  'de luchthaven': { fr: 'Un mot en « de » ; pluriel « luchthavens ».', en: 'A “de” word; plural “luchthavens”.' },
  'de maan': { fr: 'Pluriel : « manen ». Avec « de ».', en: 'Plural: “manen”. Takes “de”.' },
  'de maand': { fr: 'Pluriel « maanden » ; ne pas confondre avec « de maan » (la lune).', en: 'The plural is “maanden”; not to be mixed up with “de maan” (the moon).' },
  'de maat': { fr: 'Pour les chaussures, on dit aussi « de schoenmaat » (la pointure).', en: 'For shoes there is also “de schoenmaat” (shoe size).' },
  'de mail': { fr: '« Mailtje » est le diminutif courant d’un message court ou léger.', en: '“Mailtje” is the common diminutive for a short or light message.' },
  'de mama': { fr: '« Moeke » est la forme affectueuse flamande, qu’on dit à sa mère ou à son sujet.', en: '“Moeke” is the affectionate Flemish form, said to one’s mother or about her.' },
  'de man': { fr: 'Pluriel « mannen ». « Mijn man » se dit aussi pour le mari.', en: 'Plural “mannen”. “Mijn man” is also how you say your husband.' },
  'de markt': { fr: '« De markt » est aussi la place centrale d’une ville flamande, où se tenait le marché.', en: '“De markt” is also the central square of a Flemish town, where the market was held.' },
  'de match': { fr: 'La Flandre dit « match » ; le nord dit « wedstrijd ».', en: 'Flanders says “match”; the north says “wedstrijd”.' },
  'de meester': { fr: 'On s’adresse à lui en disant « meester », de la maternelle à la primaire ; une femme est « de juf ».', en: 'Pupils address him as “meester”, from kindergarten through primary school; a woman is “de juf”.' },
  'de melk': { fr: '« De melk » prend « de » ; non dénombrable, sans pluriel courant.', en: '“De melk” takes “de”; it is uncountable, with no usual plural.' },
  'de meneer': { fr: 'Sert aussi à appeler quelqu’un : « Dag, meneer ».', en: 'Also used to address someone: “Dag, meneer”.' },
  'de mening': { fr: 'Pour donner son avis : « naar mijn mening » (à mon avis).', en: 'To give your view: “naar mijn mening” (in my opinion).' },
  'de mensen': { fr: '« Mensen » est le pluriel de « de mens » (la personne, l’être humain).', en: '“Mensen” is the plural of “de mens” (the person, the human being).' },
  'de mevrouw': { fr: 'Sert aussi à interpeller une femme : « Dag, mevrouw ».', en: 'Also used to address a woman: “Dag, mevrouw”.' },
  'de minuut': { fr: 'Pluriel en « -en » : « tien minuten ».', en: 'The plural ends in “-en”: “tien minuten”.' },
  'de moeder': { fr: 'Pluriel « moeders » ; à l’oral, on dit plus souvent « mama ».', en: 'Plural “moeders”; in speech, “mama” is more common.' },
  'de muis': { fr: 'Pluriel : « muizen », avec un « z ».', en: 'Plural: “muizen”, with a “z”.' },
  'de muts': { fr: 'Bonnet en laine ; pour un chapeau à bords, c’est « de hoed ».', en: 'A knitted hat; for a brimmed hat, it is “de hoed”.' },
  'de muur': { fr: '« De muur » : article « de ». Pluriel « de muren ».', en: '“De muur”: article “de”. Plural “de muren”.' },
  'de muziek': { fr: 'Toujours « de muziek », jamais « het muziek ».', en: 'Always “de muziek”, never “het muziek”.' },
  'de naam': { fr: 'C’est un mot en « de », et son pluriel est « de namen ».', en: 'It is a “de” word, and its plural is “de namen”.' },
  'de namiddag': { fr: 'En Flandre, « de middag » est le midi et la pause de table (« over de middag »), donc l’après-midi est « de namiddag ».', en: 'In Flanders “de middag” is noon and the lunch break (“over de middag”), so the afternoon is “de namiddag”.' },
  'de natuur': { fr: 'Presque jamais au pluriel : « natuur » désigne l’ensemble du monde naturel.', en: 'Almost never plural: “natuur” names the natural world as a whole.' },
  'de neef': { fr: 'Un seul mot pour cousin et neveu ; pluriel « neven ».', en: 'One word for male cousin and nephew; plural “neven”.' },
  'de nicht': { fr: 'Un seul mot pour cousine et nièce ; pluriel « nichten ».', en: 'One word for female cousin and niece; plural “nichten”.' },
  'de nonkel': { fr: 'Le mot de Belgique : « de nonkel ». « De oom » est la forme du Nord, qu’on comprend aussi.', en: 'The Belgian word: “de nonkel”. “De oom” is the northern form, understood too.' },
  'de ober': { fr: 'Le serveur en salle est « de ober », une personne. « De server » est la machine, pas la personne.', en: 'The person who waits tables is “de ober”. “De server” is the machine, not the person.' },
  'de oma': { fr: 'Mot familier ; le mot neutre est « grootmoeder ».', en: 'A familiar word; the neutral word is “grootmoeder”.' },
  'de omgeving': { fr: 'Se compose volontiers : « testomgeving » ou « productieomgeving ».', en: 'Readily forms compounds: “testomgeving” or “productieomgeving”.' },
  'de oom': { fr: '« Oom » est la forme du Nord ; en Belgique, on dit aussi « nonkel ».', en: '“Oom” is the northern form; in Belgium, “nonkel” is also said.' },
  'de opa': { fr: 'Mot familier ; le mot neutre est « grootvader ».', en: 'A familiar word; the neutral word is “grootvader”.' },
  'de opdracht': { fr: 'Un travail confié à quelqu’un : « de opdracht », pluriel « de opdrachten ».', en: 'A piece of work given to someone: “de opdracht”, plural “de opdrachten”.' },
  'de opleiding': { fr: 'Un nom en « -ing » tiré d’un verbe prend « de » : « de opleiding », pluriel « de opleidingen ».', en: 'A noun in “-ing” made from a verb takes “de”: “de opleiding”, plural “de opleidingen”.' },
  'de oplossing': { fr: 'Les mots en « -ing » prennent « de » : « de oplossing », pluriel « oplossingen ».', en: 'Words in “-ing” take “de”: “de oplossing”, plural “oplossingen”.' },
  'de opvang': { fr: 'L’accueil des enfants avant et après les cours. Se dit aussi « de buitenschoolse opvang ».', en: 'Care for children before and after lessons. Also called “de buitenschoolse opvang”.' },
  'de ouders': { fr: '« De ouders » sont seulement le père et la mère, pas la famille élargie (« de familie »). Le singulier est « de ouder ».', en: '“De ouders” are only the mother and father, never the wider family (“de familie”). The singular is “de ouder”.' },
  'de oven': { fr: '« De oven » : article « de ». Pluriel « de ovens ».', en: '“De oven”: article “de”. Plural “de ovens”.' },
  'de pannenkoek': { fr: 'Prend « de ». Pluriel : « pannenkoeken ».', en: 'Takes “de”. Plural: “pannenkoeken”.' },
  'de papa': { fr: '« Vake » est la forme familière et affectueuse, surtout entendue en famille.', en: '“Vake” is the familiar, affectionate form, heard mostly within the family.' },
  'de parking': { fr: 'Un mot en « de », pas « het » comme on pourrait le croire : « de parking », au pluriel « de parkings ».', en: 'A “de” word, not “het” as you might guess: “de parking”, plural “de parkings”.' },
  'de pasta': { fr: 'Le verbe reste au singulier, contrairement au français : « de pasta is klaar ».', en: 'The verb stays singular, unlike in French: “de pasta is klaar”.' },
  'de pauze': { fr: 'Écrit avec z, et avec « de » : « de pauze », pluriel « de pauzes ».', en: 'Written with a z, and with “de”: “de pauze”, plural “de pauzes”.' },
  'de pen': { fr: 'Pluriel « de pennen ». Le mot sert aussi pour un stylo à bille.', en: 'The plural is “de pennen”. The word also covers a ballpoint.' },
  'de peper': { fr: 'Prend « de » ; non dénombrable, sans pluriel courant.', en: 'Takes “de”; it is uncountable, with no usual plural.' },
  'de pet': { fr: 'Casquette à visière, à ne pas confondre avec « de muts » ni « de hoed ».', en: 'A peaked cap, not to be mixed up with “de muts” or “de hoed”.' },
  'de pijn': { fr: 'Avec « hebben » : « pijn hebben » (avoir mal). Le pluriel est « pijnen ».', en: 'Used with “hebben”: “pijn hebben” (to be in pain). The plural is “pijnen”.' },
  'de pint': { fr: 'Un « pintje » est un petit verre de bière blonde, 25 ou 33 cl, et non une pinte.', en: 'A “pintje” is a small glass of lager, 25 or 33 cl, not an imperial pint.' },
  'de pistolet': { fr: 'Emprunté au français, gardé en Flandre. Le nord dirait « broodje ».', en: 'Borrowed from French, kept in Flanders. The north would say “broodje”.' },
  'de pizza': { fr: 'Prend « de ». Le pluriel prend une apostrophe avant le s.', en: 'Takes “de”. The plural puts an apostrophe before the s.' },
  'de plank': { fr: '« De plank » : article « de ». Pluriel « de planken ».', en: '“De plank”: article “de”. Plural “de planken”.' },
  'de planning': { fr: 'Avec « de » : « de planning » est le calendrier d’un projet ; le verbe est « plannen ».', en: 'With “de”: “de planning” is a project’s timetable; the verb is “plannen”.' },
  'de plant': { fr: 'Pluriel : « planten ».', en: 'Plural: “planten”.' },
  'de pleister': { fr: 'Pour un plâtre de fracture, on dit « het gips ».', en: 'For a cast on a broken bone, one says “het gips”.' },
  'de ploeg': { fr: '« De ploeg » prend « de », alors que son synonyme « het team » est neutre.', en: '“De ploeg” takes “de”, while its synonym “het team” is neuter.' },
  'de politie': { fr: '« De politie » est singulier : « de politie komt » (la police arrive).', en: '“De politie” is singular: “de politie komt” (the police are coming).' },
  'de post': { fr: '« De post » désigne aussi le courrier, pas seulement le bureau.', en: '“De post” also means the mail, not just the office.' },
  'de printer': { fr: 'Prend « de » : « de printer », pluriel « de printers ».', en: 'Takes “de”: “de printer”, plural “de printers”.' },
  'de pyjama': { fr: 'Un pyjama, haut et bas ensemble, se dit « de pyjama » ; plusieurs : « de pyjama’s ».', en: 'One pair of pyjamas, top and bottom together, is “de pyjama”; several are “de pyjama’s”.' },
  'de receptie': { fr: 'Se dit « aan de receptie » (à l’accueil) ; c’est aussi une réception mondaine.', en: 'Said “aan de receptie” (at the desk); it is also a formal reception.' },
  'de refter': { fr: 'Mot belge : « de refter » est la cantine de l’école ou du travail.', en: 'A Belgian word: “de refter” is the canteen at school or at work.' },
  'de regen': { fr: 'Avec « de » : « de regen ». Le verbe est « regenen ».', en: 'Takes “de”: “de regen”. The verb is “regenen”.' },
  'de reis': { fr: 'Pluriel « reizen » : le s final devient z. Toujours « de reis ».', en: 'Plural “reizen”: the final s becomes z. Always “de reis”.' },
  'de rekening': { fr: 'Au restaurant, on demande « de rekening » pour payer. Le pluriel est « de rekeningen ».', en: 'At a restaurant you ask for “de rekening” to pay. The plural is “de rekeningen”.' },
  'de reservatie': { fr: 'En Belgique, on dit « de reservatie ». Aux Pays-Bas, on dit plutôt « de reservering ».', en: 'In Belgium people say “de reservatie”. In the Netherlands “de reservering” is more usual.' },
  'de richting': { fr: '« De richting » : on dit « in de richting van » pour aller vers un lieu. Le pluriel est « de richtingen ».', en: '“De richting”: you say “in de richting van” for heading towards a place. The plural is “de richtingen”.' },
  'de riem': { fr: 'Avec « de » ; pluriel « de riemen ».', en: 'Takes “de”; the plural is “de riemen”.' },
  'de rijst': { fr: '« De rijst » prend « de » ; non dénombrable, sans pluriel courant.', en: '“De rijst” takes “de”; it is uncountable, with no usual plural.' },
  'de rit': { fr: 'On dit « de rit » pour un trajet en voiture, en « bus » ou à vélo ; le pluriel est « de ritten ».', en: '“De rit” is a ride by car, “bus” or bike; the plural is “de ritten”.' },
  'de rivier': { fr: 'Pluriel : « rivieren ». Avec « de ».', en: 'Plural: “rivieren”. Takes “de”.' },
  'de rok': { fr: 'Attention : « de rok » est la jupe, la robe est « het kleed ».', en: 'Careful: “de rok” is the skirt; the dress is “het kleed”.' },
  'de rotonde': { fr: 'Faux ami : en français, ce mot désigne un bâtiment rond ; ici, c’est un rond-point. Pluriel : « de rotondes ».', en: 'A false friend: in French this word means a round building; here it is a roundabout. Plural: “de rotondes”.' },
  'de rug': { fr: 'Le pluriel est « ruggen », avec deux « g ».', en: 'The plural is “ruggen”, with a doubled “g”.' },
  'de rugzak': { fr: 'Pluriel « rugzakken » (consonne doublée).', en: 'Plural “rugzakken” (doubled consonant).' },
  'de salade': { fr: 'Prend « de ». Pluriel : « salades ».', en: 'Takes “de”. Plural: “salades”.' },
  'de saus': { fr: 'Pluriel : « sauzen », avec un z.', en: 'Plural: “sauzen”, with a z.' },
  'de schaar': { fr: 'Singulier en néerlandais : « de schaar » ; pluriel « de scharen ».', en: 'Singular in Dutch: “de schaar”; the plural is “de scharen”.' },
  'de schoenen': { fr: 'Pluriel de « de schoen » : une paire se dit « een paar schoenen ».', en: 'Plural of “de schoen”: a pair is “een paar schoenen”.' },
  'de school': { fr: 'Mot en « de ». Pluriel « scholen ».', en: 'A “de” word. Plural “scholen”.' },
  'de schoonmoeder': { fr: 'Formé avec « schoon- » : « de schoonvader » est le beau-père.', en: 'Formed with “schoon-”: “de schoonvader” is the father-in-law.' },
  'de server': { fr: 'Pluriel « servers », avec « de » ; le mot s’écrit et se dit comme en anglais.', en: 'Plural “servers”, with “de”; the word is spelled and said as in English.' },
  'de sjaal': { fr: 'Le pluriel prend seulement un s : « de sjaals ».', en: 'The plural takes just an s: “de sjaals”.' },
  'de slaapkamer': { fr: '« De slaapkamer » sert à dormir ; « de kamer » seul désigne n’importe quelle pièce.', en: '“De slaapkamer” is for sleeping; “de kamer” alone is any room.' },
  'de sleutel': { fr: 'Mot en « de » ; le pluriel prend « -s » : « de sleutels ».', en: 'A “de” word, and the plural takes “-s”: “de sleutels”.' },
  'de sms': { fr: 'Avec « de », comme « de gsm ». Pour en envoyer un : « een sms sturen ».', en: 'Takes “de”, like “de gsm”. To send one: “een sms sturen”.' },
  'de soep': { fr: 'Prend « de ». Pluriel : « soepen ».', en: 'Takes “de”. Plural: “soepen”.' },
  'de speeltijd': { fr: 'La pause entre deux cours. La cour elle-même est « de speelplaats ».', en: 'The break between two lessons. The yard itself is “de speelplaats”.' },
  'de spiegel': { fr: '« De spiegel » : article « de ». Pluriel « de spiegels ».', en: '“De spiegel”: article “de”. Plural “de spiegels”.' },
  'de spoed': { fr: 'En Belgique, « de spoed » est le service des urgences ; « spoed » seul désigne ce qui presse.', en: 'In Belgium, “de spoed” is the emergency department; “spoed” alone means urgency.' },
  'de sport': { fr: 'Prend « de » ; pluriel « de sporten ».', en: 'Takes “de”; plural “de sporten”.' },
  'de stad': { fr: 'Pluriel irrégulier : « steden ». On dit « in de stad » (en ville).', en: 'Irregular plural: “steden”. Said “in de stad” (in town).' },
  'de stagiair': { fr: 'Vient du français : « de stagiair », et « de stagiaire » pour une femme.', en: 'From French: “de stagiair”, and “de stagiaire” for a woman.' },
  'de steen': { fr: 'Pluriel : « stenen ». Avec « de ».', en: 'Plural: “stenen”. Takes “de”.' },
  'de ster': { fr: 'Pluriel : « sterren », avec deux « r ».', en: 'Plural: “sterren”, with two “r”.' },
  'de stoel': { fr: '« De stoel » : article « de ». Pluriel « de stoelen ».', en: '“De stoel”: article “de”. Plural “de stoelen”.' },
  'de straat': { fr: 'Une rue prend « in » : « in de …straat » ; « op straat » veut dire dehors. Pluriel : « de straten ».', en: 'A street takes “in”: “in de …straat”; “op straat” means outdoors. Plural: “de straten”.' },
  'de suiker': { fr: '« De suiker » prend « de », mais « het zout » prend « het ».', en: '“De suiker” takes “de”, but “het zout” takes “het”.' },
  'de supermarkt': { fr: 'Composé de « de markt », donc « de » ; pluriel « de supermarkten ».', en: 'Built on “de markt”, so “de”; plural “de supermarkten”.' },
  'de taak': { fr: 'Pluriel à retenir : « de taak », « de taken ».', en: 'Plural to remember: “de taak”, “de taken”.' },
  'de taal': { fr: 'Un mot en « de » ; le pluriel est « talen ».', en: 'A “de” word; the plural is “talen”.' },
  'de taart': { fr: '« Cake » ne désigne que le cake en moule : un gâteau d’anniversaire est aussi une « taart », « verjaardagstaart ».', en: '“Cake” is only the loaf cake: a birthday cake is a “taart” too, “verjaardagstaart”.' },
  'de tafel': { fr: '« De tafel » : article « de ». Pluriel « de tafels ».', en: '“De tafel”: article “de”. Plural “de tafels”.' },
  'de tand': { fr: 'Le pluriel est « tanden » ; le dentiste est « de tandarts ».', en: 'The plural is “tanden”; the dentist is “de tandarts”.' },
  'de tandarts': { fr: 'Composé de « tand » et « arts », comme « de huisarts ».', en: 'Built from “tand” and “arts”, like “de huisarts”.' },
  'de tante': { fr: 'Le pluriel est « tantes » ; le e final se prononce, contrairement au français.', en: 'The plural is “tantes”; the final e is pronounced, unlike in French.' },
  'de taxi': { fr: 'Un mot en « de » ; le pluriel prend une apostrophe avant le s.', en: 'A “de” word; the plural takes an apostrophe before the s.' },
  'de tekening': { fr: 'Pluriel « de tekeningen ». Le verbe est « tekenen ».', en: 'The plural is “de tekeningen”. The verb is “tekenen”.' },
  'de telefoon': { fr: 'Avec « de ». Pour dire que ça sonne : « de telefoon gaat ».', en: 'Takes “de”. For a ringing phone: “de telefoon gaat”.' },
  'de televisie': { fr: 'Pour la regarder : « naar de televisie kijken ».', en: 'To watch it: “naar de televisie kijken”.' },
  'de tent': { fr: 'Pluriel « tenten » ; se dit « in een tent » (sous une tente).', en: 'Plural “tenten”; said “in een tent” (in a tent).' },
  'de test': { fr: 'Article « de », pluriel « testen » : « de test », « de testen ».', en: 'Article “de”, plural “testen”: “de test”, “de testen”.' },
  'de thee': { fr: '« De thee » est non dénombrable ; pour une tasse : « een tas thee » ou « een kop thee ».', en: '“De thee” is uncountable; for a cup: “een tas thee” or “een kop thee”.' },
  'de tiener': { fr: 'Pluriel « tieners » ; un seul mot pour un garçon ou une fille.', en: 'Plural “tieners”; one word for a boy or a girl.' },
  'de toerist': { fr: 'Un mot en « de » ; pluriel « toeristen ».', en: 'A “de” word; plural “toeristen”.' },
  'de toets': { fr: 'Un contrôle à l’école ; « de test » en est un synonyme, mais « de toets » reste le mot scolaire.', en: 'A test in class; “de test” is a synonym, but “de toets” is the usual word at school.' },
  'de tomaat': { fr: 'Prend « de ». Le pluriel se forme avec une finale différente de celle de « appels » : « tomaten ».', en: 'Takes “de”. The plural is formed differently from “appels”: “tomaten”.' },
  'de toren': { fr: 'Pluriel en -s : « de torens ».', en: 'Plural in -s: “de torens”.' },
  'de tram': { fr: 'Le pluriel est « de trams ». En Flandre, on le prend surtout à Anvers, à Gand et sur la côte.', en: 'The plural is “de trams”. In Flanders you mostly ride it in Antwerp, Ghent and along the coast.' },
  'de trap': { fr: '« De trap » : article « de ». Pluriel « de trappen ».', en: '“De trap”: article “de”. Plural “de trappen”.' },
  'de trein': { fr: 'On prend le train : « Ik neem de trein ». Le pluriel est « de treinen ».', en: 'You take the train: “Ik neem de trein”. The plural is “de treinen”.' },
  'de trui': { fr: 'Avec « de », pluriel « de truien ».', en: 'Takes “de”; the plural is “de truien”.' },
  'de tuin': { fr: 'Mot en « de » ; le pluriel est « de tuinen ».', en: 'A “de” word, and the plural is “de tuinen”.' },
  'de uitnodiging': { fr: 'Un nom en « -ing » tiré d’un verbe prend « de » : « uitnodigen » donne « de uitnodiging ».', en: 'A noun in “-ing” made from a verb takes “de”: “uitnodigen” gives “de uitnodiging”.' },
  'de uitstap': { fr: 'Nom en « de » ; on dit « een uitstap maken » (faire une sortie).', en: 'A “de” noun; the phrase is “een uitstap maken” (to go on an outing).' },
  'de vader': { fr: 'Pluriel « vaders » ; à l’oral, on dit plus souvent « papa ».', en: 'Plural “vaders”; in speech, “papa” is more common.' },
  'de vakantie': { fr: 'Singulier en néerlandais : « De kinderen hebben vakantie » (les enfants sont en vacances).', en: 'Singular in Dutch: “De kinderen hebben vakantie” (the children are on holiday).' },
  'de vergadering': { fr: 'Les bureaux flamands disent « meeting » aussi souvent que « vergadering ».', en: 'Flemish offices say “meeting” as often as “vergadering”.' },
  'de verjaardag': { fr: 'Mot en « de ». Le jour même : « Ik ben vandaag jarig » (c’est mon anniversaire).', en: 'A “de” word. On the day: “Ik ben vandaag jarig” (it is my birthday).' },
  'de verpleger': { fr: 'Au féminin : « de verpleegster » ; le terme neutre aujourd’hui est « de verpleegkundige ».', en: 'The feminine is “de verpleegster”; the neutral term today is “de verpleegkundige”.' },
  'de vertraging': { fr: 'Tu l’entendras tous les jours : « tien minuten vertraging ». Le pluriel est « de vertragingen ».', en: 'You will hear it every day: “tien minuten vertraging”. The plural is “de vertragingen”.' },
  'de verwarming': { fr: 'Nom tiré d’un verbe : « verwarmen » donne « de verwarming », au pluriel « de verwarmingen ».', en: 'A noun made from a verb: “verwarmen” gives “de verwarming”, plural “de verwarmingen”.' },
  'de vis': { fr: 'Pluriel : « vissen ». Le mot désigne aussi le poisson dans l’assiette.', en: 'Plural: “vissen”. The word also covers fish on the plate.' },
  'de vlinder': { fr: 'Pluriel : « vlinders ». Avec « de ».', en: 'Plural: “vlinders”. Takes “de”.' },
  'de vloer': { fr: '« De vloer » : article « de ». Pluriel « de vloeren ».', en: '“De vloer”: article “de”. Plural “de vloeren”.' },
  'de vlucht': { fr: 'Pluriel « vluchten ». Signifie aussi la fuite.', en: 'Plural “vluchten”. It also means escape.' },
  'de voet': { fr: 'Le pluriel est « voeten », avec la terminaison « -en ».', en: 'The plural is “voeten”, with the ending “-en”.' },
  'de vogel': { fr: 'Pluriel : « vogels ». Avec « de ».', en: 'Plural: “vogels”. Takes “de”.' },
  'de voormiddag': { fr: 'En Belgique, « de voormiddag » va jusqu’à midi ; vient ensuite « de namiddag ».', en: 'In Belgium, “de voormiddag” runs until noon; then comes “de namiddag”.' },
  'de vork': { fr: 'Avec « de » : « de vork ». Le pluriel est « de vorken ».', en: 'Takes “de”: “de vork”. The plural is “de vorken”.' },
  'de vraag': { fr: 'Pluriel « vragen » ; poser une question se dit « een vraag stellen ».', en: 'Plural “vragen”; to ask one is “een vraag stellen”.' },
  'de vriend': { fr: 'Veut aussi dire petit ami. « Een vriend van mij » reste neutre.', en: 'Also means boyfriend. “Een vriend van mij” stays neutral.' },
  'de vriendin': { fr: 'Pluriel « vriendinnen ». Veut aussi dire petite amie.', en: 'Plural “vriendinnen”. Also means girlfriend.' },
  'de vrouw': { fr: 'Pluriel « vrouwen ». « Mijn vrouw » se dit aussi pour l’épouse.', en: 'Plural “vrouwen”. “Mijn vrouw” is also how you say your wife.' },
  'de wachtzaal': { fr: '« De wachtkamer » s’entend aussi en Flandre, et c’est le mot usuel au nord.', en: '“De wachtkamer” is heard in Flanders too, and is the usual word in the north.' },
  'de wandeling': { fr: 'On dit « een wandeling maken » ; le verbe est « wandelen ».', en: 'The phrase is “een wandeling maken”; the verb is “wandelen”.' },
  'de wasmachine': { fr: 'Mot composé : « de wasmachine » prend l’article du dernier élément, « de machine ». Pluriel « de wasmachines ».', en: 'A compound takes the article of its last part, “de machine”: “de wasmachine”. Plural “de wasmachines”.' },
  'de week': { fr: 'Pluriel « weken » : « twee weken ».', en: 'The plural is “weken”: “twee weken”.' },
  'de werkgever': { fr: 'L’opposé de « de werknemer » : « de werkgever », pluriel « de werkgevers ».', en: 'The opposite of “de werknemer”: “de werkgever”, plural “de werkgevers”.' },
  'de werknemer': { fr: 'L’opposé de « de werkgever » : « de werknemer », pluriel « de werknemers ».', en: 'The opposite of “de werkgever”: “de werknemer”, plural “de werknemers”.' },
  'de werkplek': { fr: 'Mot composé : l’article suit le dernier élément, « de plek », donc « de werkplek ».', en: 'A compound: the article follows the last part, “de plek”, so “de werkplek”.' },
  'de wijk': { fr: '« De wijk » est le quartier comme division de la ville ; « de buurt » est le voisinage proche.', en: '“De wijk” is the neighbourhood as a division of the town; “de buurt” is the close surroundings.' },
  'de wijn': { fr: 'Pluriel : « wijnen » (sortes de vin). Pour un verre : « een glas wijn ».', en: 'Plural: “wijnen” (kinds of wine). For a glass: “een glas wijn”.' },
  'de wind': { fr: 'Le néerlandais le dit aussi avec un verbe : « het waait » (il y a du vent), de « waaien ».', en: 'Dutch also says it with a verb: “het waait” (it is windy), from “waaien”.' },
  'de winkel': { fr: 'Pluriel en « -s » : « winkels ». Faire les magasins se dit « winkelen ».', en: 'Plural in “-s”: “winkels”. To go shopping is “winkelen”.' },
  'de winkelkar': { fr: '« Caddie » vient du français et reste le mot courant en Flandre.', en: '“Caddie” came from French and remains the usual word in Flanders.' },
  'de winter': { fr: 'Mot en « de » ; on dit « in de winter » (en hiver).', en: 'A “de” word; you say “in de winter” (in winter).' },
  'de wolk': { fr: 'Pluriel : « wolken ». Avec « de ».', en: 'Plural: “wolken”. Takes “de”.' },
  'de worst': { fr: 'Prend « de ». Pluriel : « worsten ».', en: 'Takes “de”. Plural: “worsten”.' },
  'de wortel': { fr: 'Pluriel : « wortels ». Le mot signifie aussi la racine.', en: 'Plural: “wortels”. The word also means a root.' },
  'de zee': { fr: 'Un mot en « de » ; pluriel « zeeën », avec un tréma.', en: 'A “de” word; plural “zeeën”, with a diaeresis.' },
  'de zetel': { fr: 'Un mot en « de » : « de zetel », au pluriel « de zetels ». Il couvre le canapé comme le fauteuil.', en: 'A “de” word: “de zetel”, plural “de zetels”. It covers the sofa as well as the armchair.' },
  'de zin': { fr: 'Le pluriel est « zinnen », avec deux n.', en: 'The plural is “zinnen”, with a double n.' },
  'de zolder': { fr: '« De zolder » : article « de ». Pluriel « de zolders ».', en: '“De zolder”: article “de”. Plural “de zolders”.' },
  'de zomer': { fr: 'Mot en « de » ; on dit « in de zomer » (en été).', en: 'A “de” word; you say “in de zomer” (in summer).' },
  'de zon': { fr: 'Ne le confonds pas avec « de zoon » (le fils). Au soleil se dit « in de zon ».', en: 'Do not mix it up with “de zoon” (son). In the sun is “in de zon”.' },
  'de zoon': { fr: 'Pluriel « zonen ». « Zoon » prend « de ».', en: 'Plural “zonen”. “Zoon” takes “de”.' },
  'de zus': { fr: 'En Flandre on dit aussi bien « zus » que « zuster ». Pluriel : « zussen ».', en: 'In Flanders people say both “zus” and “zuster”. The plural is “zussen”.' },
  'december': { fr: 'Sans majuscule ; on dit « in december » (en décembre).', en: 'No capital; you say “in december” (in December).' },
  'denken': { fr: 'Se construit avec « dat » : « Ik denk dat het kan ». Penser à quelqu’un : « denken aan ».', en: 'Takes “dat”: “Ik denk dat het kan”. To think of someone: “denken aan”.' },
  'derde': { fr: 'Pour une date : « de derde januari » (le 3 janvier).', en: 'For a date: “de derde januari” (January 3).' },
  'dertig': { fr: 'Le radical est « der », pas « drie » : « dertig », comme « dertien ».', en: 'The stem is “der”, not “drie”: “dertig”, like “dertien”.' },
  'dichtbij': { fr: '« Kortbij » se dit en Flandre pour dire proche ; le nord préfère « dichtbij ».', en: '“Kortbij” is said in Flanders for near; the north prefers “dichtbij”.' },
  'dik': { fr: 'Double le « k » devant « -e » : « de dikke jas ». Peut aussi dire gros : « een dikke man ».', en: 'Doubles its “k” before “-e”: “de dikke jas”. It can also mean fat: “een dikke man”.' },
  'dikwijls': { fr: 'Comme « vaak », il suit le verbe conjugué : « ik ga dikwijls uit ».', en: 'Like “vaak”, it follows the conjugated verb: “ik ga dikwijls uit”.' },
  'dinsdag': { fr: 'Le plus souvent, le jour se dit seul, comme en français : « Ik kom dinsdag » (je viens mardi) ; « op dinsdag » se dit aussi.', en: 'Most often the day stands alone: “Ik kom dinsdag” (I’m coming on Tuesday); “op dinsdag” is right too.' },
  'doen': { fr: '« Doen » dit une action en général ; « maken » dit qu’on fabrique quelque chose.', en: '“Doen” is for an action in general; “maken” means producing something.' },
  'donderdag': { fr: 'Vient de « donder » (le tonnerre).', en: 'It comes from “donder” (thunder).' },
  'donker': { fr: 'Devient « donkere » devant un nom, mais « een donker bos » (mot « het » après « een »). Aussi d’une couleur foncée : « donkerblauw ».', en: 'Becomes “donkere” before a noun, but “een donker bos” (a “het” word after “een”). Also said of a deep colour: “donkerblauw”.' },
  'door': { fr: '« Door » introduit aussi l’auteur au passif : « gemaakt door mijn moeder » (fait par ma mère).', en: '“Door” also introduces the doer in the passive: “gemaakt door mijn moeder” (made by my mother).' },
  'doorgeven': { fr: 'Verbe séparable : « Ik geef het door » (je le transmets).', en: 'Separable verb: “Ik geef het door” (I will pass it on).' },
  'doorverbinden': { fr: 'Verbe séparable : « Ik verbind u door » (je vous passe la communication).', en: 'Separable verb: “Ik verbind u door” (I will put you through).' },
  'douchen': { fr: 'Verbe régulier : « ik douche ». On dit aussi « een douche nemen » (prendre une douche).', en: 'Regular verb: “ik douche”. People also say “een douche nemen” (to take a shower).' },
  'draaien': { fr: 'Le participe se forme avec « hebben » : « De server heeft de hele nacht gedraaid ».', en: 'The participle takes “hebben”: “De server heeft de hele nacht gedraaid”.' },
  'dragen': { fr: 'Verbe fort : « ik draag », participe « gedragen ».', en: 'Strong verb: “ik draag”, participle “gedragen”.' },
  'drie': { fr: 'Le radical devient « der » dans « dertien » et « dertig ».', en: 'The stem becomes “der” in “dertien” and “dertig”.' },
  'dringend': { fr: 'Sert aussi d’adverbe : « Ik heb dringend hulp nodig » (j’ai urgemment besoin d’aide).', en: 'Also works as an adverb: “Ik heb dringend hulp nodig” (I urgently need help).' },
  'drinken': { fr: '« iets drinken » veut aussi dire prendre un verre avec quelqu’un.', en: '“iets drinken” also means to go for a drink with someone.' },
  'droog': { fr: 'Devient « droge » devant un nom, le double o perdant une lettre : « een droge zomer », mais « een droog jaar » (mot « het » après « een »).', en: 'Becomes “droge” before a noun, the double o losing a letter: “een droge zomer”, but “een droog jaar” (a “het” word after “een”).' },
  'druk': { fr: 'Je suis occupé se dit « ik heb het druk » ; « ik ben druk » veut plutôt dire que l’on est agité.', en: 'I am busy is “ik heb het druk”; “ik ben druk” rather means that one is restless.' },
  'dun': { fr: 'Double le « n » devant « -e » : « de dunne jas ». Contraire de « dik ».', en: 'Doubles its “n” before “-e”: “de dunne jas”. The opposite of “dik”.' },
  'duren': { fr: '« Het duurt een uur » (ça prend une heure). Avec un nom : « De rit duurt een uur ».', en: '“Het duurt een uur” (it takes an hour). With a noun: “De rit duurt een uur”.' },
  'durven': { fr: 'Se construit avec « te » : « Ik durf niet te vragen ».', en: 'Takes “te”: “Ik durf niet te vragen”.' },
  'dus': { fr: 'Après « dus », le verbe peut suivre ou précéder le sujet : « dus ik slaap » ou « dus slaap ik ».', en: 'After “dus”, the verb may follow or precede the subject: “dus ik slaap” or “dus slaap ik”.' },
  'duur': { fr: 'Le contraire est « goedkoop ». « Een dure jas » (un manteau cher), mais après « een » devant un mot en « het » : « een duur huis » (une maison chère).', en: 'The opposite is “goedkoop”. “Een dure jas” (an expensive coat), but after “een” before a “het” word: “een duur huis” (an expensive house).' },
  'echt': { fr: 'Sert d’intensif : « echt leuk ». Adjectif, il s’accorde : « een echte vriend ».', en: 'Works as an intensifier: “echt leuk”. As an adjective it agrees: “een echte vriend”.' },
  'een': { fr: 'Même mot que l’article « een » ; comme chiffre, on l’écrit souvent « één ».', en: 'Same word as the article “een”; as a number it is often written “één”.' },
  'een beetje': { fr: '« Een klein beetje » insiste sur le peu ; les deux formes se disent.', en: '“Een klein beetje” stresses how little; both forms are said.' },
  'een half wit': { fr: 'Exactement ce qu’on dit au comptoir. Ajoute « gesneden » pour le faire trancher.', en: 'Exactly what you say at the counter. Add “gesneden” to have it sliced.' },
  'eenzaam': { fr: '« Eenzaam » dit la solitude pesante ; « alleen » dit simplement être seul.', en: '“Eenzaam” is heavy loneliness; “alleen” simply means being alone.' },
  'eerst': { fr: 'En tête de phrase, le verbe suit aussitôt : « eerst werk ik ».', en: 'At the start of a sentence, the verb follows at once: “eerst werk ik”.' },
  'eerste': { fr: 'Pour une date : « de eerste mei » (le 1er mai).', en: 'For a date: “de eerste mei” (May 1).' },
  'eigenlijk': { fr: 'Adoucit la phrase, souvent au milieu : « Ik wil eigenlijk niet ».', en: 'Softens the sentence, often in the middle: “Ik wil eigenlijk niet”.' },
  'elf': { fr: 'Forme irrégulière, comme « twaalf » ; la série régulière recommence à « dertien ».', en: 'An irregular form, like “twaalf”; the regular series starts again at “dertien”.' },
  'elkaar': { fr: 'Réciproque : « Ze hebben elkaar gezien » (ils se sont vus). Ce n’est pas « zich ».', en: 'Reciprocal: “Ze hebben elkaar gezien” (they saw each other). It is not “zich”.' },
  'elke': { fr: 'Devant un nom en « de » : « elke dag » ; devant un nom en « het » : « elk jaar ».', en: 'Before a “de” noun: “elke dag”; before a “het” noun: “elk jaar”.' },
  'en': { fr: 'Relie deux mots ou deux phrases ; à ne pas confondre avec « een » (un).', en: 'Joins two words or two clauses; not to be mixed up with “een” (a).' },
  'enkele': { fr: 'Se met devant un pluriel : « enkele dagen ». Il désigne moins que « meerdere ».', en: 'Goes before a plural: “enkele dagen”. It means fewer than “meerdere”.' },
  'erg': { fr: 'Comme « heel », il intensifie ; seul, « erg » veut dire grave : « dat is erg ».', en: 'Like “heel” it intensifies; alone, “erg” means serious: “dat is erg”.' },
  'ergens': { fr: 'Même famille que « nergens » et « overal » : « Ik heb het ergens gelezen ».', en: 'Same family as “nergens” and “overal”: “Ik heb het ergens gelezen”.' },
  'eten': { fr: '« eten » est aussi un nom neutre : « het eten » (la nourriture, le repas).', en: '“eten” is also a neuter noun: “het eten” (food, the meal).' },
  'februari': { fr: 'Sans majuscule ; on dit « in februari » (en février).', en: 'No capital; you say “in februari” (in February).' },
  'fietsen': { fr: 'Verbe tiré de « de fiets » : « ik fiets ».', en: 'A verb made from “de fiets”: “ik fiets”.' },
  'gamen': { fr: 'Verbe régulier tiré de l’anglais : « ik game ».', en: 'A regular verb taken from English: “ik game”.' },
  'gebroken': { fr: 'Participe de « breken » employé comme adjectif, pour un os ou un objet ; « kapot » vise plutôt une machine.', en: 'Past participle of “breken” used as an adjective, for a bone or an object; “kapot” is more for a machine.' },
  'gebruiken': { fr: 'Verbe inséparable : le préfixe reste collé, « ik gebruik het » (je l’utilise).', en: 'Inseparable verb: the prefix stays attached, “ik gebruik het” (I use it).' },
  'gedaan': { fr: 'Participe de « doen », mais seul il veut dire fini : « het is gedaan ».', en: 'Participle of “doen”, but on its own it means over: “het is gedaan”.' },
  'geel': { fr: 'Le « ee » devient « e » devant « -e » : « de gele jas ».', en: 'The “ee” becomes “e” before “-e”: “de gele jas”.' },
  'geen': { fr: '« Ik heb geen tijd » : nie un nom avec « een » ou sans article ; « niet » nie le reste.', en: '“Ik heb geen tijd”: negates a noun with “een” or no article; “niet” negates the rest.' },
  'geen probleem': { fr: 'En réponse à un merci, « ’t is niks » est fréquent et plus léger que « geen probleem ».', en: 'Answering thanks, “’t is niks” is common and lighter than “geen probleem”.' },
  'geloven': { fr: '« Ik geloof je » (je te crois). Croire en : « geloven in ».', en: '“Ik geloof je” (I believe you). To believe in: “geloven in”.' },
  'gelukkig': { fr: '« Gelukkig » dit le bonheur durable, mais aussi la chance : seul, il veut dire heureusement.', en: '“Gelukkig” is lasting happiness, but also luck: on its own it means fortunately.' },
  'gemakkelijk': { fr: '« Gemakkelijk » veut aussi dire confortable : « een gemakkelijke stoel » (une chaise confortable).', en: '“Gemakkelijk” also means comfortable: “een gemakkelijke stoel” (a comfortable chair).' },
  'genoeg': { fr: 'Il suit l’adjectif : « groot genoeg » (assez grand), l’inverse du français.', en: 'It follows the adjective: “groot genoeg” (big enough).' },
  'gesloten': { fr: 'Sur la porte d’un magasin on lit « gesloten » ; à l’oral on dit « toe », là où le nord dit plutôt « dicht ».', en: 'Shop doors say “gesloten”; in speech you say “toe”, where the north mostly says “dicht”.' },
  'gesneden': { fr: 'Participe passé de « snijden », employé comme adjectif : « gesneden brood ».', en: 'Past participle of “snijden”, used as an adjective: “gesneden brood”.' },
  'getrouwd': { fr: 'Il s’emploie avec « zijn » : « getrouwd zijn ». Se marier se dit « trouwen ».', en: 'It goes with “zijn”: “getrouwd zijn”. To marry is “trouwen”.' },
  'gevaarlijk': { fr: 'Dérivé de « gevaar » avec « -lijk » ; même forme comme adverbe : « gevaarlijk rijden ».', en: 'Derived from “gevaar” with “-lijk”; same form as an adverb: “gevaarlijk rijden”.' },
  'geven': { fr: 'La personne vient d’abord : « ik geef hem een boek » (je lui donne un livre).', en: 'The person comes first: “ik geef hem een boek” (I give him a book).' },
  'gezellig': { fr: 'Aucun équivalent exact. La chaleur d’être bien ensemble.', en: 'No exact equivalent. The warmth of being comfortable together.' },
  'gisteren': { fr: 'Le verbe suit en deuxième place : « Gisteren was ik laat » (hier j’étais en retard).', en: 'The verb comes second: “Gisteren was ik laat” (yesterday I was late).' },
  'glad': { fr: 'Veut dire lisse ou glissant : « de weg is glad ». Contrairement à l’anglais, il ne veut jamais dire content.', en: 'Means smooth or slippery: “de weg is glad”. Unlike the English word, it never means happy.' },
  'goed': { fr: '« Goed » est à la fois adjectif et adverbe : « het gaat goed » (ça va bien).', en: '“Goed” is both adjective and adverb: “het gaat goed” (it is going well).' },
  'goedkoop': { fr: 'Le contraire de « duur » ; au comparatif, « koop » perd un o : « goedkoper » (moins cher).', en: 'The opposite of “duur”; in the comparative, “koop” loses an o: “goedkoper” (cheaper).' },
  'goeiedag': { fr: 'Le bonjour passe-partout dans un magasin. Le nord dit « goedendag ».', en: 'The all-purpose greeting in a shop. The north says “goedendag”.' },
  'goesting': { fr: 'L’équivalent flamand de « zin ». « Ik heb er geen goesting in » (je n’ai pas envie).', en: 'The Flemish equivalent of “zin”. “Ik heb er geen goesting in” (I do not feel like it).' },
  'graag': { fr: 'Pour dire qu’on aime faire quelque chose, on ajoute « graag » au verbe : « ik zwem graag ».', en: 'To say you like doing something, you add “graag” to the verb: “ik zwem graag”.' },
  'gratis': { fr: 'À ne pas confondre avec « vrij » (libre, disponible) : « ben je vrij? » (tu es libre ?).', en: 'Not to be mixed up with “vrij” (at liberty, not busy): “ben je vrij?” (are you free?).' },
  'grijs': { fr: '« Een grijze jas » (le s devient z), mais après « een » devant un mot en « het » : « een grijs hemd ».', en: '“Een grijze jas” (the s turns into z), but after “een” before a “het” word: “een grijs hemd”.' },
  'groen': { fr: '« De groene trui », mais après « een » devant un mot en « het » : « een groen hemd ». Après le verbe, sans « -e » : « de trui is groen ».', en: '“De groene trui”, but after “een” before a “het” word: “een groen hemd”. After the verb, no “-e”: “de trui is groen”.' },
  'groot': { fr: 'Prend « -e » devant un nom : « de grote man », mais « een groot huis » (mot « het » après « een »). Le double o perd une lettre.', en: 'Takes “-e” before a noun: “de grote man”, but “een groot huis” (a “het” word after “een”). The double o loses a letter.' },
  'haar': { fr: 'Double emploi : complément (« Ik zie haar ») et possessif (« haar boek »).', en: 'Does double duty: object (“Ik zie haar”) and possessive (“haar boek”).' },
  'halen': { fr: 'Sert aussi pour un train : « de trein halen » (attraper le train). Pour apporter, c’est « brengen ».', en: 'Also used for a train: “de trein halen” (to catch the train). To bring something along is “brengen”.' },
  'half': { fr: '« half drie » = 2h30, pas 3h30. C’est une demi-heure AVANT trois heures.', en: '“half drie” = 2.30, not 3.30. It is half an hour BEFORE three o’clock.' },
  'hallo': { fr: 'En Flandre « hey » sert seulement à saluer ; « salut » (comme « dag ») dit bonjour et aussi au revoir.', en: 'In Flanders “hey” only greets; “salut” (like “dag”) says hello and also goodbye.' },
  'hard': { fr: 'Veut aussi dire fort, pour un son : « hard praten » (parler fort). Devant un nom : « harde », mais « een hard bed » (mot « het » après « een »).', en: 'Also means loud, for a sound: “hard praten” (to speak loudly). Before a noun: “harde”, but “een hard bed” (a “het” word after “een”).' },
  'hebben': { fr: '« ik heb », « jij hebt », « hij heeft », « wij hebben ». En flamand : « gij hebt ».', en: '“ik heb”, “jij hebt”, “hij heeft”, “wij hebben”. In Flemish: “gij hebt”.' },
  'heel': { fr: 'Devant un adjectif : « heel mooi ». Au sens d’entier, il s’accorde : « de hele dag ».', en: 'Before an adjective: “heel mooi”. Meaning whole, it agrees: “de hele dag”.' },
  'helemaal': { fr: 'Souvent avec la négation : « helemaal niet » (pas du tout).', en: 'Often used with a negation: “helemaal niet” (not at all).' },
  'helpen': { fr: 'Verbe fort : « hielp » au prétérit et « geholpen » au participe, comme dans « Wordt u al geholpen? » en magasin.', en: 'A strong verb: “hielp” in the past and “geholpen” as participle, as in “Wordt u al geholpen?” in a shop.' },
  'hem': { fr: 'Forme complément, pas sujet : « Ik zie hem ». Le sujet est « hij ».', en: 'Object form, not subject: “Ik zie hem”. The subject is “hij”.' },
  'herhalen': { fr: 'Le participe n’a pas de « ge- » : « halen » donne « gehaald », mais « herhalen » donne « herhaald ».', en: 'The participle takes no “ge-”: “halen” gives “gehaald”, but “herhalen” gives “herhaald”.' },
  'het Engels': { fr: 'Une langue prend une majuscule, et l’article tombe après « spreken » : « ik spreek Engels ».', en: 'A language takes a capital, and the article drops after “spreken”: “ik spreek Engels”.' },
  'het Frans': { fr: 'Une langue prend une majuscule, et l’article tombe après « spreken » : « ik spreek Frans ».', en: 'A language takes a capital, and the article drops after “spreken”: “ik spreek Frans”.' },
  'het Nederlands': { fr: 'Une langue prend une majuscule, et l’article tombe après « spreken » : « ik spreek Nederlands ».', en: 'A language takes a capital, and the article drops after “spreken”: “ik spreek Nederlands”.' },
  'het antwoord': { fr: 'Neutre ; le pluriel « antwoorden » est aussi le verbe.', en: 'Neuter; the plural “antwoorden” is also the verb.' },
  'het avondmaal': { fr: 'Neutre ; on dit aussi « het avondeten ».', en: 'Neuter; people also say “het avondeten”.' },
  'het bed': { fr: 'Attention : « het bed », pas « de ». Pluriel « de bedden ».', en: 'Mind the article: “het bed”, not “de”. Plural “de bedden”.' },
  'het bedrijf': { fr: 'Neutre : « het bedrijf », au pluriel « de bedrijven ».', en: 'Neuter: “het bedrijf”, plural “de bedrijven”.' },
  'het bericht': { fr: 'Avec « het », pluriel « berichten ». « De boodschap » veut aussi dire le message.', en: 'It takes “het”, plural “berichten”. “De boodschap” means a message too.' },
  'het bestek': { fr: 'Nom collectif neutre, au singulier : « het bestek ». Un seul couvert se dit « de vork », « de lepel » ou « het mes ».', en: 'A neuter collective noun, singular: “het bestek”. A single piece is “de vork”, “de lepel” or “het mes”.' },
  'het bier': { fr: '« Het bier » est neutre ; pluriel « bieren » pour des sortes de bière.', en: '“Het bier” is neuter; the plural “bieren” means kinds of beer.' },
  'het blad': { fr: 'Pluriel des feuilles d’arbre : « bladeren ». Aussi une feuille de papier ou une revue.', en: 'Plural for tree leaves: “bladeren”. Also a sheet of paper or a magazine.' },
  'het boek': { fr: 'Neutre : « het boek », pluriel « de boeken ».', en: 'Neuter: “het boek”, plural “de boeken”.' },
  'het bord': { fr: 'Neutre : « het bord ». Le pluriel est « de borden », et le mot désigne aussi un panneau.', en: 'Neuter: “het bord”. The plural is “de borden”, and the word also means a sign.' },
  'het bos': { fr: 'Neutre : « het bos ». Pluriel : « bossen ».', en: 'Neuter: “het bos”. Plural: “bossen”.' },
  'het brood': { fr: 'Un nom en « het » : « het brood », comme « het water ».', en: 'A “het” noun: “het brood”, like “het water”.' },
  'het broodje': { fr: 'Un diminutif en « -je », donc « het » : « het broodje ». Il désigne le petit pain comme le sandwich.', en: 'A diminutive in “-je”, so “het”: “het broodje”. It means the roll as well as the sandwich.' },
  'het buitenland': { fr: 'Neutre et employé au singulier : « in het buitenland » (à l’étranger).', en: 'Neuter and used in the singular: “in het buitenland” (abroad).' },
  'het bureau': { fr: 'Neutre : « het bureau », pluriel « de bureaus ». Pour la pièce, on dit plutôt « het kantoor ».', en: 'Neuter: “het bureau”, plural “de bureaus”. For the room, “het kantoor” is the usual word.' },
  'het café': { fr: 'Neutre, et il garde son accent : « het café ». La boisson, c’est « de koffie ».', en: 'Neuter, and it keeps its accent: “het café”. The drink is “de koffie”.' },
  'het centrum': { fr: 'Neutre : « het centrum », pluriel « de centra ».', en: 'Neuter: “het centrum”, plural “de centra”.' },
  'het concert': { fr: 'Neutre, contrairement à « de muziek » : « het concert ».', en: 'Neuter, unlike “de muziek”: “het concert”.' },
  'het containerpark': { fr: 'Mot flamand. Le nord dit « milieustraat ».', en: 'A Flemish word. The north says “milieustraat”.' },
  'het contract': { fr: 'Ressemble au français, mais il est neutre : « het contract ».', en: 'Looks like French, but it is neuter: “het contract”.' },
  'het dak': { fr: 'Attention : « het dak », pas « de ». Pluriel « de daken ».', en: 'Mind the article: “het dak”, not “de”. Plural “de daken”.' },
  'het dessert': { fr: 'Attention : « het dessert » est neutre, alors que le mot français est masculin.', en: 'Mind the article: “het dessert” is neuter, whereas the French word is masculine.' },
  'het dier': { fr: 'Neutre : « het dier ». Pluriel : « dieren ».', en: 'Neuter: “het dier”. Plural: “dieren”.' },
  'het diploma': { fr: 'Avec « het » ; pluriel « de diploma’s », avec une apostrophe.', en: 'It takes “het”; the plural is “de diploma’s”, with an apostrophe.' },
  'het dorp': { fr: 'Neutre : « het dorp », au pluriel « de dorpen ».', en: 'Neuter: “het dorp”, plural “de dorpen”.' },
  'het eiland': { fr: 'Neutre : « het eiland », pluriel « eilanden ».', en: 'Neuter: “het eiland”, plural “eilanden”.' },
  'het examen': { fr: 'Avec « het », pluriel « de examens » ; l’accent tombe sur « -a- ».', en: 'It takes “het”, and the plural is “de examens”; the stress falls on “-a-”.' },
  'het feest': { fr: 'Mot en « het », le mot général. Pour une soirée dansante de jeunes, on dit « de fuif ».', en: 'A “het” word, the general one. For a young people’s dance party, you say “de fuif”.' },
  'het fietspad': { fr: 'Neutre comme « het pad » ; pluriel « de fietspaden ».', en: 'Neuter like “het pad”; plural “de fietspaden”.' },
  'het fruit': { fr: 'Collectif singulier : « het fruit » est neutre et n’a pas de pluriel courant.', en: 'Collective singular: “het fruit” is neuter and has no usual plural.' },
  'het gebouw': { fr: 'Neutre : « het gebouw », pluriel « de gebouwen ».', en: 'Neuter: “het gebouw”, plural “de gebouwen”.' },
  'het geld': { fr: 'Jamais le métal : celui-ci se dit « zilver », comme dans « een zilveren ring » (une bague en argent).', en: 'Money only, never the metal silver: that is “zilver”, as in “een zilveren ring” (a silver ring).' },
  'het gemeentehuis': { fr: 'Il est « het » comme « huis », son dernier mot. Une ville dit plutôt « het stadhuis ».', en: 'It is “het” like “huis”, its last word. A city says “het stadhuis” instead.' },
  'het gesprek': { fr: 'Avec « het ». Aussi un entretien : « een gesprek met de baas ».', en: 'Takes “het”. Also a formal talk: “een gesprek met de baas”.' },
  'het glas': { fr: 'Neutre : « het glas ». Le pluriel est « de glazen », avec le « s » qui devient « z ».', en: 'Neuter: “het glas”. The plural is “de glazen”, where the “s” becomes “z”.' },
  'het gordijn': { fr: 'Attention : « het gordijn », pas « de ». Pluriel « de gordijnen ».', en: 'Mind the article: “het gordijn”, not “de”. Plural “de gordijnen”.' },
  'het gras': { fr: 'Neutre : « het gras ». Presque toujours au singulier.', en: 'Neuter: “het gras”. Almost always singular.' },
  'het hemd': { fr: 'Attention à l’article : « het hemd », pas « de » ; pluriel « de hemden ».', en: 'Mind the article: “het hemd”, not “de”; the plural is “de hemden”.' },
  'het hoofd': { fr: 'Neutre, donc « het hoofd ». Le pluriel est « hoofden ».', en: 'Neuter, so “het hoofd”. The plural is “hoofden”.' },
  'het hoofdgerecht': { fr: 'Mot composé neutre : « het hoofdgerecht ». Le pluriel est « de hoofdgerechten ».', en: 'A neuter compound: “het hoofdgerecht”. The plural is “de hoofdgerechten”.' },
  'het hotel': { fr: 'Neutre : « het hotel », et non « de ». Pluriel « hotels ».', en: 'Neuter: “het hotel”, not “de”. Plural “hotels”.' },
  'het huis': { fr: '« Het huis » est neutre, alors que la maison est féminine : apprends l’article avec le nom.', en: '“Het huis” is neuter, while the French word for house is feminine: learn the article with the noun.' },
  'het huiswerk': { fr: 'Toujours au singulier en néerlandais, avec « het » : « het huiswerk », jamais « de huiswerken ».', en: 'Always singular in Dutch, with “het”: “het huiswerk”, never “de huiswerken”.' },
  'het ijs': { fr: 'Neutre : « het ijs » désigne aussi l’eau gelée, pas seulement la crème glacée.', en: 'Neuter: “het ijs” also means ice, not only ice cream.' },
  'het jaar': { fr: 'Pluriel : « de jaren », mais après un nombre il reste « jaar » : « vijf jaar ».', en: 'Plural: “de jaren”, but after a number it stays “jaar”: “vijf jaar”.' },
  'het kaartje': { fr: 'C’est un diminutif en « -je », donc « het » : « het kaartje ». On entend aussi « het ticket ».', en: 'A diminutive in “-je”, so “het”: “het kaartje”. You also hear “het ticket”.' },
  'het kantoor': { fr: 'Neutre, pluriel « kantoren » ; sert aussi pour une agence ou un cabinet.', en: 'Neuter, plural “kantoren”; also used for an agency or a practice.' },
  'het kind': { fr: 'Mot en « het », pas « de ». Pluriel irrégulier : « kinderen ».', en: 'A “het” word, not “de”. Irregular plural: “kinderen”.' },
  'het kleed': { fr: 'Le mot prend « het », et non « de » : « het kleed ». En Flandre, c’est le mot courant pour une robe, courte ou longue.', en: 'It takes “het”, not “de”: “het kleed”. In Flanders it is the everyday word for a dress, short or long.' },
  'het konijn': { fr: 'Neutre : « het konijn ». Pluriel : « konijnen ».', en: 'Neuter: “het konijn”. Plural: “konijnen”.' },
  'het kruispunt': { fr: 'Neutre, comme « het punt » ; pluriel « de kruispunten ».', en: 'Neuter, like “het punt”; plural “de kruispunten”.' },
  'het kussen': { fr: 'Attention : « het kussen », pas « de ». Pluriel « de kussens ».', en: 'Mind the article: “het kussen”, not “de”. Plural “de kussens”.' },
  'het kwart': { fr: '« kwart over drie » (3h15) et « kwart voor vier » (3h45).', en: '“kwart over drie” (3.15) and “kwart voor vier” (3.45).' },
  'het land': { fr: '« Het land » est neutre, et non « de ». Le pluriel est « landen ».', en: '“Het land” is neuter, not “de”. The plural is “landen”.' },
  'het loket': { fr: 'Neutre ; pluriel avec deux t : « de loketten ».', en: 'Neuter; plural with two t’s: “de loketten”.' },
  'het loon': { fr: 'Neutre : « het loon », au pluriel « de lonen ».', en: 'Neuter: “het loon”, plural “de lonen”.' },
  'het medicijn': { fr: 'Attention au genre : « het medicijn », et non « de ».', en: 'Mind the gender: “het medicijn”, not “de”.' },
  'het meisje': { fr: 'Un diminutif en « -je », donc « het », même pour une fille.', en: 'A diminutive in “-je”, so “het”, even for a girl.' },
  'het menu': { fr: 'Neutre, contrairement au français : « het menu ». Le pluriel est « de menu’s ».', en: 'Neuter, unlike the French: “het menu”. The plural is “de menu’s”.' },
  'het mes': { fr: 'Neutre : « het mes ». Le pluriel est « de messen », avec le « s » doublé.', en: 'Neuter: “het mes”. The plural is “de messen”, with the “s” doubled.' },
  'het museum': { fr: 'Neutre : « het museum », pluriel « de musea ».', en: 'Neuter: “het museum”, plural “de musea”.' },
  'het ongeval': { fr: 'Neutre : « het ongeval », pluriel « de ongevallen ».', en: 'Neuter: “het ongeval”, plural “de ongevallen”.' },
  'het ontbijt': { fr: 'Neutre : « het ontbijt ». Le verbe est « ontbijten ».', en: 'Neuter: “het ontbijt”. The verb is “ontbijten”.' },
  'het overleg': { fr: 'Neutre et singulier : « het overleg ». Le verbe est « overleggen ».', en: 'Neuter and singular: “het overleg”. The verb is “overleggen”.' },
  'het paard': { fr: 'Neutre : « het paard », pas « de ». Pluriel : « paarden ».', en: 'Neuter: “het paard”, not “de”. Plural: “paarden”.' },
  'het pakje': { fr: 'Diminutif en « -je », donc « het » ; « het pakket » est plus formel, et c’est le mot des Pays-Bas.', en: 'A diminutive in “-je”, so “het”; “het pakket” is more formal, and the Netherlands word.' },
  'het park': { fr: 'Neutre : « het park », pluriel « de parken ».', en: 'Neuter: “het park”, plural “de parken”.' },
  'het paspoort': { fr: 'Neutre : « het paspoort », pluriel « paspoorten ».', en: 'Neuter: “het paspoort”, plural “paspoorten”.' },
  'het perron': { fr: '« Perron » est un faux ami : en français, c’est l’escalier devant un bâtiment, jamais un quai. On désigne aussi le quai par sa voie : « op spoor 3 ».', en: '“Perron” is a false friend: in French it is the steps in front of a building, never a platform. A platform is also given by its track: “op spoor 3”.' },
  'het personeel': { fr: 'Neutre et singulier, même pour plusieurs personnes : « het personeel ».', en: 'Neuter and singular, even for several people: “het personeel”.' },
  'het plafond': { fr: 'Attention : « het plafond », pas « de ». Pluriel « de plafonds ».', en: 'Mind the article: “het plafond”, not “de”. Plural “de plafonds”.' },
  'het plein': { fr: 'Neutre, donc « het plein » ; « de plaats » est l’endroit, pas la place publique.', en: 'Neuter, so “het plein”; “de plaats” is the spot, not the public square.' },
  'het potlood': { fr: 'Avec « het » ; pluriel « de potloden ».', en: 'It takes “het”, and the plural is “de potloden”.' },
  'het probleem': { fr: 'Neutre, pluriel « problemen » : « het probleem », « de problemen ».', en: 'Neuter, plural “problemen”: “het probleem”, “de problemen”.' },
  'het project': { fr: 'Neutre, pluriel « projecten » : « het project », « de projecten ».', en: 'Neuter, plural “projecten”: “het project”, “de projecten”.' },
  'het raam': { fr: 'Attention : « het raam », pas « de ». Pluriel « de ramen ».', en: 'Mind the article: “het raam”, not “de”. Plural “de ramen”.' },
  'het rapport': { fr: 'Avec « het », pluriel « de rapporten » ; ici le bulletin scolaire, mais le mot désigne aussi un rapport écrit, au travail par exemple.', en: 'It takes “het”, and the plural is “de rapporten”; here the school report, but the word also means a written report, at work for example.' },
  'het sap': { fr: 'Neutre : « het sap ». Pluriel : « sappen ».', en: 'Neuter: “het sap”. Plural: “sappen”.' },
  'het schaap': { fr: 'Neutre : « het schaap ». Au pluriel, un seul « a » à l’écrit : « schapen ».', en: 'Neuter: “het schaap”. In the plural, one “a” is dropped in spelling: “schapen”.' },
  'het scherm': { fr: 'Avec « het ». Désigne aussi un paravent ou une protection.', en: 'Takes “het”. Also means a screen as a partition or shield.' },
  'het schrift': { fr: 'Avec « het », et pluriel « de schriften » ; ne le confonds pas avec « het boek ».', en: 'It takes “het”, and the plural is “de schriften”; do not mix it up with “het boek”.' },
  'het seizoen': { fr: 'Mot en « het » ; le pluriel est « de seizoenen ».', en: 'A “het” word; the plural is “de seizoenen”.' },
  'het servet': { fr: 'Neutre : « het servet », pluriel « de servetten ». Ne le confonds pas avec « de handdoek » (la serviette de toilette).', en: 'Neuter: “het servet”, plural “de servetten”. Not to be mixed up with “de handdoek” (the bath towel).' },
  'het speelgoed': { fr: 'Singulier collectif avec « het » : « het speelgoed » ; on n’en fait pas de pluriel.', en: 'A collective singular with “het”: “het speelgoed”, with no plural.' },
  'het spel': { fr: 'Neutre : « het spel » ; pluriel « de spellen ».', en: 'Neuter: “het spel”; plural “de spellen”.' },
  'het spoor': { fr: 'Les annonces disent « spoor 4 » : c’est le chiffre qu’il faut retenir. Attention, « het spoor » est neutre.', en: 'The announcements say “spoor 4”: the number is what you need to catch. Note that “het spoor” is neuter.' },
  'het stadhuis': { fr: 'Neutre, comme « het huis ». Une ville a « het stadhuis », une commune plus petite « het gemeentehuis ».', en: 'Neuter, like “het huis”. A city has “het stadhuis”, a smaller municipality “het gemeentehuis”.' },
  'het station': { fr: 'Gare est féminin, mais c’est « het station », neutre. Le pluriel est « de stations ».', en: 'French gare is feminine, but it is “het station”, neuter. The plural is “de stations”.' },
  'het strand': { fr: 'Neutre : « het strand », pas « de strand ».', en: 'Neuter: “het strand”, not “de strand”.' },
  'het tapijt': { fr: 'Attention : « het tapijt », pas « de ». Pluriel « de tapijten ».', en: 'Mind the article: “het tapijt”, not “de”. Plural “de tapijten”.' },
  'het team': { fr: 'Neutre : « het team », pas « de team ». « De ploeg » dit la même chose.', en: 'Neuter: “het team”, not “de team”. “De ploeg” means the same.' },
  'het telefoonnummer': { fr: 'Composé : l’article suit « nummer », donc « het ».', en: 'A compound takes the article of its last part, “nummer”, so “het”.' },
  'het terras': { fr: 'Contrairement au français, c’est un mot neutre : « het terras ». Le pluriel est « de terrassen ».', en: 'Unlike the French, it is neuter: “het terras”. The plural is “de terrassen”.' },
  'het theater': { fr: 'Neutre : « het theater », et non « de theater ».', en: 'Neuter: “het theater”, not “de theater”.' },
  'het thuiswerk': { fr: '« Telewerk » est le mot belge officiel, employé par les employeurs ; le nord dit « thuiswerk ».', en: '“Telewerk” is the official Belgian word, used by employers; the north says “thuiswerk”.' },
  'het ticket': { fr: 'Neutre, pluriel « tickets » : au travail, c’est la demande suivie dans l’outil ; « het kaartje » sert aussi pour un billet.', en: 'Neuter, plural “tickets”: at work it is the request tracked in the tool; “het kaartje” also serves for a travel or concert ticket.' },
  'het uur': { fr: 'Neutre, donc « het uur » ; sert aussi à dire l’heure : « twee uur ».', en: 'Neuter, so “het uur”; it also gives the time of day: “twee uur”.' },
  'het varken': { fr: 'Neutre : « het varken ». Pluriel : « varkens ».', en: 'Neuter: “het varken”. Plural: “varkens”.' },
  'het verband': { fr: 'Neutre, et le même mot veut aussi dire un lien logique entre deux choses.', en: 'Neuter, and the same word also means a logical link between two things.' },
  'het verkeerslicht': { fr: 'Composé neutre, car « het licht » ; pluriel « de verkeerslichten ».', en: 'A neuter compound, because “het licht”; plural “de verkeerslichten”.' },
  'het verlof': { fr: 'Au travail on prend « verlof » ; les enfants ont « vakantie ».', en: 'At work you take “verlof”; children have “vakantie”.' },
  'het verslag': { fr: 'Neutre, pluriel « verslagen » : un « verslag » est un compte rendu écrit.', en: 'Neuter, plural “verslagen”: a “verslag” is a written account.' },
  'het vlees': { fr: '« Het vlees » est neutre et collectif, sans pluriel courant.', en: '“Het vlees” is neuter and collective, with no usual plural.' },
  'het vliegtuig': { fr: 'Neutre : « het vliegtuig », pluriel « vliegtuigen ».', en: 'Neuter: “het vliegtuig”, plural “vliegtuigen”.' },
  'het voetbal': { fr: 'Neutre : « het voetbal ». Le ballon, lui, est « de bal ».', en: 'Neuter: “het voetbal”. The ball itself is “de bal”.' },
  'het voetpad': { fr: 'Neutre : « het voetpad » ; aux Pays-Bas, on dit généralement « de stoep ».', en: 'Neuter: “het voetpad”; in the Netherlands, people usually say “de stoep”.' },
  'het voorgerecht': { fr: 'Mot composé neutre : « het voorgerecht ». Le pluriel est « de voorgerechten ».', en: 'A neuter compound: “het voorgerecht”. The plural is “de voorgerechten”.' },
  'het voorschrift': { fr: 'Mot flamand. Le nord dit « recept ».', en: 'A Flemish word. The north says “recept”.' },
  'het vuil': { fr: '« Vuilniszak » est le sac-poubelle ; « vuil » désigne les déchets en général.', en: '“Vuilniszak” is the bin bag; “vuil” means rubbish in general.' },
  'het water': { fr: 'Un nom en « het » : « het water », comme « het brood ».', en: 'A “het” noun: “het water”, like “het brood”.' },
  'het weekend': { fr: 'Neutre : « het weekend », et non « de ».', en: 'Neuter: “het weekend”, not “de”.' },
  'het weer': { fr: '« Het weer » prend « het » : « Het is mooi weer » (il fait beau). « Weer » est aussi un adverbe qui veut dire encore : « Het regent weer » (il pleut encore).', en: '“Het weer” takes “het”: “Het is mooi weer” (the weather is nice). “Weer” is also an adverb meaning again: “Het regent weer” (it is raining again).' },
  'het werk': { fr: 'Neutre : « op het werk » (au travail), « naar het werk » (au travail, en y allant). Sur un panneau, le pluriel « werken » annonce des travaux.', en: 'Neuter: “op het werk” (at work), “naar het werk” (to work). On a road sign, the plural “werken” means roadworks.' },
  'het woord': { fr: '« Het woord » est neutre ; le pluriel est « woorden ».', en: '“Het woord” is neuter; the plural is “woorden”.' },
  'het woordenboek': { fr: 'Neutre, comme « het boek » : un composé garde l’article de son dernier mot.', en: 'Neuter, like “het boek”: a compound keeps the article of its last word.' },
  'het zakje': { fr: 'Un diminutif en « -je », donc « het » : « het zakje », comme « het broodje ».', en: 'A diminutive in “-je”, so “het”: “het zakje”, like “het broodje”.' },
  'het zebrapad': { fr: 'Neutre comme « het pad » ; pluriel « de zebrapaden ».', en: 'Neuter like “het pad”; plural “de zebrapaden”.' },
  'het ziekenhuis': { fr: 'Neutre, donc « het ziekenhuis » : littéralement la maison des malades.', en: 'Neuter, so “het ziekenhuis”: literally the house of the sick.' },
  'het zout': { fr: '« Het zout » est neutre, alors que « de suiker » prend « de ».', en: '“Het zout” is neuter, whereas “de suiker” takes “de”.' },
  'het zwembad': { fr: 'Neutre, comme « het bad » ; pluriel « de zwembaden ».', en: 'Neuter, like “het bad”; plural “de zwembaden”.' },
  'heten': { fr: 'Sans pronom réfléchi, contrairement au français : « ik heet », « hij heet ».', en: 'No reflexive pronoun, unlike French: “ik heet”, “hij heet”.' },
  'hier': { fr: 'Faux ami : « hier » veut dire ici, jamais le jour d’avant aujourd’hui, qui se dit « gisteren ».', en: '“Hier” means here, as in English, not yesterday as in French: yesterday is “gisteren”.' },
  'hij': { fr: 'Vaut aussi pour une chose masculine : « de auto » devient « hij », mais « de stad » devient « ze ».', en: 'Also stands for a masculine thing: “de auto” becomes “hij”, but “de stad” becomes “ze”.' },
  'hoe': { fr: 'Aussi devant un adjectif ou un adverbe : « Hoe oud ben je ? » (quel âge as-tu ?).', en: 'Also before an adjective or adverb: “Hoe oud ben je?” (how old are you?).' },
  'hoelang': { fr: 'S’écrit en un mot pour la durée : « Hoelang blijf je ? ».', en: 'Written as one word for duration: “Hoelang blijf je?”.' },
  'hoeveel': { fr: 'Se met devant le nom : « hoeveel mensen ». Pour un prix : « hoeveel kost het ».', en: 'Goes before the noun: “hoeveel mensen”. For a price: “hoeveel kost het”.' },
  'hoeven': { fr: 'S’emploie surtout avec « niet » et « te » : « Je hoeft niet te komen ».', en: 'Used mostly with “niet” and “te”: “Je hoeft niet te komen”.' },
  'honderd': { fr: 'Invariable et soudé au chiffre : « tweehonderd » (deux cents).', en: 'Invariable and written together with the digit word: “tweehonderd” (two hundred).' },
  'hoog': { fr: 'Devient « hoge » devant un nom, mais « een hoog gebouw » (mot « het » après « een »). Pour une personne grande, on dit « groot », pas « hoog ».', en: 'Becomes “hoge” before a noun, but “een hoog gebouw” (a “het” word after “een”). For a tall person, use “groot”, not “hoog”.' },
  'hopen': { fr: 'Comme « denken », avec « dat » : « Ik hoop dat het lukt ».', en: 'Like “denken”, with “dat”: “Ik hoop dat het lukt”.' },
  'hun': { fr: 'Possessif de « zij » (eux) : « hun huis ». Il ne change jamais.', en: 'Possessive of “zij” (they): “hun huis”. It never changes.' },
  'ieder': { fr: '« Iedere » devant un nom en « de » (« iedere dag »), « ieder » devant un nom en « het » (« ieder jaar »).', en: '“Iedere” before a “de” noun (“iedere dag”), “ieder” before a “het” noun (“ieder jaar”).' },
  'iedereen': { fr: 'On salue toute une salle avec « Dag iedereen! » (bonjour tout le monde).', en: 'You greet a whole room with “Dag iedereen!” (hello everyone).' },
  'iemand': { fr: 'Un sujet indéfini appelle souvent « er » : « Er komt iemand » (quelqu’un vient).', en: 'An indefinite subject often takes “er”: “Er komt iemand” (someone is coming).' },
  'iets': { fr: 'Après ce mot, l’adjectif prend un s final : « iets nieuws ».', en: 'After this word the adjective takes a final s: “iets nieuws”.' },
  'ik': { fr: 'Après « ik », le verbe garde son radical nu, sans « t » : « ik werk », « ik woon ».', en: 'After “ik”, the verb keeps its bare stem, with no “t”: “ik werk”, “ik woon”.' },
  'in': { fr: '« In » dit où l’on est : « in de keuken ». Pour où l’on va, on prend « naar » : « naar de keuken ».', en: '“In” says where you are: “in de keuken”. For where you are going, take “naar”: “naar de keuken”.' },
  'inpakken': { fr: 'Verbe séparable : « ik pak mijn koffer in » (je fais ma valise).', en: 'Separable verb: “ik pak mijn koffer in” (I pack my suitcase).' },
  'interessant': { fr: 'Proche du français, avec « voor » : « interessant voor mij » (intéressant pour moi).', en: 'Close to French, with “voor”: “interessant voor mij” (interesting for me).' },
  'ja': { fr: 'Redoublé, « jaja » veut souvent dire « ja, ja, ik weet het » et peut sonner impatient.', en: 'Doubled, “jaja” often means “ja, ja, ik weet het” and can sound impatient.' },
  'jaloers': { fr: '« Jaloers » se construit avec « op » : « jaloers op » (jaloux de).', en: '“Jaloers” takes “op”: “jaloers op” (jealous of).' },
  'jammer': { fr: '« Jammer » commente un regret : « jammer genoeg » (malheureusement). « Spijtig » dit la même chose.', en: '“Jammer” comments on a regret: “jammer genoeg” (unfortunately). “Spijtig” says the same.' },
  'januari': { fr: 'Les mois s’écrivent sans majuscule : « januari », comme « juli ».', en: 'Months are written without a capital: “januari”, like “juli”.' },
  'jarig': { fr: 'Après le verbe, comme attribut : « Ik ben jarig » (c’est mon anniversaire).', en: 'After the verb: “Ik ben jarig” (it is my birthday).' },
  'jezelf': { fr: 'Forme appuyée de « je » : « Jij kent jezelf ». Pour « u », on dit « uzelf ».', en: 'The stressed form of “je”: “Jij kent jezelf”. For “u”, it is “uzelf”.' },
  'jij': { fr: 'En Flandre, « gij » et « ge » remplacent « jij » à l’oral, et le verbe garde son -t même en tête : « hebt ge » là où les Pays-Bas disent « heb je ».', en: 'In Flanders, “gij” and “ge” replace “jij” in speech, and the verb keeps its -t even when it comes first: “hebt ge” where the Netherlands says “heb je”.' },
  'jong': { fr: 'Comparatif « jonger », superlatif « jongst ».', en: 'Comparative “jonger”, superlative “jongst”.' },
  'juli': { fr: 'Facile à confondre avec « juni » à l’oreille : écoute bien la fin du mot.', en: 'Easy to mix up with “juni” by ear: listen to the end of the word.' },
  'juni': { fr: 'Il sonne presque comme « juli » : les deux mois se confondent facilement.', en: 'It sounds almost like “juli”: the two months are easy to mix up.' },
  'kalm': { fr: '« Kalm » dit le calme d’une personne qui ne s’énerve pas ; « stil » dit l’absence de bruit.', en: '“Kalm” is the calm of a person who stays cool; “stil” is the absence of noise.' },
  'kamperen': { fr: 'Verbe régulier : « ik kampeer », « ik heb gekampeerd ».', en: 'A regular verb: “ik kampeer”, “ik heb gekampeerd”.' },
  'kapot': { fr: 'Double le « t » devant « -e » : « een kapotte fiets » (en panne). Pour un os, on préfère « gebroken ».', en: 'Doubles its “t” before “-e”: “een kapotte fiets” (out of order). For a bone, “gebroken” is preferred.' },
  'kennen': { fr: 'Une personne ou un lieu : « Ik ken hem ». Pour un fait, c’est « weten ».', en: 'A person or place: “Ik ken hem”. For a fact, use “weten”.' },
  'kiezen': { fr: 'Irrégulier : « ik kies », puis « Ik heb gekozen ».', en: 'Irregular: “ik kies”, then “Ik heb gekozen”.' },
  'kijken': { fr: 'Pour regarder quelque chose, « naar » : « Ik kijk naar de foto » (je regarde la photo). Un film se regarde sans : « een film kijken ».', en: 'To look at something, “naar”: “Ik kijk naar de foto” (I look at the photo). A film is watched without it: “een film kijken”.' },
  'klaar': { fr: 'Deux prépositions : « klaar met » (fini avec) et « klaar voor » (prêt pour).', en: 'Two prepositions: “klaar met” (finished with) and “klaar voor” (ready for).' },
  'klein': { fr: 'Prend « -e » dans « de kleine tafel ». Sans « -e » après « een » devant un nom en « het » : « een klein kind ».', en: 'Takes “-e” in “de kleine tafel”. No “-e” after “een” before a “het” noun: “een klein kind”.' },
  'kloppen': { fr: '« Dat klopt » (c’est exact). Veut aussi dire frapper : « Er klopt iemand ».', en: '“Dat klopt” (that is right). It also means to knock: “Er klopt iemand”.' },
  'koken': { fr: '« koken » veut dire cuisiner, mais aussi bouillir : « water koken ».', en: '“koken” means to cook but also to boil: “water koken”.' },
  'komen': { fr: '« ik kom » sans -t, mais « hij komt » ; au passé : « hij kwam ».', en: '“ik kom” has no -t, but “hij komt” does; past tense: “hij kwam”.' },
  'kopen': { fr: 'Verbe irrégulier : « ik kocht » au passé, « gekocht » au participe.', en: 'An irregular verb: “ik kocht” in the past, “gekocht” as participle.' },
  'kort': { fr: 'Prend « -e » : « de korte broek ». Se dit aussi d’une durée : « een korte pauze ».', en: 'Takes “-e”: “de korte broek”. Also said of a duration: “een korte pauze”.' },
  'kosten': { fr: 'Le radical finit déjà par « t », donc « het kost » ne prend pas de second « t ».', en: 'The stem already ends in “t”, so “het kost” takes no second “t”.' },
  'koud': { fr: 'Pour dire qu’on a froid : « ik heb het koud », avec « het ».', en: 'To say you feel cold: “ik heb het koud”, with “het”.' },
  'krijgen': { fr: 'Irrégulier au passé : « ik kreeg » et « ik heb gekregen ».', en: 'Irregular in the past: “ik kreeg” and “ik heb gekregen”.' },
  'kunnen': { fr: 'Verbe modal : « ik kan », « jij kunt ». L’infinitif part à la fin de la phrase : « Ik kan komen ».', en: 'Modal verb: “ik kan”, “jij kunt”. The other verb goes to the end: “Ik kan komen”.' },
  'laag': { fr: 'Devient « lage » devant un nom : « een lage tafel », mais « een laag plafond » (mot « het » après « een »). Contraire de « hoog ».', en: 'Becomes “lage” before a noun: “een lage tafel”, but “een laag plafond” (a “het” word after “een”). The opposite of “hoog”.' },
  'laat': { fr: 'Sert aussi à demander l’heure : « Hoe laat is het? » (quelle heure est-il ?).', en: 'Also used to ask the time: “Hoe laat is het?” (what time is it?).' },
  'lachen': { fr: '« Lachen » se construit avec « om » : « lachen om » (rire de).', en: '“Lachen” takes “om”: “lachen om” (to laugh at).' },
  'lang': { fr: 'Contraire de « kort ». Pour une personne, « lang » veut dire grand : « hij is lang » (il est grand).', en: 'The opposite of “kort”. For a person, “lang” means tall: “hij is lang” (he is tall).' },
  'langskomen': { fr: 'Verbe séparable : « ik kom langs » ; participe « langsgekomen ».', en: 'A separable verb: “ik kom langs”; participle “langsgekomen”.' },
  'langzaam': { fr: 'Devient « langzame » devant un nom, mais « een langzaam proces » (mot « het » après « een »). Adverbe inchangé : « hij praat langzaam ».', en: 'Becomes “langzame” before a noun, but “een langzaam proces” (a “het” word after “een”). The adverb is unchanged: “hij praat langzaam”.' },
  'laten': { fr: 'Avec un infinitif, faire faire : « Ik laat mijn fiets maken » (je fais réparer mon vélo).', en: 'With an infinitive it means having something done: “Ik laat mijn fiets maken” (I have my bike fixed).' },
  'leeg': { fr: 'Devient « lege » devant un nom, mais « een leeg glas » (mot « het » après « een »). Après le verbe, inchangé : « de fles is leeg ».', en: 'Becomes “lege” before a noun, but “een leeg glas” (a “het” word after “een”). After the verb it is unchanged: “de fles is leeg”.' },
  'leggen': { fr: '« Leggen » : poser à plat ; poser debout se dit « zetten ».', en: '“Leggen”: lay something flat; to stand it up is “zetten”.' },
  'lekker': { fr: 'En Flandre, « lekker » se dit surtout de ce qu’on mange ou boit ; « lekker weer » est une habitude du nord, ici « mooi weer ».', en: 'In Flanders “lekker” is mostly for what you eat or drink; “lekker weer” is a northern habit, here it is “mooi weer”.' },
  'lelijk': { fr: 'Le contraire de « mooi » ; dit d’une personne, il est direct et peut blesser.', en: 'The opposite of “mooi”; said of a person, it is blunt and can hurt.' },
  'leren': { fr: '« Leren » veut dire aussi enseigner : « hij leert me zwemmen » (il m’apprend à nager).', en: '“Leren” also means to teach: “hij leert me zwemmen” (he teaches me to swim).' },
  'leuk': { fr: '« Leuk » sert pour presque tout ce qui plaît : une soirée, une personne, une idée.', en: '“Leuk” fits almost anything that pleases: an evening, a person, an idea.' },
  'lezen': { fr: 'Verbe fort : « ik lees », mais « ik heb gelezen ».', en: 'A strong verb: “ik lees”, but “ik heb gelezen”.' },
  'licht': { fr: 'Comme nom, « het licht » est la lumière. Adjectif devant un nom : « een lichte tas », mais « een licht pakket » (mot « het » après « een »).', en: 'As a noun, “het licht” is the light. As an adjective before a noun: “een lichte tas”, but “een licht pakket” (a “het” word after “een”).' },
  'lief': { fr: 'Plus affectueux que « vriendelijk » : on le dit surtout d’un enfant ou d’un proche.', en: 'Warmer than “vriendelijk”: mostly said of a child or someone close.' },
  'liggen': { fr: 'Aussi pour un objet posé à plat : « de sleutels liggen in de keuken » (les clés sont dans la cuisine).', en: 'Also for an object lying flat: “de sleutels liggen in de keuken” (the keys are in the kitchen).' },
  'links': { fr: 'Pour indiquer une direction, « links » ne change pas : « Sla links af » (tourne à gauche).', en: 'To give a direction, “links” stays as it is: “Sla links af” (turn left).' },
  'logeren': { fr: 'On dit « logeren bij vrienden » (chez des amis) et « logeren in een hotel » (à l’hôtel).', en: 'You say “logeren bij vrienden” (with friends) and “logeren in een hotel” (at a hotel).' },
  'lopen': { fr: '« Lopen » : courir, ou aller à pied. En Flandre, marcher se dit surtout « stappen ».', en: '“Lopen”: to run, or to go on foot. In Flanders, walking is mostly “stappen”.' },
  'luid': { fr: 'Un son fort se dit « luid » ; « sterk » parle de force physique. Devant un nom : « luide muziek », mais « een luid gesprek » (mot « het » après « een »).', en: 'A loud sound is “luid”; “sterk” is about physical strength. Before a noun: “luide muziek”, but “een luid gesprek” (a “het” word after “een”).' },
  'luisteren': { fr: 'Se construit avec « naar » : « ik luister naar muziek » (j’écoute de la musique).', en: 'Takes “naar”: “ik luister naar muziek” (I listen to music).' },
  'lukken': { fr: 'Le sujet est la chose, pas la personne : « Het lukt me » (j’y arrive).', en: 'The subject is the thing, not the person: “Het lukt me” (I manage).' },
  'maandag': { fr: 'Pas de majuscule en néerlandais, et tous les jours finissent en « dag ».', en: 'No capital letter in Dutch, and every weekday ends in “dag”.' },
  'maar': { fr: 'Relie deux phrases sans changer l’ordre des mots : « Ik wil, maar ik kan niet ».', en: 'Joins two clauses without changing the word order: “Ik wil, maar ik kan niet”.' },
  'maart': { fr: 'Sans majuscule. Ne le confonds pas avec « maar » (mais) : « in maart ».', en: 'No capital. Do not mix it up with “maar” (but): “in maart”.' },
  'maken': { fr: '« Maken » insiste sur ce qu’on produit ; une action sans produit se dit « doen ».', en: '“Maken” stresses what you produce; an action with no product is “doen”.' },
  'meenemen': { fr: 'Verbe séparable : « ik neem mijn laptop mee ». Au comptoir, « om mee te nemen » veut dire à emporter.', en: 'Separable verb: “ik neem mijn laptop mee”. At the counter, “om mee te nemen” means takeaway.' },
  'meer': { fr: 'Comparatif irrégulier de « veel » : « meer », puis « het meest ».', en: 'Irregular comparative of “veel”: “meer”, then “het meest”.' },
  'meerdere': { fr: 'Se met devant un pluriel : « meerdere mensen ». Ne le confonds pas avec « meer ».', en: 'Goes before a plural: “meerdere mensen”. Do not mix it up with “meer”.' },
  'meestal': { fr: 'Après le verbe conjugué (« ik eet meestal thuis »), ou en tête avec le verbe juste derrière : « meestal eet ik thuis ».', en: 'After the conjugated verb (“ik eet meestal thuis”), or first with the verb right behind it: “meestal eet ik thuis”.' },
  'mei': { fr: 'Sans majuscule, et très court : « in mei » (en mai).', en: 'No capital, and short: “in mei” (in May).' },
  'menen': { fr: '« Meen je dat? » (tu es sérieux ?) ou « Ik meen het ».', en: '“Meen je dat?” (are you serious?) or “Ik meen het”.' },
  'met': { fr: '« Met » donne aussi le moyen de transport : « met de trein » (en train).', en: '“Met” also gives the means of transport: “met de trein” (by train).' },
  'meteen': { fr: 'S’écrit en un seul mot : « Ik kom meteen ».', en: 'Written as one word: “Ik kom meteen”.' },
  'mezelf': { fr: 'Forme appuyée de « me » : « Ik ken mezelf ». Le réfléchi simple est « me ».', en: 'The stressed form of “me”: “Ik ken mezelf”. The plain reflexive is “me”.' },
  'mijn': { fr: 'Il ne varie jamais : « mijn naam », « mijn kinderen ».', en: 'It never changes: “mijn naam”, “mijn kinderen”.' },
  'minder': { fr: 'Comparatif de « weinig » : « minder », puis « het minst ».', en: 'Comparative of “weinig”: “minder”, then “het minst”.' },
  'misschien': { fr: 'Il ouvre souvent la phrase, et le verbe vient alors en deuxième : « misschien komt hij ».', en: 'It often opens the sentence, and the verb then comes second: “misschien komt hij”.' },
  'missen': { fr: '« Ik mis je » (tu me manques) : le sujet est celui qui ressent le manque, à l’inverse du français.', en: '“Ik mis je” (I miss you): the subject is the one who feels the lack, the reverse of French.' },
  'moe': { fr: 'Fatigué est « moe » avec « zijn » (« ik ben moe »), mais avoir sommeil prend « hebben » : « ik heb slaap ».', en: 'Tired is “moe” with “zijn” (“ik ben moe”), but sleepy takes “hebben”: “ik heb slaap”.' },
  'moeilijk': { fr: '« Moeilijk » s’oppose à « gemakkelijk » ; « moeilijk doen » veut dire faire des histoires.', en: '“Moeilijk” is the opposite of “gemakkelijk”; “moeilijk doen” means to make a fuss.' },
  'moeten': { fr: 'Modal comme « kunnen » : « ik moet », « jij moet ». L’infinitif part à la fin : « Ik moet werken ».', en: 'Modal like “kunnen”: “ik moet”, “jij moet”. The other verb goes to the end: “Ik moet werken”.' },
  'mogen': { fr: 'La permission, pas la capacité : « Mag ik zitten? ». Pour la capacité, c’est « kunnen ».', en: 'Permission, not ability: “Mag ik zitten?”. For ability, use “kunnen”.' },
  'mooi': { fr: '« Mooi » dit le beau à regarder ; pour ce qui est agréable, on dit « leuk ».', en: '“Mooi” is beauty to look at; for what is pleasant, say “leuk”.' },
  'morgen': { fr: 'Sans article, c’est demain ; « de morgen » (le matin) s’écrit pareil.', en: 'Without an article it is tomorrow; “de morgen” (the morning) is spelled the same.' },
  'na': { fr: '« Na » se place devant l’événement : « na de les ». Pour dire dans combien de temps, c’est « over » : « over twee dagen » (dans deux jours).', en: '“Na” comes before the event you count from: “na de les”. A time from now takes “over”: “over twee dagen” (in two days).' },
  'naar': { fr: '« Naar » suit un verbe de mouvement : « Ik ga naar huis ». Pour être à la maison, on dit « thuis » : « Ik ben thuis » (je suis à la maison).', en: '“Naar” follows a verb of motion: “Ik ga naar huis”. To be at home, say “thuis”: “Ik ben thuis” (I am at home).' },
  'naast': { fr: '« Naast » veut aussi dire en plus de quelque chose : « naast mijn werk » (en plus de mon travail).', en: '“Naast” can also mean in addition to something: “naast mijn werk” (besides my job).' },
  'nat': { fr: 'Son contraire est « droog ».', en: 'Its opposite is “droog”.' },
  'natuurlijk': { fr: '« Tuurlijk » est « natuurlijk » raccourci, courant à l’oral ; à l’écrit on met « natuurlijk ».', en: '“Tuurlijk” is “natuurlijk” clipped, common in speech; in writing use “natuurlijk”.' },
  'nee': { fr: 'Redoublé, « neenee » insiste : un refus net, ou un « nee, nee » pour rassurer.', en: 'Doubled, “neenee” insists: a firm refusal, or a reassuring “nee, nee”.' },
  'negen': { fr: 'Sert de base à « negentig » (nonante).', en: 'It is the base of “negentig” (ninety).' },
  'negentig': { fr: '« negentig » donne nonante en belge, pas quatre-vingt-dix. Un mot pour un mot.', en: '“negentig” matches Belgian French nonante, not quatre-vingt-dix. One word for one word.' },
  'nemen': { fr: 'Irrégulier au passé : « ik nam » et « ik heb genomen ».', en: 'Irregular in the past: “ik nam” and “ik heb genomen”.' },
  'nergens': { fr: 'Nie déjà le lieu, donc pas de « niet » en plus : « Ik zie het nergens ».', en: 'Already negates the place, so no extra “niet”: “Ik zie het nergens”.' },
  'niemand': { fr: 'Sans « niet » : « niemand komt » (personne ne vient).', en: 'No “niet” here: “niemand komt” (nobody comes).' },
  'niet': { fr: 'À l’oral on avale le « t » final : « nie » se dit, « niet » s’écrit.', en: 'In speech the final “t” drops: “nie” is said, “niet” is written.' },
  'niets': { fr: '« Niks » est la forme parlée, très courante.', en: '“Niks” is the spoken form, very common.' },
  'nieuw': { fr: 'Ne pas confondre avec « negen » (le nombre neuf) : en français, neuf a deux sens. Devant un nom : « nieuwe », comme « de nieuwe fiets ».', en: 'Not to be confused with “negen” (the number nine): French has the same word for new and nine. Before a noun it becomes “nieuwe”, as in “de nieuwe fiets”.' },
  'nieuwsgierig': { fr: 'Formé de « nieuws » et « gierig » (avide) : littéralement avide de nouvelles.', en: 'Built from “nieuws” and “gierig” (greedy): literally greedy for news.' },
  'niks': { fr: '« Niks » est familier ; « niets » est plus soigné à l’écrit.', en: '“Niks” is informal; “niets” is more polished in writing.' },
  'nog': { fr: 'Avec « niet » : « nog niet » (pas encore) ; « niet meer » veut dire ne … plus.', en: 'With “niet”: “nog niet” (not yet); “niet meer” means no longer.' },
  'nog eens': { fr: 'À l’oral « eens » devient « is » : on dit « nog is » et on écrit « nog eens ».', en: 'In speech “eens” becomes “is”: you say “nog is” and write “nog eens”.' },
  'nogal': { fr: 'Nuance souvent un peu critique : « nogal duur ».', en: 'Often carries a slightly critical tone: “nogal duur”.' },
  'nooit': { fr: 'Se suffit à lui-même, sans « niet » : « ik drink nooit koffie ».', en: 'It stands alone, without “niet”: “ik drink nooit koffie”.' },
  'november': { fr: 'Sans majuscule ; on dit « in november » (en novembre).', en: 'No capital; you say “in november” (in November).' },
  'nu': { fr: 'Ouvre souvent la phrase, et le verbe suit aussitôt : « Nu ga ik ».', en: 'Often opens the sentence, and the verb follows right after: “Nu ga ik”.' },
  'nul': { fr: 'Pour un score : « twee nul » (deux à zéro).', en: 'For a score: “twee nul” (two nil).' },
  'of': { fr: 'Relie deux choix, ou ouvre une question indirecte : « Ik weet niet of hij komt ».', en: 'Joins two choices, or opens an indirect question: “Ik weet niet of hij komt”.' },
  'oktober': { fr: 'Il s’écrit avec « k », non avec « c » comme en français : « oktober ».', en: 'It is spelled with “k”, not “c”: “oktober”.' },
  'omdat': { fr: 'Même sens que « want », mais le verbe part à la fin : « omdat ik moe ben ».', en: 'Same meaning as “want”, but the verb goes last: “omdat ik moe ben”.' },
  'onder': { fr: '« Onder de tafel » : sous la table ; « onder » veut aussi dire parmi : « onder vrienden ». Pour deux repères, c’est « tussen ».', en: '“Onder de tafel” means under the table; “onder” also means among: “onder vrienden”. For two reference points, it is “tussen”.' },
  'ongeveer': { fr: 'Se met devant le chiffre : « ongeveer tien minuten ».', en: 'Goes before the figure: “ongeveer tien minuten”.' },
  'ontbijten': { fr: 'Non séparable : « ik ontbijt om acht uur ». Le français de Belgique dit aussi déjeuner pour le matin.', en: 'Not separable: “ik ontbijt om acht uur”. Belgian French also says déjeuner for breakfast.' },
  'onthouden': { fr: 'Retenir une information : « Ik onthoud het ». Au passé : « Ik heb het onthouden ».', en: 'To keep a fact in mind: “Ik onthoud het”. Past: “Ik heb het onthouden”.' },
  'onze': { fr: '« Ons » devant un mot « het », « onze » devant les autres : « ons huis », « onze tuin ».', en: '“Ons” before a “het” word, “onze” before the rest: “ons huis”, “onze tuin”.' },
  'ooit': { fr: 'Contraire de « nooit » (jamais) ; dans une question : « ben je ooit ziek geweest ».', en: 'Opposite of “nooit” (never); in a question: “ben je ooit ziek geweest”.' },
  'ook': { fr: 'Moi aussi se dit « ik ook », avec le pronom sujet.', en: 'Me too is “ik ook”, with the subject pronoun.' },
  'op': { fr: '« Op » sert aussi pour les jours : « op maandag » (lundi).', en: '“Op” is used for days too: “op maandag” (on Monday).' },
  'opbellen': { fr: '« Opbellen » est un verbe à particule qui se sépare : « ik bel hem op ». « Bellen » seul n’a pas de particule.', en: '“Opbellen” is a separable verb: “ik bel hem op”. “Bellen” on its own has no particle.' },
  'open': { fr: 'Pas de -e devant un nom : « een open deur », « de open dag » (la journée portes ouvertes).', en: 'No -e before a noun: “een open deur”, “de open dag” (the open day).' },
  'openen': { fr: 'Aussi l’adjectif « open » : « de winkel is open » (le magasin est ouvert).', en: 'Also the adjective “open”: “de winkel is open” (the shop is open).' },
  'ophangen': { fr: 'Verbe séparable : « Ik hang op » (je raccroche).', en: 'Separable verb: “Ik hang op” (I hang up).' },
  'oplossen': { fr: 'Séparable : « Ik los het op », participe « opgelost ».', en: 'Separable: “Ik los het op”, participle “opgelost”.' },
  'opnemen': { fr: 'Verbe séparable : « Ik neem op » (je décroche) ; « antwoorden » répond à une personne.', en: 'Separable verb: “Ik neem op” (I pick up); “antwoorden” answers a person.' },
  'opruimen': { fr: 'Verbe à particule séparable : « ik ruim op ». Participe : « opgeruimd ».', en: 'A separable verb: “ik ruim op”. Past participle: “opgeruimd”.' },
  'opstaan': { fr: 'Verbe séparable : « ik sta om zes uur op ». Le nom est « het opstaan ».', en: 'Separable verb: “ik sta om zes uur op”. The noun is “het opstaan”.' },
  'oranje': { fr: 'Invariable : « de oranje jas », le « -e » final est déjà là.', en: 'Never changes: “de oranje jas”, the final “-e” is already there.' },
  'oud': { fr: 'Pour demander l’âge, on dit « hoe oud » (quel âge), jamais « hoeveel jaar ».', en: 'To ask someone’s age, say “hoe oud” (how old), never “hoeveel jaar”.' },
  'over': { fr: 'Le sujet dont on parle prend « over », pas « van » : « Ik praat over mijn werk » (je parle de mon travail).', en: 'The topic you talk about takes “over”, not “van”: “Ik praat over mijn werk” (I talk about my job).' },
  'overal': { fr: 'Fait la paire avec « nergens » : « Overal is het druk ».', en: 'Pairs with “nergens”: “Overal is het druk”.' },
  'overstappen': { fr: 'Verbe séparable : « Ik stap over ». Il sert pour le train comme pour le « bus ».', en: 'A separable verb: “Ik stap over”. It works for the train as well as the “bus”.' },
  'oversteken': { fr: 'Verbe séparable : « ik steek de straat over » (je traverse la rue).', en: 'Separable verb: “ik steek de straat over” (I cross the street).' },
  'paars': { fr: '« Een paarse broek », mais après « een » devant un mot en « het » : « een paars hemd ».', en: '“Een paarse broek”, but after “een” before a “het” word: “een paars hemd”.' },
  'passen': { fr: 'Pour un vêtement, « passen » : essayer ou aller. Tenter quelque chose se dit « proberen ».', en: 'For clothes, “passen” is to try on or to fit. To attempt something is “proberen”.' },
  'plat': { fr: 'Double le « t » devant « -e » : « een platte band » (un pneu à plat).', en: 'Doubles its “t” before “-e”: “een platte band” (a flat tyre).' },
  'plezant': { fr: 'Calqué sur le français plaisant, un mot typiquement flamand. Le nord dit « leuk ».', en: 'Modelled on French plaisant, a typically Flemish word. The north says “leuk”.' },
  'poetsen': { fr: 'Verbe régulier : « ik poets », « wij poetsen ». Passé : « ik poetste ».', en: 'Regular verb: “ik poets”, “wij poetsen”. Past: “ik poetste”.' },
  'proberen': { fr: 'Suivi d’un autre verbe, il demande « te » : « ik probeer te slapen » (j’essaie de dormir).', en: 'Followed by another verb, it takes “te”: “ik probeer te slapen” (I try to sleep).' },
  'proper': { fr: 'En Flandre, « proper » est le mot courant pour propre : « een propere keuken ». Aux Pays-Bas, on dit plutôt « schoon ».', en: 'In Flanders, “proper” is the usual word for clean: “een propere keuken”. The Netherlands prefers “schoon”.' },
  'raar': { fr: 'Faux ami : pas rare au sens de peu fréquent, qui se dit « zeldzaam ».', en: 'False friend: not rare in the sense of uncommon, which is “zeldzaam”.' },
  'recht': { fr: 'Devient « rechte » devant un nom, mais « een recht pad » (mot « het » après « een »). Aussi adverbe, tout droit : « recht vooruit ».', en: 'Becomes “rechte” before a noun, but “een recht pad” (a “het” word after “een”). Also an adverb, straight ahead: “recht vooruit”.' },
  'rechtdoor': { fr: 'Avec un verbe, il reste un mot à part : « rechtdoor gaan », « Ga rechtdoor ».', en: 'With a verb it stays a separate word: “rechtdoor gaan”, “Ga rechtdoor”.' },
  'rechts': { fr: 'Adverbe invariable : « Ga rechts ». Ne le confonds pas avec « recht » (droit).', en: 'An invariable adverb: “Ga rechts”. Do not mix it up with “recht” (straight).' },
  'regelmatig': { fr: 'Après « een » devant un nom en « het », pas de e final : « een regelmatig bezoek ». Avec « het », on l’ajoute : « het regelmatige bezoek ».', en: 'After “een” before a “het” noun, no final e: “een regelmatig bezoek”. With “het” it is added: “het regelmatige bezoek”.' },
  'reizen': { fr: 'Verbe régulier : « ik reis », participe « gereisd ».', en: 'Regular verb: “ik reis”, participle “gereisd”.' },
  'rekenen': { fr: 'Verbe régulier : « ik reken ». À l’école, « rekenen » est aussi la matière, les maths de base.', en: 'A regular verb: “ik reken”. At school, “rekenen” is also the subject, basic maths.' },
  'reserveren': { fr: 'Présent : « ik reserveer », « wij reserveren ».', en: 'Present: “ik reserveer”, “wij reserveren”.' },
  'rijden': { fr: '« Rijden » vaut pour tout ce qui roule : « De bus rijdt » (circule), « Ik rijd » (je conduis).', en: '“Rijden” covers anything that moves on wheels: “De bus rijdt” (runs), “Ik rijd” (I drive).' },
  'rond': { fr: '« Rond » sert aussi pour une heure approximative : « rond acht uur » (vers huit heures).', en: '“Rond” also gives an approximate time: “rond acht uur” (around eight o’clock).' },
  'rood': { fr: '« Een rode jas », mais après « een » devant un mot en « het » : « een rood hemd ».', en: '“Een rode jas”, but after “een” before a “het” word: “een rood hemd”.' },
  'roze': { fr: '« Roze » ne change jamais : « een roze jas », « de roze jassen ».', en: '“Roze” never changes: “een roze jas”, “de roze jassen”.' },
  'ruilen': { fr: 'Verbe régulier. Échanger contre se dit « ruilen voor » : « ruilen voor een andere maat ».', en: 'A regular verb. To exchange for is “ruilen voor”: “ruilen voor een andere maat”.' },
  'ruim': { fr: 'Se dit d’un espace : « een ruime kamer ». Devant un nombre, il veut dire un peu plus de : « ruim twee uur » (deux bonnes heures).', en: 'Used for a space: “een ruime kamer”. Before a number it means a little over: “ruim twee uur” (a good two hours).' },
  'rusten': { fr: 'Pas de réfléchi en néerlandais : « ik rust », jamais « ik rust me ».', en: 'Not reflexive in Dutch: “ik rust”, never “ik rust me”.' },
  'rustig': { fr: 'Attribut sans terminaison : « de straat is rustig » ; devant un nom, « -e » : « een rustige straat », mais « een rustig dorp » (mot « het » après « een »).', en: 'No ending after the verb: “de straat is rustig”; before a noun, “-e”: “een rustige straat”, but “een rustig dorp” (a “het” word after “een”).' },
  'saai': { fr: 'Le contraire de « leuk » : « een saaie film » ne vaut pas le détour.', en: 'The opposite of “leuk”: “een saaie film” is not worth watching.' },
  'samen': { fr: 'Il ne varie pas ; pour dire avec qui, on ajoute « met » : « samen met ».', en: 'It never changes; to add a person, use “met”: “samen met”.' },
  'samenwerken': { fr: 'Verbe séparable : « ik werk samen », « ik heb samengewerkt ».', en: 'A separable verb: “ik werk samen”, “ik heb samengewerkt”.' },
  'scherp': { fr: 'Se dit d’un couteau ou d’un goût piquant : « een scherp mes ». Aussi net : « een scherpe foto ».', en: 'Used for a knife or a spicy taste: “een scherp mes”. Also crisp in focus: “een scherpe foto”.' },
  'schilderen': { fr: 'Verbe régulier : « ik schilder », « ik heb geschilderd ».', en: 'A regular verb: “ik schilder”, “ik heb geschilderd”.' },
  'schrijven': { fr: 'Verbe fort : « ik schrijf », « ik schreef ».', en: 'Strong verb: “ik schrijf”, “ik schreef”.' },
  'september': { fr: 'Sans majuscule ; on dit « in september » (en septembre).', en: 'No capital; you say “in september” (in September).' },
  'sinds': { fr: 'Suivi d’un point de départ (« sinds gisteren »), le verbe reste au présent.', en: 'Followed by a starting point (“sinds gisteren”), the verb stays in the present.' },
  'slapen': { fr: 'Verbe fort : « sliep » au passé, « geslapen » au participe, et « ik slaap » double le « a ».', en: 'A strong verb: “sliep” in the past, “geslapen” as participle, and “ik slaap” doubles the “a”.' },
  'slecht': { fr: '« Slecht » sert aussi d’adverbe (mal) : « ik voel me slecht » (je me sens mal), « ik slaap slecht » (je dors mal).', en: '“Slecht” is also an adverb (badly): “ik voel me slecht” (I feel unwell), “ik slaap slecht” (I sleep badly).' },
  'sluiten': { fr: 'Sert aussi à conclure : « een contract sluiten » (conclure un contrat).', en: 'Also used for concluding: “een contract sluiten” (to conclude a contract).' },
  'smal': { fr: 'Devient « smalle » devant un nom : « een smalle straat », mais « een smal pad » (mot « het » après « een »). Contraire de « breed ».', en: 'Becomes “smalle” before a noun: “een smalle straat”, but “een smal pad” (a “het” word after “een”). The opposite of “breed”.' },
  'snappen': { fr: 'Familier : « Ik snap het niet ». « Verstaan » est plus neutre.', en: 'Informal: “Ik snap het niet”. “Verstaan” is more neutral.' },
  'snel': { fr: 'Double le « l » devant « -e » : « de snelle trein ». Sert aussi d’adverbe, inchangé : « hij loopt snel ».', en: 'Doubles its “l” before “-e”: “de snelle trein”. Also an adverb, unchanged: “hij loopt snel”.' },
  'sommige': { fr: 'Employé seul pour des personnes, il devient « sommigen » ; pour des choses, « sommige » reste : « sommige zijn duur ».', en: 'Standing alone for people it becomes “sommigen”; for things “sommige” stays: “sommige zijn duur”.' },
  'soms': { fr: 'Après le verbe conjugué (« ik ben soms moe »), ou en tête avec le verbe juste derrière : « soms ben ik moe ».', en: 'After the conjugated verb (“ik ben soms moe”), or first with the verb right behind it: “soms ben ik moe”.' },
  'sorry': { fr: '« Sorry » sert à s’excuser et, avec une intonation montante, à faire répéter.', en: '“Sorry” apologises and, with a rising tone, asks someone to repeat.' },
  'speciaal': { fr: 'Le double a tombe devant un e : « een speciale dag ». Mais « niks speciaals » le garde.', en: 'The double a drops before an e: “een speciale dag”. But “niks speciaals” keeps it.' },
  'spelen': { fr: 'Pas de préposition : « piano spelen », « voetbal spelen » (jouer du piano, jouer au foot).', en: 'No preposition: “piano spelen”, “voetbal spelen” (to play the piano, to play football).' },
  'spijtig': { fr: '« Spijtig » commente un regret : « spijtig genoeg » (malheureusement). « Jammer » dit la même chose.', en: '“Spijtig” comments on a regret: “spijtig genoeg” (unfortunately). “Jammer” says the same.' },
  'sporten': { fr: 'Dérivé de « de sport » : « ik sport », « ik heb gesport ».', en: 'Derived from “de sport”: “ik sport”, “ik heb gesport”.' },
  'spreken': { fr: 'Verbe fort : « ik spreek », « hij sprak », « gesproken ».', en: 'A strong verb: “ik spreek”, “hij sprak”, “gesproken”.' },
  'staan': { fr: 'Dit aussi qu’un objet est là, debout : « de fles staat in de kast » (la bouteille est dans l’armoire).', en: 'Also for an object standing somewhere: “de fles staat in de kast” (the bottle is in the cupboard).' },
  'stappen': { fr: 'En Flandre, « stappen » est le verbe courant pour marcher, alors que « lopen » y veut aussi dire courir.', en: 'In Flanders, “stappen” is the everyday verb for walking, while “lopen” there also means running.' },
  'steeds': { fr: '« Steeds » s’emploie comme « altijd ». Avec « meer », il dit de plus en plus : « steeds meer ».', en: '“Steeds” is used like “altijd”. With “meer” it means more and more: “steeds meer”.' },
  'sterk': { fr: 'Fort au sens de puissant ou solide : « een sterke man ». Pour un son fort, on dit « luid ».', en: 'Strong as in powerful or sturdy: “een sterke man”. For a loud sound, use “luid”.' },
  'stil': { fr: 'Sans bruit : « het is stil ». Pour une personne calme, on dit plutôt « rustig » ou « kalm ».', en: 'Without noise: “het is stil”. For a calm person, “rustig” or “kalm” fits better.' },
  'stofzuigen': { fr: 'Ce verbe ne se sépare pas : « ik stofzuig », « hij stofzuigt », participe « gestofzuigd ».', en: 'This verb does not split: “ik stofzuig”, “hij stofzuigt”, participle “gestofzuigd”.' },
  'stom': { fr: 'Familier et dur dit d’une personne ; plus doux dit d’une chose ou d’une erreur : « een stomme fout ».', en: 'Informal and harsh said of a person; milder said of a thing or a mistake: “een stomme fout”.' },
  'stoppen': { fr: 'Peut aussi vouloir dire mettre dedans : « ik stop het in mijn tas » (je le mets dans mon sac).', en: 'Can also mean to put into: “ik stop het in mijn tas” (I put it in my bag).' },
  'straks': { fr: '« straks » vaut pour l’avenir comme pour le passé, comme tout à l’heure ; « daarnet » ne dit que le passé.', en: '“straks” looks ahead or back, like French tout à l’heure; “daarnet” only means just now.' },
  'streng': { fr: 'Pour une maladie grave, on dit « ernstig », pas « streng » : « een ernstige ziekte ».', en: 'For a serious illness say “ernstig”, not “streng”: “een ernstige ziekte”.' },
  'studeren': { fr: 'Se dit aussi pour réviser une interro, à tout âge, pas seulement à l’université.', en: 'It also means studying for a quiz, at any age, not only at university.' },
  'sturen': { fr: 'Participe passé « gestuurd » : « Ik heb het gestuurd ».', en: 'Past participle “gestuurd”: “Ik heb het gestuurd”.' },
  'te': { fr: 'Se met devant l’adjectif ou l’adverbe : « te duur », « te laat ».', en: 'Goes before an adjective or adverb: “te duur”, “te laat”.' },
  'tegen': { fr: '« Tegen » sert aussi après un verbe de parole : « Ik zeg het tegen hem » (je le lui dis).', en: '“Tegen” is also used after a verb of speaking: “Ik zeg het tegen hem” (I tell him).' },
  'tekenen': { fr: 'Verbe régulier : « ik teken », « ik heb getekend ».', en: 'A regular verb: “ik teken”, “ik heb getekend”.' },
  'terugbellen': { fr: 'Verbe séparable : « Ik bel u terug » (je vous rappelle).', en: 'Separable verb: “Ik bel u terug” (I will call you back).' },
  'terwijl': { fr: 'Conjonction de subordination, donc le verbe part à la fin : « terwijl ik werk ».', en: 'A subordinating word, so the verb goes last: “terwijl ik werk”.' },
  'tevreden': { fr: '« Tevreden » dit une satisfaction calme après un résultat ; « blij » est plus vif.', en: '“Tevreden” is calm satisfaction after a result; “blij” is livelier.' },
  'thuiskomen': { fr: 'Verbe séparable : « ik kom om zes uur thuis ». Le verbe est « komen », « thuis » reste à la fin.', en: 'Separable verb: “ik kom om zes uur thuis”. The verb is “komen”, and “thuis” stays at the end.' },
  'tien': { fr: 'Les nombres de 13 à 19 finissent par « tien » : « dertien ».', en: 'The numbers 13 to 19 end in “tien”: “dertien”.' },
  'toch': { fr: 'Particule d’insistance ; en fin de phrase, il demande confirmation : « je komt toch ».', en: 'Particle of insistence; at the end of a sentence it asks for confirmation: “je komt toch”.' },
  'toen': { fr: 'Au sens de quand, le verbe part à la fin : « Toen ik klein was » ; au sens d’alors, il vient juste après : « Toen ging ik ».', en: 'In the sense of when, the verb goes last: “Toen ik klein was”; in the sense of then, it comes right after: “Toen ging ik”.' },
  'tonen': { fr: 'Se construit avec deux compléments : « ik toon u het plan » (je vous montre le plan). « Laten zien » est un synonyme courant.', en: 'Takes two objects: “ik toon u het plan” (I show you the plan). “Laten zien” is a common synonym.' },
  'tot ziens': { fr: '« Salut » se dit en partant, au magasin comme entre amis ; le nord dit « tot ziens ».', en: '“Salut” is said on leaving, in a shop as among friends; the north says “tot ziens”.' },
  'trager': { fr: '« Trager » est plus courant en Flandre, « langzamer » aux Pays-Bas. C’est le comparatif de « traag ».', en: '“Trager” is more usual in Flanders, “langzamer” in the Netherlands. It is the comparative of “traag”.' },
  'triestig': { fr: '« Triestig » se dit d’une personne comme d’une chose ; pour le chagrin d’une personne, on garde « verdrietig ».', en: '“Triestig” fits a person as well as a thing; for a person’s grief, keep “verdrietig”.' },
  'trots': { fr: '« Trots » se construit avec « op » : « trots op » (fier de).', en: '“Trots” takes “op”: “trots op” (proud of).' },
  'tussen': { fr: '« Tussen » se place devant deux repères : « tussen de zetel en de muur » (entre le canapé et le mur).', en: '“Tussen” goes before two reference points: “tussen de zetel en de muur” (between the sofa and the wall).' },
  'twaalf': { fr: 'Midi se dit « twaalf uur ».', en: 'Noon is “twaalf uur”.' },
  'twee': { fr: 'Après un nombre, « uur » reste au singulier : « twee uur ».', en: 'After a number, “uur” stays singular: “twee uur”.' },
  'tweede': { fr: 'Pour une date : « de tweede juni » (le 2 juin).', en: 'For a date: “de tweede juni” (June 2).' },
  'twijfelen': { fr: 'Avec « aan » : « Ik twijfel aan het plan ». Avec « of » : « Ik twijfel of hij komt ».', en: 'With “aan”: “Ik twijfel aan het plan”. With “of”: “Ik twijfel of hij komt”.' },
  'twintig': { fr: 'L’unité vient d’abord : « eenentwintig » (vingt et un).', en: 'The unit comes first: “eenentwintig” (twenty-one).' },
  'u': { fr: 'La Flandre emploie « u » bien plus que le nord, y compris chez le commerçant.', en: 'Flanders uses “u” far more than the north, including in the shop.' },
  'uit': { fr: 'Pour le pays d’origine, on dit « uit », pas « van » : « Ik kom uit Frankrijk ».', en: 'For your country of origin, use “uit”, not “van”: “Ik kom uit Frankrijk”.' },
  'uitdoen': { fr: 'Verbe séparable : « ik doe mijn schoenen uit ».', en: 'Separable verb: “ik doe mijn schoenen uit”.' },
  'uitgaan': { fr: 'Verbe à particule séparable : « ik ga uit ».', en: 'A separable verb: “ik ga uit”.' },
  'uitleggen': { fr: 'Séparable : « Ik leg het uit », participe « uitgelegd ».', en: 'Separable: “Ik leg het uit”, participle “uitgelegd”.' },
  'uitnodigen': { fr: 'Verbe séparable : « Ik nodig u uit » (je vous invite).', en: 'Separable verb: “Ik nodig u uit” (I invite you).' },
  'uw': { fr: 'En Flandre, « uw » s’emploie aussi familièrement, là où le nord dirait « je ».', en: 'In Flanders, “uw” is also used informally, where the north would say “je”.' },
  'vaak': { fr: 'Comme « dikwijls », il suit le verbe conjugué : « ik ga vaak uit ».', en: 'Like “dikwijls”, it follows the conjugated verb: “ik ga vaak uit”.' },
  'van': { fr: '« Van » marque la possession : « het huis van mijn vader » (la maison de mon père).', en: '“Van” marks possession: “het huis van mijn vader” (my father’s house).' },
  'vandaag': { fr: 'Le verbe suit en deuxième place : « Vandaag heb ik tijd » (aujourd’hui j’ai le temps).', en: 'The verb comes second: “Vandaag heb ik tijd” (today I have time).' },
  'veel': { fr: 'Pas de « van » devant un nom sans article : « veel mensen », « veel water ».', en: 'No “van” before a noun with no article: “veel mensen”, “veel water”.' },
  'veertig': { fr: 'Le radical est « veer », pas « vier ».', en: 'The stem is “veer”, not “vier”.' },
  'vegetarisch': { fr: 'Invariable après « zijn » : « Ik ben vegetarisch ». Devant un nom en « de », il prend un -e : « vegetarische ».', en: 'Unchanged after “zijn”: “Ik ben vegetarisch”. Before a “de” noun it takes an -e: “vegetarische”.' },
  'ver': { fr: 'Adverbe : « Is het ver? ». Le contraire est « dichtbij » ; le comparatif est « verder ».', en: 'An adverb: “Is het ver?”. The opposite is “dichtbij”; the comparative is “verder”.' },
  'verdrietig': { fr: '« Verdrietig » dit le chagrin d’une personne ; « triestig » va aussi bien à une personne qu’à une chose.', en: '“Verdrietig” names a person’s grief; “triestig” fits a person and a thing alike.' },
  'vergaderen': { fr: 'Préfixe inséparable : pas de « ge- » au participe, « hij heeft vergaderd ».', en: 'Inseparable prefix: no “ge-” in the participle, “hij heeft vergaderd”.' },
  'vergeten': { fr: 'Au passé, avec « zijn » : « Ik ben het vergeten ».', en: 'In the past it takes “zijn”: “Ik ben het vergeten”.' },
  'verhuizen': { fr: 'Verbe régulier : « ik verhuis », « wij verhuizen ». Participe : « verhuisd ».', en: 'Regular verb: “ik verhuis”, “wij verhuizen”. Past participle: “verhuisd”.' },
  'verlegen': { fr: '« Verlegen » dit la timidité de caractère ; la honte se dit avec « zich schamen ».', en: '“Verlegen” is shyness of character; shame is said with “zich schamen”.' },
  'verliezen': { fr: 'Irrégulier : « ik verlies » avec un s, mais « ik verloor » et « ik heb verloren ».', en: 'Irregular: “ik verlies” with an s, but “ik verloor” and “ik heb verloren”.' },
  'verplaatsen': { fr: 'Inséparable : « Ik verplaats de afspraak » (je déplace le rendez-vous).', en: 'Not separable: “Ik verplaats de afspraak” (I move the appointment).' },
  'verstaan': { fr: 'En Flandre, « verstaan » sert aussi pour comprendre une idée, là où les Pays-Bas diraient « begrijpen ».', en: 'In Flanders, “verstaan” is also used for understanding an idea, where in the Netherlands you would say “begrijpen”.' },
  'vertalen': { fr: 'Verbe inséparable, accent sur la deuxième syllabe ; participe « vertaald ».', en: 'Inseparable verb, stressed on the second syllable; participle “vertaald”.' },
  'vertellen': { fr: '« Vertellen » raconte une histoire ; « zeggen » rapporte des mots précis.', en: '“Vertellen” recounts a story; “zeggen” reports specific words.' },
  'vertrekken': { fr: 'Verbe à particule inséparable : « de trein vertrekt » au présent, « is vertrokken » au passé composé.', en: 'An inseparable verb: “de trein vertrekt” in the present, “is vertrokken” in the perfect.' },
  'verwachten': { fr: 'S’attendre à : « Ik verwacht regen ». Attendre quelqu’un ou quelque chose se dit « wachten op ».', en: 'To expect: “Ik verwacht regen”. To wait for someone or something is “wachten op”.' },
  'vier': { fr: 'Le radical devient « veer » dans « veertien » et « veertig ».', en: 'The stem becomes “veer” in “veertien” and “veertig”.' },
  'vierde': { fr: 'Pour une date : « de vierde juli » (le 4 juillet).', en: 'For a date: “de vierde juli” (July 4).' },
  'vieren': { fr: 'Verbe régulier : « ik vier ». Il se dit pour une fête : « Kerstmis vieren ».', en: 'A regular verb: “ik vier”. Used for a holiday: “Kerstmis vieren”.' },
  'vijf': { fr: 'S’écrit avec « ij », comme « vijftig ».', en: 'Spelled with “ij”, like “vijftig”.' },
  'vijftig': { fr: 'Se forme directement sur « vijf », sans changement de racine.', en: 'Built straight on “vijf”, with no change of stem.' },
  'vinden': { fr: 'Verbe irrégulier : « vond », « gevonden ». Sert aussi à donner son avis : « ik vind het mooi ».', en: 'An irregular verb: “vond”, “gevonden”. Also gives an opinion: “ik vind het mooi”.' },
  'vliegen': { fr: 'Verbe fort : passé « ik vloog », participe « gevlogen ».', en: 'Strong verb: past “ik vloog”, participle “gevlogen”.' },
  'voelen': { fr: 'Avec un adjectif, il est réfléchi : « ik voel me ziek » (je me sens malade).', en: 'With an adjective it is reflexive: “ik voel me ziek” (I feel ill).' },
  'voetballen': { fr: 'Le football se dit « het voetbal », le ballon « de voetbal » : le verbe vient du premier, d’où « voetballen ».', en: 'Football is “het voetbal”, the ball is “de voetbal”: the verb comes from the first, hence “voetballen”.' },
  'vol': { fr: 'Double le « l » devant « -e » : « de volle tas ». Après le verbe, il reste « vol » : « de tas is vol ».', en: 'Doubles its “l” before “-e”: “de volle tas”. After the verb it stays “vol”: “de tas is vol”.' },
  'volgende': { fr: 'Le e tombe devant un nom en « het » sans article : « volgend jaar », mais « volgende week » et « het volgende weekend ».', en: 'The e drops before a “het” noun with no article: “volgend jaar”, but “volgende week” and “het volgende weekend”.' },
  'voor': { fr: 'Pour le temps écoulé, « voor » ne sert pas : on dit « twee dagen geleden » (il y a deux jours).', en: 'For time gone by, “voor” is not used: say “twee dagen geleden” (two days ago).' },
  'vorig': { fr: 'Un « e » final devant un mot en « de » : « vorige week », mais « vorig jaar ».', en: 'A final “e” before a “de” word: “vorige week”, but “vorig jaar”.' },
  'vragen': { fr: 'Pour demander quelque chose : « vragen om », comme « ik vraag om hulp » (je demande de l’aide).', en: 'To ask for something: “vragen om”, as in “ik vraag om hulp” (I ask for help).' },
  'vriendelijk': { fr: '« Vriendelijk » est aimable et poli, même avec un inconnu ; « lief » est plus tendre.', en: '“Vriendelijk” is kind and polite, even with a stranger; “lief” is warmer.' },
  'vrijdag': { fr: 'S’écrit avec « ij » ; « vrij » veut aussi dire libre.', en: 'Spelled with “ij”; “vrij” also means free.' },
  'vroeg': { fr: 'Contraire de « laat » ; « te vroeg » veut dire trop tôt.', en: 'The opposite of “laat”; “te vroeg” means too early.' },
  'waar': { fr: 'Même famille que « hier » et « daar ». Autre sens : « Dat is waar » (c’est vrai).', en: 'Same family as “hier” and “daar”. Another sense: “Dat is waar” (that is true).' },
  'waarom': { fr: 'La réponse commence par « omdat », pas par « want » : « Omdat ik moe ben ».', en: 'The answer starts with “omdat”, not “want”: “Omdat ik moe ben”.' },
  'wachten': { fr: 'Se construit avec « op » : « ik wacht op u » (je vous attends).', en: 'Takes “op”: “ik wacht op u” (I am waiting for you).' },
  'wandelen': { fr: '« wandelen » se fait à pied, pour le plaisir ; à vélo, c’est « fietsen ».', en: '“wandelen” is on foot, for pleasure; by bike it is “fietsen”.' },
  'wanneer': { fr: 'Pour une question de temps, jamais « als » : « Wanneer kom je ? ».', en: 'For a question about time, never “als”: “Wanneer kom je?”.' },
  'want': { fr: 'Après « want » l’ordre reste normal, après « omdat » le verbe va à la fin.', en: 'After “want” the word order stays normal, after “omdat” the verb goes last.' },
  'warm': { fr: 'Pour dire qu’on a chaud : « ik heb het warm », avec « het ».', en: 'To say you feel hot: “ik heb het warm”, with “het”.' },
  'wat': { fr: '« Wat » demande une chose, « wie » une personne : « Wat is dat ? ».', en: '“Wat” asks about a thing, “wie” about a person: “Wat is dat?”.' },
  'weinig': { fr: 'Se met directement devant le nom, sans « van » : « weinig tijd ».', en: 'Goes straight before the noun, with no “van”: “weinig tijd”.' },
  'wel': { fr: 'Insiste sur le oui, face à un « niet » : « Ik kom wel ».', en: 'Stresses the positive, against a “niet”: “Ik kom wel”.' },
  'welke': { fr: '« Welk » devant un mot « het » au singulier ; « welke » devant un mot « de » ou un pluriel : « welke boeken ».', en: '“Welk” before a singular “het” word; “welke” before a “de” word or a plural: “welke boeken”.' },
  'wenen': { fr: 'Verbe régulier : « ze weent » au présent, « ze heeft geweend » au passé.', en: 'A regular verb: “ze weent” in the present, “ze heeft geweend” in the past.' },
  'werken': { fr: 'Verbe régulier : « ik werk », « hij werkt ». Pour une entreprise, on dit « werken bij ».', en: 'A regular verb: “ik werk”, “hij werkt”. For a company, say “werken bij”.' },
  'weten': { fr: 'Un fait ou une phrase : « Ik weet het ». Pour une personne ou un lieu, c’est « kennen ».', en: 'A fact or a clause: “Ik weet het”. For a person or place, use “kennen”.' },
  'wie': { fr: '« Wie is dat ? » ne se dit que d’une personne ; pour une chose, « wat ».', en: '“Wie is dat?” is only for a person; for a thing, “wat”.' },
  'wij': { fr: 'À l’oral on dit « we » ; « wij » s’emploie pour insister sur le groupe.', en: 'In speech you say “we”; “wij” is for stressing the group.' },
  'willen': { fr: 'Au singulier : « ik wil », « jij wilt ». L’infinitif part à la fin : « Ik wil gaan ».', en: 'Singular: “ik wil”, “jij wilt”. The other verb goes to the end: “Ik wil gaan”.' },
  'wit': { fr: 'La consonne se double devant « -e » : « de witte jas ».', en: 'The consonant doubles before “-e”: “de witte jas”.' },
  'woensdag': { fr: 'Dans « woensdag », le groupe oe se prononce comme ou en français.', en: 'In “woensdag”, the letters oe sound like the oo in moon.' },
  'wonen': { fr: 'Devant une ville, on met « in » : « wonen in ».', en: 'Before a town, use “in”: “wonen in”.' },
  'zacht': { fr: 'Devient « zachte » devant un nom : « een zachte stem » (une voix douce), mais « een zacht kussen » (mot « het » après « een »).', en: 'Becomes “zachte” before a noun: “een zachte stem” (a gentle voice), but “een zacht kussen” (a “het” word after “een”).' },
  'zaterdag': { fr: '« zaterdags » (le samedi, chaque semaine) dit une habitude.', en: '“zaterdags” (on Saturdays, every week) describes a habit.' },
  'zeggen': { fr: 'La personne à qui l’on parle suit « tegen » : « ik zeg het tegen hem » (je le lui dis).', en: 'The person you tell comes after “tegen”: “ik zeg het tegen hem” (I tell him).' },
  'zeker': { fr: 'Répond seul à une question, comme une confirmation : « Zeker ! ».', en: 'Works alone as an answer, a confirmation: “Zeker!”.' },
  'zelden': { fr: 'Contraire de « vaak » ; il suit le verbe conjugué : « ik ga zelden uit ».', en: 'Opposite of “vaak”; it follows the conjugated verb: “ik ga zelden uit”.' },
  'zelf': { fr: 'Renforce le sujet et se place après lui : « Ik doe het zelf ».', en: 'Stresses the subject and comes after it: “Ik doe het zelf”.' },
  'zenuwachtig': { fr: 'Vient de « zenuwen » (les nerfs) : on est « zenuwachtig » avant un examen.', en: 'From “zenuwen” (nerves): you are “zenuwachtig” before an exam.' },
  'zes': { fr: 'La dizaine correspondante est « zestig » (soixante).', en: 'The matching tens word is “zestig” (sixty).' },
  'zetten': { fr: '« Zetten » : poser debout ; à plat, on dit « leggen ».', en: '“Zetten”: set something upright; flat, it is “leggen”.' },
  'zeven': { fr: 'Sert de base à « zeventig » (septante).', en: 'It is the base of “zeventig” (seventy).' },
  'zeventig': { fr: '« zeventig » donne septante en belge, pas soixante-dix ; le belge et le néerlandais se suivent mot pour mot.', en: '“zeventig” and Belgian French septante are both built as seven + ty, unlike the soixante-dix of France.' },
  'zich': { fr: 'Réfléchi de la troisième personne : « Hij wast zich ».', en: 'Reflexive of the third person: “Hij wast zich”.' },
  'ziek': { fr: 'Contraire de « gezond ». Avec « zijn » : « ziek zijn » (être malade).', en: 'The opposite of “gezond”. Used with “zijn”: “ziek zijn” (to be ill).' },
  'zien': { fr: 'Verbe irrégulier : « ik zie », « ik zag », « ik heb gezien ».', en: 'Irregular verb: “ik zie”, “ik zag”, “ik heb gezien”.' },
  'zij': { fr: 'À l’oral on dit « ze » ; « zij » s’emploie pour insister sur la personne.', en: 'In speech you say “ze”; “zij” is for stressing the person.' },
  'zijn': { fr: '« ik ben », « jij bent », « hij is », « wij zijn ». En flamand : « gij zijt ».', en: '“ik ben”, “jij bent”, “hij is”, “wij zijn”. In Flemish: “gij zijt”.' },
  'zingen': { fr: 'Le participe est « gezongen » : « ik heb gezongen ».', en: 'The participle is “gezongen”: “ik heb gezongen”.' },
  'zitten': { fr: 'Dit aussi où quelqu’un se trouve : « ik zit thuis » (je suis chez moi).', en: 'Also says where someone is: “ik zit thuis” (I am at home).' },
  'zodat': { fr: 'S’écrit en un mot, et le verbe part à la fin : « zodat je het weet ».', en: 'Written as one word, and the verb goes last: “zodat je het weet”.' },
  'zoeken': { fr: 'Verbe irrégulier : « zocht », « gezocht ». On dit aussi « zoeken naar » : « ik zoek naar mijn sleutels » (je cherche mes clés).', en: 'Irregular verb: “zocht”, “gezocht”. “Zoeken naar” works too: “ik zoek naar mijn sleutels” (I am looking for my keys).' },
  'zondag': { fr: '« zondag » contient « de zon » (le soleil).', en: '“zondag” holds “de zon” (the sun).' },
  'zonder': { fr: '« Zonder » va avec « te » devant un verbe : « zonder te vragen » (sans demander).', en: '“Zonder” takes “te” before a verb: “zonder te vragen” (without asking).' },
  'zullen': { fr: 'Futur et proposition : « Zal ik helpen? » (je t’aide ?).', en: 'Future and offer: “Zal ik helpen?” (shall I help?).' },
  'zwaar': { fr: 'Devant un nom, il devient « zware » : « een zware dag » (une journée pénible).', en: 'Before a noun it becomes “zware”: “een zware dag” (a hard day).' },
  'zwart': { fr: '« Een zwarte jas », mais après « een » devant un mot en « het » : « een zwart hemd ».', en: '“Een zwarte jas”, but after “een” before a “het” word: “een zwart hemd”.' },
  'zwemmen': { fr: 'Le participe est « gezwommen » : « ik heb gezwommen ».', en: 'The participle is “gezwommen”: “ik heb gezwommen”.' },
};
